  background: var(--row-hover);
}

.workspace-board-add-status .icon {
  width: 13px;
  height: 13px;
}

@container workspace-board (max-width: 900px) {
  .workspace-board-head {
    flex-wrap: wrap;
  }

  .workspace-board-search {
    order: 3;
    width: 100%;
  }

  .workspace-board-actions {
    margin-left: auto;
  }
}

/* One workspace inventory, two arrangements: project rows for reading, and
 * user-owned status lanes for planning. Both use the same cards and actions. */
.workspace-board-head { flex-wrap: wrap; }
.workspace-board-search { flex: 1; width: auto; min-width: min(16em, 100%); }
.workspace-board-overview { display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-3); padding: var(--space-2) var(--space-1) var(--space-4); }
.workspace-board-overview p { margin: 0; color: var(--ink-label); font-size: var(--text-sm); }
/* The accuracy strip: zo's orchestration accuracy for the active project, one
 * chip per rate. Same recipe as .workspace-board-card-host (tokens only). */
.workspace-board-accuracy { display: inline-flex; flex-wrap: wrap; align-items: center; gap: var(--space-2); }
.workspace-board-accuracy-title { color: var(--ink-label); font-size: var(--text-sm); }
.workspace-board-accuracy-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 6px;
  border-radius: var(--radius-sm);
  background: color-mix(in srgb, var(--surface-abyss) 38%, transparent);
  color: var(--ink-mist);
  font-size: var(--text-sm);
}
.workspace-board-accuracy-chip strong { color: var(--ink-figure); }
.workspace-board-accuracy-samples { color: var(--ink-label); font-size: var(--text-sm); }
.workspace-board-layout-controls { display: flex; flex-wrap: wrap; gap: var(--space-2); margin-left: auto; }
.workspace-board-layout-controls[hidden] { display: none; }
.workspace-board-layout-controls .btn { font-size: var(--text-xs); }
.workspace-board-layout-controls .btn[aria-pressed="true"] { background: var(--row-hover); color: var(--ink-chalk); }

.workspace-board-lanes.is-fit {
  grid-auto-flow: row;
  grid-template-columns: repeat(var(--workspace-board-lane-count, 1), minmax(0, 1fr));
  grid-auto-columns: auto;
}
.workspace-board-lanes.is-fit .workspace-board-lane { width: auto; }
.workspace-board-lanes.is-fit .workspace-board-lane-cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 19em), 1fr));
  grid-auto-rows: max-content;
  align-content: start;
  align-items: start;
}
.workspace-board-lanes.is-fit .workspace-board-lane-bottom-add,
.workspace-board-lanes.is-fit .workspace-board-empty { grid-column: 1 / -1; }

.workspace-board-card-title { font-size: var(--text-sm); }
/* A workspace row says three different facts, and each keeps its own mark so
 * none can be mistaken for another (t-3818):
 *
 *   plan          the stage a PERSON set — a hollow square in the stage's colour
 *   activity      what an AGENT is doing — a status dot in the signal colours
 *   verification  changes and review — the PR pill and the doors beside it
 *
 * The stage chip is a door to the stage menu, the changes chip to source
 * control, and the tasks chip to the task board scoped to this checkout. */
.workspace-board-card-stage,
.workspace-board-changes,
.workspace-board-tasks {
  min-height: var(--control-height-sm);
  padding: 0 var(--space-3);
  border: var(--rule-width) solid var(--nav-plane-rule);
  border-radius: var(--radius-pill);
  background: transparent;
  color: var(--ink-label);
  font: inherit;
  font-size: var(--text-xs);
  cursor: pointer;
  transition: color var(--motion-fast) var(--ease-standard), background-color var(--motion-fast) var(--ease-standard);
}
.workspace-board-changes,
.workspace-board-tasks { display: inline-flex; align-items: center; gap: var(--space-2); }
/* The stage chip is a block in list view so its label can ellipsize; one
 * line at the chip's inner height centres it without a flex box. */
.workspace-board-card-stage { line-height: calc(var(--control-height-sm) - var(--rule-width) * 2); }
.workspace-board-card-stage:hover,
.workspace-board-changes:hover,
.workspace-board-tasks:hover,
.workspace-board-project-head:hover { color: var(--ink-chalk); background: var(--row-hover); }
.workspace-board-card-stage::before {
  display: inline-block;
  width: var(--workbench-mark-size);
  height: var(--workbench-mark-size);
  margin-right: var(--space-2);
  border: var(--status-dot-ring) solid var(--workspace-status, var(--edge-mark));
  border-radius: var(--radius-xs);
  vertical-align: middle;
  content: "";
}
.workspace-board-card-live { display: flex; flex-direction: column; gap: var(--space-2); min-width: 0; color: var(--ink-label); font-size: var(--text-xs); }
.workspace-board-card-live strong { display: inline-flex; align-items: center; gap: var(--space-2); font-weight: 500; }
.workspace-board-card-live strong::before {
  flex: none;
  width: var(--status-dot);
  height: var(--status-dot);
  border: var(--status-dot-ring) solid var(--edge-mark);
  border-radius: 50%;
  content: "";
}
.workspace-board-card-live > span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.workspace-board-card-live[data-state="streaming"] strong { color: var(--signal-ready); }
.workspace-board-card-live[data-state="waiting"] strong,
.workspace-board-card-live[data-state="blocked"] strong { color: var(--signal-wait); }
/* Filled while an agent runs, a hollow amber ring while it asks, a filled
 * amber square while a permission holds it — the shape carries the state
 * for a reader who cannot tell the two ambers from a green. */
.workspace-board-card-live[data-state="active"] strong::before { background: var(--edge-mark); }
.workspace-board-card-live[data-state="streaming"] strong::before { border-color: var(--signal-ready); background: var(--signal-ready); }
.workspace-board-card-live[data-state="waiting"] strong::before { border-color: var(--signal-wait); }
.workspace-board-card-live[data-state="blocked"] strong::before {
  border-color: var(--signal-wait);
  border-radius: var(--radius-xs);
  background: var(--signal-wait);
}
.workspace-board-card-git { display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-2); min-width: 0; }
.workspace-board-card-git .board-card-review { max-width: 100%; font-size: var(--text-xs); }
.workspace-board-card-stage,
.workspace-board-card-live { display: none; }

.workspace-board[data-pin-zone="hidden"] .workspace-board-pin { display: none; }
.workspace-board[data-pin-zone="hint"] .workspace-board-pin,
.workspace-board[data-pin-zone="drop"] .workspace-board-pin { display: flex; }
.workspace-board[data-view="list"] .workspace-board-lanes {
  display: block;
  overflow: auto;
  min-width: 0;
  scrollbar-gutter: stable;
}
.workspace-board-project-group { margin-bottom: var(--space-5); min-width: 0; }
.workspace-board-project-head {
  display: block;
  width: 100%;
  padding: var(--space-3) var(--space-2);
  border: 0;
  background: transparent;
  color: var(--ink-chalk);
  font: inherit;
  font-size: var(--text-md);
  font-weight: 600;
  text-align: left;
  cursor: pointer;
  transition: background-color var(--motion-fast) var(--ease-standard), color var(--motion-fast) var(--ease-standard);
}
.workspace-board-project-cards { display: grid; gap: var(--space-2); }
.workspace-board-project-cards[hidden], .workspace-board-columns[hidden] { display: none; }
.workspace-board[data-view="list"] .workspace-board-card,
.workspace-board-columns {
  display: grid;
  grid-template-columns: minmax(0, 1.4fr) minmax(0, 1.7fr) minmax(7em, .7fr) minmax(9em, .8fr);
  gap: var(--space-2) var(--space-4);
  align-items: center;
  padding: var(--space-4);
  min-width: 0;
}
.workspace-board-columns {
  padding-block: var(--space-2);
  border-bottom: var(--rule-width) solid var(--nav-plane-rule);
  color: var(--ink-label);
  font-family: var(--font-display);
  font-size: var(--text-2xs);
  font-weight: 600;
  letter-spacing: var(--workbench-eyebrow-tracking);
  text-transform: uppercase;
}
.workspace-board[data-view="list"] .workspace-board-card { margin: 0; contain-intrinsic-size: auto 6em; }
.workspace-board[data-view="list"] .workspace-board-card-top { grid-column: 1; grid-row: 1; }
.workspace-board[data-view="list"] .workspace-board-card-meta { grid-column: 1; grid-row: 2; }
.workspace-board[data-view="list"] .workspace-board-card-live { display: flex; grid-column: 2; grid-row: 1 / 3; }
.workspace-board[data-view="list"] .workspace-board-card-stage { display: block; grid-column: 3; grid-row: 1 / 3; justify-self: start; max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.workspace-board[data-view="list"] .workspace-board-card-git { grid-column: 4; grid-row: 1 / 3; }
.workspace-board[data-view="list"] .workspace-board-card-agents { display: none; }
.workspace-board[data-view="list"] .workspace-board-card-project { display: none; }
.workspace-board[data-view="list"] .is-pinned .workspace-board-card-project { display: inline-flex; }
.workspace-board[data-view="list"] .workspace-board-card-title { white-space: normal; overflow-wrap: anywhere; line-height: 1.5; }
.workspace-board[data-view="list"] .workspace-board-card-menu { opacity: 1; }
.workspace-board[data-view="list"] .workspace-board-card:hover { transform: none; }

@container workspace-board (max-width: 1050px) {
  .workspace-board-lanes.is-fit {
    grid-template-columns: repeat(auto-fit, minmax(min(100%, var(--workspace-board-column-width)), 1fr));
    grid-auto-rows: minmax(20em, 1fr);
    overflow-y: auto;
  }
}
@container workspace-board (max-width: 800px) {
  .workspace-board[data-view="list"] .workspace-board-card { grid-template-columns: minmax(0, 1fr) auto; }
  .workspace-board[data-view="list"] .workspace-board-card-top { grid-column: 1; grid-row: 1; }
  .workspace-board[data-view="list"] .workspace-board-card-meta { grid-column: 1; grid-row: 2; }
  .workspace-board[data-view="list"] .workspace-board-card-live { grid-column: 1 / -1; grid-row: 3; }
  .workspace-board[data-view="list"] .workspace-board-card-stage { grid-column: 2; grid-row: 1 / 3; max-width: 10em; }
  .workspace-board[data-view="list"] .workspace-board-card-git { grid-column: 1 / -1; grid-row: 4; }
  .workspace-board-columns { display: none; }
}
@container workspace-board (max-width: 420px) {
  .workspace-board-head { padding: var(--space-3); gap: var(--space-2); }
  .workspace-board-heading-row { min-width: 0; width: 100%; }
  .workspace-board-search { min-width: 0; flex-basis: 100%; }
  .workspace-board-body { padding: var(--space-2); }
  .workspace-board-settings-pop { inset-inline: var(--space-2); width: auto; }
  .workspace-board-pin { height: auto; min-height: 3em; }
  .workspace-board-pin > span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
}

@media (hover: none) {
  .workspace-board-lane-bottom-add,
  .workspace-board-card-menu {
    opacity: 1;
  }
}

@media (prefers-reduced-motion: reduce) {
  .workspace-board,
  .workspace-board-card,
  .workspace-board-settings-pop {
    animation: none;
  }

  .workspace-board-card,
  .workspace-board-pin,
  .workspace-board-lane {
    transition: none;
  }
}

.board-head {
  display: flex;
  flex: none;
  gap: var(--space-2);
  align-items: center;
  grid-row: 1;
  padding: var(--space-2) var(--space-3);
  border-bottom: 1px solid var(--edge-rule);
}

/* 헤더의 첫 낱말. 크기·굵기·표식은 세 뷰가 나눠 쓰는 마스트헤드 제목
 * (`.workbench` 절, t-3818)이 들고, 여기 남는 것은 이 h1만의 여백이다. */
.board-title {
  margin: 0;
}

.board-search {
  display: flex;
  flex: 1;
  gap: var(--space-2);
  align-items: center;
  min-width: 0;
  padding-inline: var(--space-2);
  border-radius: var(--radius-sm);
  background: var(--surface-raised);
}

.board-search .icon {
  flex: none;
  width: 14px;
  height: 14px;
  color: var(--ink-glyph);
}

.board-query {
  flex: 1;
  min-width: 0;
  height: 28px;
  border: 0;
  background: none;
  color: var(--ink-chalk);
  font: inherit;
  font-size: var(--text-xs);
  outline: none;
}

/* The chord in the empty field — Orca's keycap pair at 9px with a keycap's
 * own border (`ShortcutKeyCombo`, `min-w-4 px-1 text-[9px]`,
 * AgentDashboardToolbar.tsx:111-117). One cap holding the window's spelling
 * (⌘K, Ctrl+K) rather than two: the speller is one hand here. */
.board-search-keys {
  flex: none;
  padding: 1px 4px;
  border: 1px solid var(--edge-rule);
  border-radius: var(--radius-xs);
  color: var(--ink-mist);
  font-family: inherit;
  font-size: 9px;
  line-height: 1.4;
  pointer-events: none;
}

.board-count {
  flex: none;
  color: var(--ink-mist);
  font-size: var(--text-xs);
  font-variant-numeric: tabular-nums;
}

/* 검색이 좁히고 있는 동안에만 서는 줄. 옆의 총계보다 조용한 것은 둘이 다른
 * 질문에 답하기 때문이다 — 하나는 이 보드가 들고 있는 것, 다른 하나는 지금
 * 보이는 것. */
.board-results {
  flex: none;
  color: var(--ink-mist);
  font-size: var(--text-2xs);
  font-variant-numeric: tabular-nums;
}

/* ---- Agent ontology graph -------------------------------------------------
 *
 * One stable topology and one action inspector. Runtime state changes the
 * node's dress, never its coordinates, so the graph remains a spatial memory
 * instead of becoming another moving Kanban. */

/* 보드가 재는 것은 창이 아니라 제 폭이다 (1-t1111).
 *
 * 아래 두 블록은 `@media`였고, 그것은 창 전체의 폭을 물었다. 보드는 창의 한
 * 조각이다 — 사이드바와 오른쪽 판이 서 있고 무대가 둘로 갈리면 1440px 창
 * 안에서 보드가 받는 자리는 400px다(실측). 창은 그동안 1440이라고 답했으므로
 * 두 칸 격자(`minmax(0, 1fr)` + 인스펙터)가 그대로 서 있었다.
 *
 * 격리에는 둘째 몫이 있다. `#board-view`는 `.pane` 격자의 칸이라 `min-width`가
 * `auto`였고, 그래서 제 min-content 밑으로는 줄지 않았다 — 400px 판 안에
 * 601px로 서서 201px가 잘렸고, 잘린 쪽이 인스펙터였다. `inline-size`는 제 폭이
 * 내용을 보지 않게 하므로 그 바닥이 사라진다(실측: 잘린 폭 201px → 0).
 *
 * 컨테이너와 격자가 같은 요소인 것은 가로 축만 가두기 때문에 안전하다. 이
 * 격자의 `auto auto auto minmax(0, 1fr)`도, 그 안 표면의 `minmax(0, 1fr) auto`도
 * 부모가 준 높이에서 그대로 풀린다 — 실측: 이 한 줄만 얹고 아래 두 블록을 옛
 * `@media`인 채로 두면 `window.mjs`는 774/774이고, 809px 보드에서 범례는 제
 * 줄 56px를 그대로 지킨다. 지난번 그 줄이 모든 폭에서 0이었던 것은 격리 탓이
 * 아니라 아래 둘째 블록이 **창을 재서 고른 720이라는 수를 보드에 그대로 물어**
 * `display: none`이 어디서나 걸렸기 때문이다 — 보드가 받는 자리는 어느 창에서도
 * 720을 넘은 적이 없다(실측: 1280 창에서 649, 1024에서 433, 860에서 319).
 *
 * id가 아니라 클래스로 짚는 것은 둘째 leaf의 보드가 복제본이기 때문이다:
 * `docHost`가 사본에서 id를 떼므로 `#board-view`는 첫 판에만 있다. 팝아웃은
 * 원본 마크업을 그대로 쓰므로 같은 선택자에 함께 걸린다. 셋 다 컨테이너인 것을
 * 재고 나서야 아래를 `@container`로 옮겼다 — 컨테이너가 없는 자리에 남은
 * `@container`는 살아 있는 규칙의 모양을 한 죽은 규칙이다. `:has()`가 보드의
 * 다시 그리기에 무는 값은 없다(실측: 카드 스물넷을 마흔 판 다시 그려 스타일
 * 재계산 81회·21ms로 `#board-view`와 같다). */
.file-view:has(.agent-graph-layout) {
  /* 이름을 단 컨테이너 (round three). 아래 세 티어의 `@container board`가 이
   * 상자를 묻는다 — 그림의 스크롤 판도 컨테이너가 되면서(`graph`, 레인이
   * 제 방을 나눠 갖는 셈의 기준) 이름 없는 질의가 안쪽 상자를 잡을 수
   * 있게 되었기 때문이다. 티어는 보드의 폭이고, 레인의 몫은 판의 폭이다. */
  container: board / inline-size;
}

/* 시안의 사이드바가 보드 안의 레일이 된다 (t-4145). 첫 열이 레일이고 머리·
 * 나브·툴바·그림은 둘째 열에 선다 — 파일 뷰의 네 행은 그대로이고, 레일만
 * 네 행을 다 지난다. 작업 보기와 목록 티어에서 레일이 접히면 첫 열은
 * `auto`라 0으로 내려앉는다.
 *
 * 위의 `:has()`가 아니라 마크업의 제 클래스(`.agent-board`)로 짚는다 — 사본과
 * 팝아웃도 그 클래스를 들고, `:has()` 뒤에 `> *`를 달면 보드의 모든 직계
 * 자식이 「:has 에 매인 자리」가 되어 선택 하나마다 판 전체를 다시 묻는다
 * (실측: 선택 30번 41ms → 158ms). */
.agent-board {
  grid-template-columns: auto minmax(0, 1fr);
}

.agent-board > * {
  grid-column: 2;
}

/* ---- 작업 레일 (t-4145, 시안의 sidebar/run-item) ------------------------
 *
 * 항목은 범위 선택과 같은 표에서 나온다(`agentRelationsScopeChoices`). 굵은
 * 줄이 작업, 작은 줄이 「에이전트 N개 · 확인 필요 1」이고, 앞의 점이 묶음의
 * 상태다 — 다섯 상태 색 그대로, 새 색은 없다. */
.agent-board > .agent-relations-rail {
  grid-column: 1;
  grid-row: 1 / -1;
}

.agent-relations-rail {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
  width: var(--agent-relations-rail-width);
  min-height: 0;
  padding: var(--space-5) var(--space-2) var(--space-4);
  border-right: var(--rule-width) solid var(--edge-rule);
  background: var(--nav-plane);
  overflow: auto;
  scrollbar-width: thin;
}

.agent-relations-rail-caption {
  margin: 0;
  padding: 0 var(--space-2) var(--space-2);
  color: var(--ink-mist);
  font-family: var(--font-display);
  font-size: var(--text-3xs);
  font-weight: 600;
  letter-spacing: var(--workbench-eyebrow-tracking);
  text-transform: uppercase;
}

.agent-relations-rail-list {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
  min-width: 0;
}

.agent-relations-rail-item {
  display: flex;
  gap: var(--space-2);
  align-items: flex-start;
  width: 100%;
  min-width: 0;
  padding: var(--space-3) var(--space-2);
  border: var(--rule-width) solid transparent;
  border-radius: var(--radius-sm);
  background: none;
  color: var(--ink-mist);
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition:
    background-color var(--motion-fast) var(--ease-standard),
    border-color var(--motion-fast) var(--ease-standard);
}

.agent-relations-rail-item:hover,
.agent-relations-rail-item:focus-visible {
  background: var(--row-hover);
  outline: none;
}

.agent-relations-rail-item[aria-pressed="true"] {
  border-color: var(--edge-rule);
  background: var(--surface-raised);
}

.agent-relations-rail-copy {
  flex: 1;
  min-width: 0;
}

.agent-relations-rail-item b,
.agent-relations-rail-item small {
  display: block;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agent-relations-rail-item b {
  color: var(--ink-chalk);
  font-size: var(--text-2xs);
  font-weight: 500;
}

.agent-relations-rail-item small {
  margin-top: var(--space-1);
  font-size: var(--text-3xs);
}

.agent-relations-rail-mark {
  flex: none;
  width: var(--status-dot);
  height: var(--status-dot);
  margin-top: var(--space-1);
  border-radius: 50%;
  background: var(--ink-mist);
}

.agent-relations-rail-mark.is-attention { background: var(--signal-wait); }
.agent-relations-rail-mark.is-working { background: var(--signal-ready); }
.agent-relations-rail-mark.is-done { background: var(--signal-done); }
.agent-relations-rail-mark.is-paused { background: var(--ink-label); }

.agent-graph-head {
  gap: var(--space-4);
  padding-inline: var(--space-5);
  /* 어느 폭에서든, 어느 말로든 (1-t1111). 이 줄은 아래 블록 안에 있었고,
   * 거기 있으면 「머리가 한 줄에 드는가」를 판의 폭 하나가 대신 답한다 — 그
   * 답은 낱말의 길이에 달렸고 낱말은 로케일마다 다르다(실측·한국어: 줄지 않는
   * 항목 여섯이 510px, 그 중 요약 하나가 219px). 밖에 두어도 넓은 판에서는
   * 아무것도 바뀌지 않는다: `flex: 1`인 검색은 basis가 0이라 줄을 넘치게 하지
   * 못하므로, 자리가 모자란 판에서만 줄이 하나 늘어난다. */
  flex-wrap: wrap;
  min-height: var(--agent-graph-head-height);
  padding-block: var(--space-2);
  background: var(--workbench-ambient), var(--surface-deck);
}

.agent-graph-heading {
  display: flex;
  flex: none;
  gap: var(--space-2);
  align-items: center;
  margin-right: var(--space-2);
  white-space: nowrap;
}

/* 시안의 머리는 아이콘과 제목이다 (t-4145). 눈썹줄은 DOM에 남되 그림에서
 * 물러난다 — 작업 보기는 이미 그랬고, 두 보기가 한 머리를 나눠 쓴다. */
.agent-graph-head .agent-graph-eyebrow {
  display: none;
}

.agent-graph-heading-mark {
  flex: none;
  color: var(--workbench-accent-ink);
}

.agent-graph-eyebrow,
.agent-inspector-kind,
.agent-graph-node-kind,
.agent-graph-lane,
.agent-graph-legend-head {
  color: var(--ink-glyph);
  font-family: var(--font-display);
  font-size: var(--text-3xs);
  font-weight: 600;
  letter-spacing: 0.08em;
  line-height: 1.2;
  text-transform: uppercase;
}

.agent-graph-node-kind,
.agent-graph-lane {
  font-size: var(--agent-graph-text-fine);
}

/* 레인 줄이 이미 열의 이름을 말한다 (round three). 카드마다 「에이전트」를
 * 한 번 더 적던 눈썹줄은 같은 낱말의 세 번째 사본이었다 — DOM에는 남고
 * (낭독기의 라벨은 노드가 따로 든다) 그림에서만 물러난다. */
.agent-graph-node-kind {
  display: none;
}

.agent-graph-summary {
  display: flex;
  flex: none;
  gap: var(--space-3);
  align-items: center;
  margin-left: auto;
}

.agent-graph-stat {
  display: inline-flex;
  gap: var(--space-2);
  align-items: center;
  min-height: var(--agent-graph-control-height);
  padding-inline: var(--space-2);
  border: 0;
  border-radius: var(--radius-sm);
  background: none;
  color: var(--ink-mist);
  font: inherit;
  font-size: var(--text-2xs);
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
  transition:
    background-color var(--motion-fast) var(--ease-standard),
    color var(--motion-fast) var(--ease-standard);
}



.agent-graph-stat:hover:not(:disabled),
.agent-graph-stat:focus-visible {
  background: var(--row-hover);
  color: var(--ink-chalk);
  outline: none;
}

.agent-graph-stat:disabled {
  cursor: default;
  opacity: 0.48;
}

.agent-graph-stat-mark {
  width: 7px;
  height: 7px;
  border: var(--rule-width) solid var(--edge-mark);
  border-radius: 50%;
}

.agent-graph-stat.is-attention .agent-graph-stat-mark {
  border-color: var(--signal-wait);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--signal-wait) 22%, transparent);
}

/* 넷 중 하나만 사람을 붙잡는다 (1-t353).
 *
 * 넷은 같은 11px 굵은 글씨로 나란히 서 있었고, 그래서 "확인 필요 2"와 "완료 0"이
 * 같은 크기로 읽혔다. 둘은 같은 급함이 아니다 — 하나는 에이전트가 사람을 기다리며
 * 멈춰 선 수이고 다른 하나는 지나간 일의 수다. 0인 칩은 이미 `:disabled`로
 * 물러나 있으므로, 남은 일은 **서 있는 확인 필요**를 앞으로 내는 것뿐이다. */
.agent-graph-stat.is-attention:not(:disabled) {
  color: var(--signal-wait-ink);
}

/* 잉크는 신호색이 아니라 신호색의 **잉크**다 (1-t385).
 *
 * 위 규칙이 이 칩에 신호색 12%의 바탕을 주었다. 그 바탕 위에 같은 신호색을
 * 글자로 얹으면 밝은 바닥에서 대비가 바닥을 뚫는다 — 칠해진 픽셀로 재어
 * 3.91:1, 11px 글자에 필요한 4.5:1 밑이다. 같은 산술이 이 저장소에 이미
 * 한 번 적혀 있고(`--signal-halt-ink`), 답도 같다. */
.agent-graph-stat.is-attention:not(:disabled) .agent-graph-stat-count {
  color: var(--signal-wait-ink);
}

.agent-graph-stat.is-working .agent-graph-stat-mark {
  border-color: var(--signal-ready);
  border-top-color: transparent;
  animation: wt-agent-spin 1s steps(12) infinite;
}

.agent-graph-stat.is-done .agent-graph-stat-mark {
  border-color: var(--signal-done);
  background: var(--signal-done);
}

.agent-graph-stat-count {
  min-width: 1ch;
  color: var(--ink-chalk);
  font-size: var(--text-xs);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  text-align: right;
}

/* 런은 에이전트 상태가 아닌 제어 범위다. 그래서 상태 셋과 한 상자에 합치지 않고,
 * 움직이지 않는 궤도 글리프를 써서 작업 중 스피너와도 구분한다. */
.agent-graph-run {
  display: inline-flex;
  flex: none;
  gap: var(--space-1);
  align-items: center;
  color: var(--ink-mist);
  font-family: var(--font-display);
  font-size: var(--text-3xs);
  font-weight: 600;
  letter-spacing: var(--workbench-eyebrow-tracking);
  text-transform: uppercase;
}

.agent-graph-run .icon {
  width: 12px;
  height: 12px;
  color: var(--ink-glyph);
}

.agent-graph-run-count {
  color: var(--ink-chalk);
  font-variant-numeric: tabular-nums;
}

.agent-graph-overlay-controls {
  display: inline-flex;
  flex: none;
  gap: var(--agent-graph-gap-tight);
}

.agent-graph-overlay-controls button {
  min-height: var(--agent-graph-control-height);
  padding-inline: var(--space-3);
  border: 0;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--ink-mist);
  font: inherit;
  font-size: var(--text-2xs);
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
  transition:
    background-color var(--motion-fast) var(--ease-standard),
    color var(--motion-fast) var(--ease-standard);
}


.agent-graph-overlay-controls button:hover,
.agent-graph-overlay-controls button:focus-visible,
.agent-graph-overlay-controls button.is-active,
.agent-graph-density[aria-pressed="true"],
.agent-graph-follow.is-active {
  background: var(--surface-raised);
  color: var(--ink-chalk);
  outline: none;
}

.agent-relations-toolbar .board-search {
  flex: 0 1 var(--agent-graph-search-width);
  min-width: 8em;
  margin-left: auto;
  padding-inline: 0;
  border-bottom: var(--rule-width) solid var(--edge-rule);
  border-radius: 0;
  background: none;
}

/* ---- 서랍·시트·팝오버가 쉬는 자리 (t-2374) --------------------------------
 *
 * 셋 다 뷰가 태어날 때 함께 서고, 넓은 판에서는 아무 일도 하지 않는다. 여는
 * 것도 닫는 것도 클래스 하나이므로 티어를 오갈 때 만들어지는 노드는 0이다. */
.agent-graph-overlays {
  position: relative;
  display: flex;
  flex: none;
  align-items: center;
}

/* 이 둘은 좁은 판에만 있다 — 넓은 판에서 세 단추는 이미 나란히 서 있고,
 * 곁판은 이미 열려 있다. 목적지가 아니라 좁은 판의 손잡이다. */
.icon-btn.agent-graph-overlay-toggle,
.icon-btn.agent-inspector-close {
  display: none;
}

.agent-graph-scrim {
  position: absolute;
  z-index: 6;
  display: none;
  border: 0;
  background: color-mix(in srgb, var(--surface-well) 55%, transparent);
  cursor: default;
  inset: 0;
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--motion-fast) var(--ease-standard);
}

.file-view.is-inspector-open .agent-graph-scrim {
  opacity: 1;
  pointer-events: auto;
}

.agent-inspector-close {
  position: absolute;
  top: var(--space-3);
  right: var(--space-3);
}

.agent-inspector-head {
  position: relative;
}

.agent-graph-head-tools {
  display: flex;
  flex: none;
  gap: var(--space-1);
  align-items: center;
}

.agent-graph-head-tools > .icon-btn {
  flex: none;
}

/* 서랍 티어의 손잡이. 넓은 판의 곁판은 늘 서 있으므로 여기서는 없다. */
.icon-btn.agent-inspector-toggle {
  display: none;
}

.agent-graph-legend-toggle[aria-expanded="true"] {
  color: var(--ink-chalk);
  background: var(--row-hover);
}

.agent-graph-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) var(--agent-graph-inspector-width);
  min-width: 0;
  min-height: 0;
  grid-row: 4;
  border-top: var(--rule-width) solid var(--edge-rule);
}

.agent-graph-surface,
.agent-graph-scroll,
.agent-graph-canvas {
  min-width: 0;
  min-height: 0;
}

/* 판은 모눈이 아니라 원장이다 (round three).
 *
 * 모눈 종이와 한가운데의 후광은 「작은 그림이 판 한가운데 앉는」 그림을
 * 위한 것이었고, 그 그림이 곧 문제였다: 1998px 창에서 그림은 780px이었고
 * 나머지는 빈 모눈이었다. 그림이 판을 채우면 후광이 설 자리도 없다. 바닥은
 * 창의 recess 그 하나이고, 위에 서는 것은 띠와 카드뿐이다. */
.agent-graph-surface {
  /* 배율이 실제로 배율이 되는 자리 (1-t353).
   *
   * 이 여섯은 `:root`에 있었다. 커스텀 속성은 **선언된 자리에서** 치환되므로,
   * `:root`에 적힌 `--agent-graph-agent-lane`은 거기서 `--agent-graph-zoom: 1`을
   * 먹고 `calc(172px * calc(1.55 * 1))`로 굳은 다음 그 굳은 값이 아래로
   * 내려왔다. `applyAgentGraphZoom`이 이 표면에 0.45를 써 넣어도 레인 폭과
   * 글자 크기는 꿈쩍하지 않았다는 뜻이다 — 실측: 축소를 세 번 눌러 눈금이
   * 55%가 되어도 카드 폭은 180px 그대로였고, 줄어든 것은 `var(--agent-graph-zoom)`을
   * 제 규칙에서 직접 부르는 높이들(레인 22px→12px)뿐이었다. 그래서 「전체 보기」는
   * 그림을 눌러 찌그러뜨릴 뿐 작게 만들지 못했다.
   *
   * 창이 쓰는 자리에서 치환되어야 창이 쓴 값이 반영된다. 이 여섯을 읽는 규칙은
   * 전부 이 표면 안에 있고(레인 줄·띠 머리·카드의 제목/줄/눈썹/맥박), 머리의
   * `LIVE CONTROL GRAPH`는 창의 글자 크기를 쓰지 이 축척을 쓰지 않는다.
   *
   * 레인 폭 둘은 round three에서 격자(`.agent-graph-nodes`)로 내려갔다 —
   * 그 둘이 이제 판의 폭(`cqw`)을 읽고, 그 단위는 쓰는 자리의 컨테이너를
   * 보기 때문이다. */
  --agent-graph-zoom: 1;
  --agent-graph-scale: calc(var(--agent-graph-density) * var(--agent-graph-zoom));
  /* Zooming out has to shrink the WORDS too, or a lane half its width is a
   * lane holding the same sentence with less room for it. The floor is what
   * keeps a zoomed-out graph a picture a person can still read rather than a
   * diagram of grey bars — past it, shrinking further buys nothing. */
  --agent-graph-text-title: max(var(--agent-graph-text-floor-title), calc(var(--text-sm) * var(--agent-graph-zoom)));
  --agent-graph-text-now: max(var(--agent-graph-text-floor-line), calc(var(--text-xs) * var(--agent-graph-zoom)));
  --agent-graph-text-line: max(var(--agent-graph-text-floor-line), calc(var(--text-2xs) * var(--agent-graph-zoom)));
  --agent-graph-text-fine: max(var(--agent-graph-text-floor-fine), calc(var(--text-3xs) * var(--agent-graph-zoom)));
  position: relative;
  /* 두 줄: 그림, 그리고 범례 (1-t431). 범례는 이 표면 위에 뜬 겹이었고 —
   * 그래서 카드를 가리고 띠 머리에게 덮였다 — 이제 제 줄에 선다. 그림의 줄이
   * `minmax(0, 1fr)`인 것은 스크롤 판이 제 내용만큼 자라 범례를 밀어내지
   * 않게 하기 위해서다. */
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  grid-template-columns: minmax(0, 1fr);
  overflow: hidden;
  background: var(--surface-well);
}

/* 판의 머리 (t-4145, 시안의 canvas-heading): 눈썹줄(런), 범위의 제목, 한 문장,
 * 오른쪽에 에이전트 수. 그림 위에 뜨지 않고 제 줄에 선다. */
.agent-graph-canvas-head {
  grid-row: 1;
  display: flex;
  gap: var(--space-3);
  align-items: flex-start;
  justify-content: space-between;
  min-width: 0;
  padding: var(--space-5) var(--space-6) var(--space-1);
}

.agent-graph-canvas-heading {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  min-width: 0;
}

.agent-graph-scope-title {
  margin: 0;
  overflow: hidden;
  color: var(--ink-chalk);
  font-family: var(--font-display);
  font-size: var(--text-lg);
  font-weight: 600;
  letter-spacing: -0.02em;
  line-height: 1.3;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agent-graph-scope-copy {
  margin: 0;
  color: var(--ink-mist);
  font-size: var(--text-2xs);
  line-height: 1.6;
  overflow-wrap: anywhere;
}

.agent-graph-scope-count {
  flex: none;
  margin-top: var(--space-5);
  padding: var(--space-1) var(--space-2);
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-sm);
  color: var(--ink-mist);
  font-size: var(--text-3xs);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

/* 레인이 제 방을 나눠 갖는 셈의 기준 (round three). `cqw`는 가장 가까운
 * 컨테이너의 폭이고, 그것이 이 판이어야 인스펙터의 몫을 뺀 폭이 답이 된다. */
.agent-graph-scroll {
  grid-row: 2;
  width: 100%;
  height: 100%;
  padding: var(--space-4) var(--space-5) var(--space-6);
  overflow: auto;
  cursor: grab;
  container: graph / inline-size;
}

.agent-graph-scroll.is-panning {
  cursor: grabbing;
  user-select: none;
}

/* 그림은 위에서 시작하고 폭을 채운다 (round three).
 *
 * 1-t353의 「그림이 판보다 작으면 판 한가운데 앉는다」는 작은 그림을 큰 판에
 * 두는 법이었다. 이제 그림은 작지 않다 — 레인이 남는 폭을 나눠 가지므로 그림의
 * 폭은 언제나 판의 폭이고, 세로는 원장처럼 위에서 아래로 읽힌다. `max-content`
 * 인 것은 레인이 실측 폭 밑으로 줄지 않는 자리에서 그림이 판을 넘치고, 넘친
 * 만큼 스크롤 범위가 되어야 하기 때문이다. */
.agent-graph-canvas {
  /* 레인 둘의 폭 (round three).
   *
   * 맥락 레인은 실측 폭에 밀도와 배율을 곱한 그대로다. 에이전트 레인은 그
   * 수와 **판의 몫** 중 큰 쪽이다 — 몫은 판의 폭에서 맥락 레인과 도랑들을
   * 뺀 나머지를 층의 수(`--agent-graph-agent-lanes`, `paintAgentGraph`가
   * 적는다)로 나눈 것. 넓은 판에서 카드는 그래서 판을 채우고, 좁은 판에서는
   * 실측 폭에서 멈춰 맞춤(`fitAgentGraph`)이 배율을 내린다. 셋 다 여기 서는
   * 것은 `cqw`가 쓰는 자리의 컨테이너를 보기 때문이고, 격자가 아니라 캔버스에
   * 있는 것은 아래의 빈 상자(`.agent-graph-extent`)가 같은 수를 읽기 때문이다. */
  --agent-graph-context-lane: calc(var(--agent-graph-context-width) * var(--agent-graph-scale));
  --agent-graph-lane-gap: calc(var(--agent-graph-layer-gap) * var(--agent-graph-scale));
  --agent-graph-lane-measured: calc(var(--agent-graph-agent-width) * var(--agent-graph-scale));
  --agent-graph-lane-share: calc(
    (100cqw - var(--agent-graph-context-lane)
      - var(--agent-graph-lane-gap) * var(--agent-graph-agent-lanes, 1))
    / var(--agent-graph-agent-lanes, 1)
  );
  --agent-graph-agent-lane: max(var(--agent-graph-lane-measured), var(--agent-graph-lane-share));
  position: relative;
  display: grid;
  align-content: start;
  width: max-content;
  min-width: 100%;
  min-height: 100%;
}

/* 그림의 제 폭 — 레인이 실측 폭일 때의 폭. 맞춤이 나누는 수이고, 그림이
 * 판을 채우고 있을 때조차 「이 배율에서 그림이 판에 드는가」를 답한다. */
.agent-graph-extent {
  position: absolute;
  top: 0;
  left: 0;
  height: 0;
  width: calc(
    var(--agent-graph-context-lane)
    + var(--agent-graph-agent-lanes, 1)
      * (var(--agent-graph-lane-measured) + var(--agent-graph-lane-gap))
  );
  visibility: hidden;
  pointer-events: none;
}

.agent-graph-nodes {
  /* Positioned so it is the offset parent every edge endpoint is measured
   * against, but WITHOUT a z-index: a stacking context here would put the
   * whole grid on one layer, and the edge layer has to slide between the cards
   * and the headings rather than sit entirely under or over them. */
  position: relative;
  display: grid;
  /* Row 1 is the lane strip and every band head is a row of its own, so the
   * rows size to what stands on them; the height a node wants is the node's
   * own min-height. Auto rows with a floor would make a 34px heading occupy a
   * 56px row, which is a wasted line per project on a surface built for many. */
  grid-template-rows: auto;
  grid-auto-rows: auto;
  /* No row gap: the lane strip sticks to the top of the scroll, and a gap
   * above the first band is a stripe of moving content passing behind a
   * heading that is supposed to be opaque. The breathing room a row wants is
   * spent on the node's own margin instead, where nothing sticks over it. */
  column-gap: var(--agent-graph-lane-gap);
  row-gap: 0;
  /* 한 행의 카드들은 윗선을 맞춘다 (round three). 가운데 맞춤은 키가 다른 두
   * 카드 중 작은 쪽을 행 한가운데 띄웠고, 그 카드의 위아래가 빈 자리였다. */
  align-items: start;
  width: max-content;
  min-width: 100%;
}

/* Over the cards, not under them.
 *
 * Every ordinary relation runs down a gutter and touches nothing, so the layer
 * costs those nothing. The one that needs it is the relation that runs uphill —
 * an agent one project spawned inside another — whose long horizontal crossing
 * can pass a third project's card however carefully the track is chosen. Under
 * the cards, that edge simply disappears where it is most surprising; over
 * them, it is a line a person can follow. */
.agent-graph-edges {
  position: absolute;
  z-index: 3;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  pointer-events: none;
}

.agent-graph-edge,
.agent-graph-legend-edge {
  fill: none;
  stroke: var(--edge-mark);
  stroke-opacity: 0.6;
  stroke-width: var(--agent-graph-edge-stroke);
  vector-effect: non-scaling-stroke;
}

/* 계보는 점선이고 유채색이 아니다 (round three). 호박색은 이 판에서 「사람이
 * 필요하다」의 색이고, 그 색으로 그은 선은 모든 하위 에이전트를 확인 필요로
 * 읽히게 했다. 관계는 잉크로, 상태만 색으로. */
.agent-graph-edge.is-spawned,
.agent-graph-legend-edge.is-spawned {
  stroke: var(--ink-mist);
  stroke-dasharray: 4 3;
  stroke-opacity: 0.75;
  color: var(--ink-mist);
  marker-end: url(#agent-graph-arrow);
}

/* 계보가 이미 말한 담김 (round three) — DOM에 남고 그림에서 물러난다. */
.agent-graph-edge.is-implied {
  stroke-opacity: 0;
}

.agent-graph-edge.is-selected {
  stroke: var(--ink-chalk);
  stroke-opacity: 0.95;
  stroke-width: var(--agent-graph-edge-stroke-lit);
  stroke-dasharray: none;
  color: var(--ink-chalk);
}

.agent-graph-edge.is-selected.is-implied {
  stroke-opacity: 0;
}

.agent-graph-edge.is-overlay {
  stroke-width: var(--agent-graph-edge-stroke-lit);
  stroke-opacity: 0.92;
}

.agent-graph-edge.is-mail {
  stroke: var(--signal-wait);
  stroke-dasharray: 2 7;
  animation: zc-graph-mail-flow 0.9s linear infinite;
}

.agent-graph-edge.is-dependency {
  stroke: var(--accent-core, var(--signal-ready));
  stroke-dasharray: 7 3;
  marker-end: url(#agent-graph-arrow);
  color: var(--accent-core, var(--signal-ready));
}

.agent-graph-overlay-label {
  fill: var(--ink-chalk);
  paint-order: stroke;
  stroke: var(--surface-well);
  stroke-width: var(--agent-graph-edge-stroke-pulse);
  font-family: var(--font-display);
  font-size: var(--text-3xs);
  text-anchor: middle;
}

.agent-graph-mail-pulse {
  fill: var(--signal-wait);
  filter: drop-shadow(0 0 3px var(--signal-wait));
  animation: zc-graph-mail-pulse 0.9s var(--ease-standard) infinite;
}

/* ---- the lane strip ----------------------------------------------------- */

/* Sticks to the top of the scrollport, which is the scroll container's PADDING
 * box — so `0` parks it flush with the visible top edge and lets the canvas's
 * own inset scroll away underneath it. */
.agent-graph-lane {
  position: sticky;
  z-index: 6;
  top: 0;
  align-self: stretch;
  height: calc(var(--agent-graph-lane-height) * var(--agent-graph-zoom));
  padding: 3px var(--space-3) 0;
  border-bottom: var(--rule-width) solid var(--edge-rule);
  background: var(--surface-well);
}

/* ---- the project band --------------------------------------------------- */

/* 띠는 상자가 아니라 절이다 (round three).
 *
 * 프로젝트마다 테두리 상자를 두르고 그 안에 워크스페이스 상자를, 그 안에 카드를
 * 두는 것은 같은 담김을 세 번 그리는 일이었다. 절은 위의 룰 하나로 갈리고,
 * 머리가 절의 이름을 들며, 그 아래는 그 절의 것이다. 접힌 절은 머리뿐이다. */
.agent-graph-band {
  z-index: 0;
  grid-column: 1 / -1;
  /* The grid centres its items; a band is a REGION and must fill the rows it
   * was given, or it collapses to the height of its own (empty) content. */
  align-self: stretch;
  border-top: var(--rule-width) solid var(--edge-rule);
  pointer-events: none;
}

.agent-graph-band.is-folded {
  opacity: 0.8;
}

/* 한 워크스페이스가 품은 것들이 눕는 띠. 왼쪽 끝의 레일은 사이드바의
 * 워크트리 행이 입는 그 폭과 그 색이다(`--rail-width`, `--lane-1`) — 이 창에서
 * 유채색은 lane(워크스페이스의 정체)과 상태에만 쓰이고, 여기 있는 것이 그
 * 첫째다. 띠 자체는 거의 무채색이라 상태의 다섯 색과 다투지 않는다. */
.agent-graph-swimlane {
  z-index: 1;
  grid-column: 1 / -1;
  align-self: stretch;
  margin-block: var(--agent-graph-gap-tight);
  border-radius: var(--radius-sm);
  background: color-mix(in srgb, var(--lane, var(--lane-1)) 3%, transparent);
  pointer-events: none;
}

.agent-graph-band-head {
  z-index: 5;
  grid-column: 1 / -1;
  align-self: stretch;
  min-height: calc(var(--agent-graph-band-head-height) * var(--agent-graph-zoom));
  pointer-events: none;
}

/* Pinned to the left edge of the scroll rather than to the start of the row:
 * a band six lanes wide loses its own name the moment somebody follows a
 * lineage to the right, which is exactly when they most need to know whose
 * project they are reading. */
.agent-graph-band-rail {
  position: sticky;
  left: 0;
  display: flex;
  gap: var(--space-3);
  align-items: center;
  width: max-content;
  max-width: 100%;
  height: 100%;
  padding: 0 var(--space-2);
  pointer-events: auto;
}

.agent-graph-band-fold {
  display: grid;
  flex: none;
  place-items: center;
  width: 20px;
  height: 20px;
  padding: 0;
  border: 0;
  border-radius: var(--radius-xs);
  background: none;
  color: var(--ink-glyph);
  cursor: pointer;
  transition:
    background-color var(--motion-fast) var(--ease-standard),
    color var(--motion-fast) var(--ease-standard);
}

.agent-graph-band-fold:hover,
.agent-graph-band-fold:focus-visible {
  background: var(--row-hover);
  color: var(--ink-chalk);
  outline: none;
}

.agent-graph-band-fold .icon {
  width: 12px;
  height: 12px;
}

.agent-graph-band-name {
  display: flex;
  gap: var(--space-2);
  align-items: baseline;
  min-width: 0;
  padding: 3px var(--space-2);
  border: var(--rule-width) solid transparent;
  border-radius: var(--radius-sm);
  background: none;
  color: var(--ink-chalk);
  font: inherit;
  font-size: var(--text-xs);
  text-align: left;
  cursor: pointer;
  transition:
    background-color var(--motion-fast) var(--ease-standard),
    border-color var(--motion-fast) var(--ease-standard);
}

.agent-graph-band-name .icon {
  width: 13px;
  height: 13px;
  color: var(--ink-glyph);
  transform: translateY(2px);
}

/* 이름은 줄지 않는다 (round three). 좁은 판에서 이름이 0으로 눌리고 수만
 * 남던 실측 그림 — `min-width: 0`이 이름에도 걸렸기 때문이다. 줄어드는 것은
 * 그 곁의 수이고, 이름은 제 낱말만큼 선다. */
.agent-graph-band-name strong {
  flex: none;
  overflow: hidden;
  max-width: 100%;
  font-family: var(--font-display);
  font-size: var(--agent-graph-text-title);
  font-weight: 600;
  letter-spacing: -0.01em;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agent-graph-band-name:hover,
.agent-graph-band-name:focus-visible {
  border-color: var(--edge-rule);
  background: var(--surface-raised);
  outline: none;
}

.agent-graph-band-head.is-selected .agent-graph-band-name {
  border-color: var(--edge-mark);
  background: var(--surface-raised);
}

/* Catalog-only projects are inventory, not dead graph space. Their default
 * folded treatment is deliberately one line even when the catalog holds many
 * workspaces; clicking the chevron restores the ordinary band. */
.agent-graph-band-head.is-dormant.is-folded .agent-graph-band-rail,
.agent-graph-band-head.is-dormant.is-folded .agent-graph-band-name {
  min-width: 0;
  max-width: 100%;
  flex-wrap: nowrap;
}

.agent-graph-band-head.is-dormant.is-folded .agent-graph-band-line {
  flex: none;
}

.agent-graph-band-head.is-dormant .agent-graph-band-name strong {
  color: var(--ink-mist);
  font-weight: 500;
}

.agent-graph-band-line {
  display: flex;
  gap: var(--space-1);
  align-items: baseline;
  min-width: 0;
  overflow: hidden;
  color: var(--ink-mist);
  font-size: var(--agent-graph-text-line);
  white-space: nowrap;
}

.agent-graph-band-counts {
  display: inline-flex;
  gap: var(--space-2);
}

/* 수는 글이지 알약이 아니다 (round three). 「3 워크스페이스」「2 에이전트」에
 * 두른 테두리 둘은 머리에서 가장 밝은 것이었고, 가장 덜 급한 것이었다. */
.agent-graph-count-chip {
  display: inline-flex;
  gap: var(--agent-graph-tick-gap);
  align-items: baseline;
  white-space: nowrap;
}

.agent-graph-count-chip + .agent-graph-count-chip::before {
  content: "·";
  margin-right: var(--space-1);
  color: var(--edge-mark);
}

.agent-graph-count-chip b {
  color: var(--ink-label);
  font-variant-numeric: tabular-nums;
  font-weight: 600;
}

.agent-graph-band-roll {
  display: flex;
  flex: none;
  gap: var(--space-1);
  align-items: center;
}

.agent-graph-band-chip {
  display: inline-flex;
  gap: var(--space-1);
  align-items: center;
  padding: var(--agent-graph-chip-inset);
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-pill);
  background: var(--surface-deck);
  color: var(--ink-mist);
  font-size: var(--text-3xs);
}

.agent-graph-band-chip i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--edge-mark);
}

.agent-graph-band-chip b {
  color: var(--ink-chalk);
  font-variant-numeric: tabular-nums;
  font-weight: 600;
}

.agent-graph-band-chip.is-attention {
  border-color: color-mix(in srgb, var(--signal-wait) 42%, transparent);
  background: color-mix(in srgb, var(--signal-wait) 10%, var(--surface-deck));
}

.agent-graph-band-chip.is-attention i {
  background: var(--signal-wait);
}

.agent-graph-band-chip.is-working {
  border-color: color-mix(in srgb, var(--signal-ready) 42%, transparent);
}

.agent-graph-band-chip.is-working i {
  background: var(--signal-ready);
}

.agent-graph-band-chip.is-done i {
  background: var(--signal-done);
}

/* A folded band still has to answer WHO is in there. The faces are the shortest
 * true answer — marks a person already recognises, each in its own state ring. */
.agent-graph-band-faces {
  display: flex;
  flex: none;
  gap: var(--agent-graph-tick-gap);
  align-items: center;
  margin-left: var(--space-1);
}

.agent-graph-band-face {
  display: grid;
  place-items: center;
  width: 20px;
  height: 20px;
  border: var(--rule-width) solid var(--edge-mark);
  border-radius: 50%;
  background: var(--surface-deck);
}

.agent-graph-band-face .agent-ico {
  width: 13px;
  height: 13px;
}

.agent-graph-band-face.is-attention {
  border-color: var(--signal-wait);
}

.agent-graph-band-face.is-working {
  border-color: var(--signal-ready);
}

.agent-graph-band-face.is-done {
  border-color: var(--signal-done);
}

.agent-graph-band-more {
  color: var(--ink-mist);
  font-size: var(--text-3xs);
}

.agent-graph-dormant-list {
  display: inline-flex;
  gap: var(--space-1);
  align-items: center;
  min-width: 0;
}

.agent-graph-dormant-chip,
.agent-graph-idle-chip {
  width: max-content;
  padding: 2px 7px;
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-pill);
  background: transparent;
  color: var(--ink-mist);
  font: inherit;
  font-size: var(--agent-graph-text-fine);
  white-space: nowrap;
  cursor: pointer;
  transition:
    background-color var(--motion-fast) var(--ease-standard),
    border-color var(--motion-fast) var(--ease-standard),
    color var(--motion-fast) var(--ease-standard),
    opacity var(--motion-fast) var(--ease-standard);
}

.agent-graph-dormant-chip:hover,
.agent-graph-dormant-chip:focus-visible,
.agent-graph-idle-chip:hover,
.agent-graph-idle-chip:focus-visible {
  border-color: var(--edge-mark);
  background: var(--surface-raised);
  color: var(--ink-chalk);
  outline: none;
}

/* ---- nodes -------------------------------------------------------------- */

.agent-graph-node {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  gap: var(--agent-graph-gap);
  align-self: start;
  width: 100%;
  min-width: 0;
  min-height: calc(var(--agent-graph-row-min-height) * var(--agent-graph-zoom));
  margin-block: calc(var(--agent-graph-row-gap) * var(--agent-graph-zoom) / 2);
  padding: var(--agent-graph-card-inset);
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--agent-graph-card-radius);
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--ink-chalk) 3%, transparent),
      transparent 40%
    ),
    var(--surface-deck);
  box-shadow: var(--shadow-node);
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition:
    background-color var(--motion-fast) var(--ease-standard),
    border-color var(--motion-fast) var(--ease-standard),
    box-shadow var(--motion-fast) var(--ease-standard),
    opacity var(--motion-fast) var(--ease-standard);
}

/* A newly spawned keyed node enters once. Re-dressing an existing state never
 * restarts this animation because the DOM node itself is retained. */
.agent-graph-node.is-agent {
  animation: zc-graph-node-in var(--motion-fast) var(--ease-enter);
}

/* Search preserves the map. A non-match recedes but keeps its seat, tree item,
 * edges and keyboard destination so clearing the query restores the exact
 * spatial memory the person had before typing. */
.agent-graph-node.is-search-dimmed,
.agent-graph-band-head.is-search-dimmed {
  opacity: 0.24;
}

.agent-graph-band.is-search-dimmed {
  opacity: 0.18;
}

.agent-graph-edge.is-search-dimmed {
  stroke-opacity: 0.14;
}

.agent-graph-node.is-selected.is-search-dimmed {
  opacity: 0.68;
}

/* State is a rail on the card's own edge, never a fill: a node whose colour
 * changes with its state is a node a person re-reads on every hook event. */
.agent-graph-node::before {
  content: "";
  position: absolute;
  top: var(--space-3);
  bottom: var(--space-3);
  left: 0;
  width: var(--rail-width);
  border-radius: 0 var(--rail-width) var(--rail-width) 0;
  background: var(--edge-mark);
}

.agent-graph-node.is-workspace::before {
  background: var(--lane, var(--lane-1));
}

/* 그리고 카드의 왼쪽 레일도. 상태 없는 노드(프로젝트·워크스페이스)의 중립선은
 * `--edge-mark` 그대로이고, 상태를 가진 대기 중 카드만 그 잉크를 입는다. */
.agent-graph-node.is-idle::before {
  background: var(--ink-mist);
}

.agent-graph-node.is-attention::before {
  background: var(--signal-wait);
}

.agent-graph-node.is-working::before {
  background: var(--signal-ready);
}

.agent-graph-node.is-done::before {
  background: var(--signal-done);
}

.agent-graph-node.is-failed::before {
  background: var(--signal-halt);
}

.agent-graph-node:hover,
.agent-graph-node:focus-visible {
  border-color: var(--edge-mark);
  background: var(--surface-raised);
  box-shadow: var(--shadow-node-raised);
  outline: none;
}

/* 고른 카드는 잉크의 고리를 두른다 (round three). 초록 고리는 「작업 중」의
 * 색이라 고른 것과 도는 것을 한 색으로 말했다. 고름은 상태가 아니므로 잉크다. */
.agent-graph-node.is-selected {
  border-color: color-mix(in srgb, var(--ink-chalk) 55%, transparent);
  background: var(--surface-raised);
  outline: var(--rule-width) solid color-mix(in srgb, var(--ink-chalk) 55%, transparent);
  outline-offset: -1px;
}

/* 확인 필요는 호박색 워시와 안쪽 고리 (t-2466). 색이 빠져도 고리가 남는다. */
.agent-graph-node.is-attention {
  border-color: color-mix(in srgb, var(--signal-wait) 55%, transparent);
  background-color: color-mix(in srgb, var(--signal-wait) 12%, var(--surface-deck));
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--signal-wait) 30%, transparent),
    var(--shadow-node);
}

.agent-graph-node.is-failed {
  border-color: color-mix(in srgb, var(--signal-halt) 45%, transparent);
}

/* Silence is recency, not death. Keep the working state and its stable seat,
 * but lower the card and stamp the stale heartbeat in amber. */
.agent-graph-node.is-went-quiet:not(.is-selected):not(.is-search-dimmed) {
  opacity: 0.7;
}

.agent-graph-mail-badge {
  position: absolute;
  z-index: 2;
  top: -7px;
  right: -7px;
  display: grid;
  place-items: center;
  min-width: 18px;
  height: 18px;
  padding-inline: var(--space-1);
  border: 2px solid var(--surface-deck);
  border-radius: var(--radius-pill);
  background: var(--signal-wait);
  color: var(--surface-abyss);
  font-size: var(--text-3xs);
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.agent-graph-merge-port {
  position: absolute;
  top: 50%;
  right: calc(-1 * var(--agent-graph-layer-gap) * var(--agent-graph-scale));
  z-index: 4;
  width: max-content;
  padding: 2px 7px;
  border: var(--rule-width) solid var(--edge-mark);
  border-radius: var(--radius-pill);
  background: var(--surface-well);
  color: var(--ink-label);
  font-size: var(--agent-graph-text-fine);
  transform: translateY(-50%);
}

.agent-graph-merge-port::before {
  content: "";
  position: absolute;
  top: 50%;
  right: 100%;
  width: calc(var(--agent-graph-layer-gap) * var(--agent-graph-scale));
  border-top: var(--rule-width) solid var(--edge-mark);
}

.agent-graph-node-head {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: var(--space-2);
  align-items: center;
}

.agent-graph-node-icon,
.agent-graph-node-state {
  display: grid;
  place-items: center;
  flex: none;
}

.agent-graph-node-icon {
  width: var(--agent-graph-icon-tile);
  height: var(--agent-graph-icon-tile);
  border-radius: var(--radius-sm);
  background: var(--surface-well);
  color: var(--ink-mist);
}

.agent-graph-node-icon > .icon {
  width: 14px;
  height: 14px;
}

.agent-graph-node-icon > .agent-ico {
  width: 16px;
  height: 16px;
}

.agent-graph-node-state {
  width: 14px;
  height: 14px;
}

/* 같은 이유로 카드의 상태 점도 — 이 기본값이 서는 자리는 대기 중뿐이고,
 * 나머지 넷은 아래에서 제 신호색을 입는다. */
.agent-graph-node-state::before {
  content: "";
  width: 7px;
  height: 7px;
  border: var(--rule-width) solid var(--ink-mist);
  border-radius: 50%;
}

.agent-graph-node-state.is-needs-attention {
  color: var(--signal-wait);
}

.agent-graph-node-state.is-needs-attention::before {
  border-color: var(--signal-wait);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--signal-wait) 24%, transparent);
}

.agent-graph-node-state.is-working::before {
  width: 9px;
  height: 9px;
  border-color: var(--signal-ready);
  border-top-color: transparent;
  animation: wt-agent-spin 1s steps(12) infinite;
}

.wt-dot.is-paused::before,
.wt-agent.is-paused .wt-agent-dot,
.agent-graph-node-state.is-paused::before {
  width: 8px;
  height: 10px;
  border: 0;
  border-inline: 2px solid var(--ink-label);
  border-radius: 0;
  background: none;
}

.agent-graph-node-state.is-done::before {
  border-color: var(--signal-done);
  background: var(--signal-done);
}

.agent-graph-node-state.is-done,
.agent-graph-node-state.is-failed {
  color: var(--signal-done);
}

.agent-graph-node-state.is-failed {
  color: var(--signal-halt);
}

.agent-graph-node-state > .icon {
  width: 11px;
  height: 11px;
}

.agent-graph-node-state:has(> .icon)::before {
  display: none;
}

.agent-graph-node-copy {
  min-width: 0;
}

.agent-graph-node-title,
.agent-graph-node-line,
.agent-graph-node-message,
.agent-graph-node-meta {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Below 60%, the graph becomes a locator: stable names and state points stay;
 * messages, activity, vendor metadata and secondary context retire. */
.agent-graph-surface.is-lod .agent-graph-node {
  min-height: calc(var(--agent-graph-row-min-height) * 0.62);
  gap: 0;
  padding-block: 5px;
}

.agent-graph-surface.is-lod .agent-graph-node-head {
  grid-template-columns: minmax(0, 1fr) auto;
  gap: var(--space-1);
}

.agent-graph-surface.is-lod .agent-graph-node-icon,
.agent-graph-surface.is-lod .agent-graph-node-kind,
.agent-graph-surface.is-lod .agent-graph-node-line,
.agent-graph-surface.is-lod .agent-graph-node-message,
.agent-graph-surface.is-lod .agent-graph-node-status,
.agent-graph-surface.is-lod .agent-card-meta,
.agent-graph-surface.is-lod .agent-graph-node-meta,
.agent-graph-surface.is-lod .agent-graph-wire,
.agent-graph-surface.is-lod .agent-graph-pips {
  display: none;
}

/* 한 벌의 사다리 (t-1853).
 *
 * 이 넷은 13·11px로 굳어 있었고, 같은 판의 띠 제목만 `--agent-graph-text-*`를
 * 읽어 배율을 따라 줄었다 — 실측(배율 60%): 카드 제목 13px 옆에 띠 제목 10px.
 * 두 제목이 서로 다른 크기로 서는 것도 문제지만, 더 큰 문제는 축소가 뜻을
 * 잃는 것이다: 레인만 좁아지고 글자는 그대로면 축소가 사는 것은 화면이 아니라
 * 말줄임표다. 토큰은 배율 1에서 정확히 13·11px이므로(`--text-sm`·`--text-2xs`)
 * 이 자리의 그림은 그대로이고, 줄어들 때만 함께 줄어든다. */
.agent-graph-node-title {
  color: var(--ink-chalk);
  font-size: var(--agent-graph-text-title);
  font-weight: 600;
  letter-spacing: -0.01em;
  line-height: 1.35;
}

/* 브랜치는 두 줄까지 받는다 (t-1853).
 *
 * 카드 제목은 한 줄에 말줄임표였고, 에이전트 카드에서는 그것이 옳다 — 거기
 * 서는 것은 과제의 **문장**이고, 문장은 머리를 읽으면 무엇인지 알 수 있다.
 * 워크스페이스 카드에 서는 것은 브랜치이고 브랜치는 그렇지 않다: 머리는 과제
 * 번호, 꼬리는 이름이라 잘린 「wt/t-1421/agent…」은 같은 과제의 워크스페이스
 * 둘을 구별해 주지 못한다. 이 레인은 실측 116px이라 앞으로도 긴 브랜치를 한
 * 줄에 담지 못하므로, 잘라 내는 대신 줄을 하나 더 준다 — 끊어지는 자리는 거의
 * 언제나 슬래시 뒤이고(UAX #14), 끊길 곳이 없는 한 덩어리만 아무 데서나
 * 끊는다. 셋째 줄은 없다: 그 아래는 카드가 아니라 문단이다. */
.agent-graph-node.is-workspace .agent-graph-node-title {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  white-space: normal;
  overflow-wrap: anywhere;
  font-family: var(--font-display);
}

/* ---- the workspace label ------------------------------------------------ */

/* 워크스페이스는 카드가 아니라 레인의 이름표다 (round three).
 *
 * 브랜치 이름과 조상과 수를 담은 상자가 카드와 같은 무게로 서면 판에서 카드가
 * 여섯이든 셋이든 절반은 이름표다. 상자를 벗기고 레인 색 레일 하나에 낱말을
 * 세우면 눈은 이름표를 지나 카드로 간다 — 이름표는 「어디」의 답이고, 사람이
 * 보드를 여는 이유는 「무엇을」이다. */
.agent-graph-node.is-workspace {
  min-height: 0;
  padding: var(--space-2) var(--space-3) var(--space-2) var(--space-4);
  border-color: transparent;
  background: transparent;
  box-shadow: none;
}

.agent-graph-node.is-workspace::before {
  top: var(--space-2);
  bottom: var(--space-2);
  border-radius: var(--radius-pill);
}

.agent-graph-node.is-workspace:hover,
.agent-graph-node.is-workspace:focus-visible {
  border-color: var(--edge-rule);
  background: var(--row-hover);
  box-shadow: none;
}

.agent-graph-node.is-workspace.is-selected {
  border-color: color-mix(in srgb, var(--ink-chalk) 35%, transparent);
  background: var(--row-selected);
  outline: none;
}

.agent-graph-node.is-workspace .agent-graph-node-icon {
  display: none;
}

.agent-graph-node.is-workspace .agent-graph-node-head {
  grid-template-columns: minmax(0, 1fr);
}

/* Orca's `dashboardCardDisplayState`: a card nobody has looked at since it
 * last moved wears full ink and semibold, and one that has been seen steps
 * back. Measured weights, not a class name — the whole point is the contrast. */
.agent-graph-node.is-agent:not(.is-unseen) .agent-graph-node-title {
  color: var(--ink-figure);
  font-weight: 600;
}

.agent-graph-node-line {
  margin-top: 2px;
  color: var(--ink-label);
  font-size: var(--agent-graph-text-line);
  font-weight: 500;
  display: flex;
  align-items: baseline;
  gap: var(--space-1);
  min-width: 0;
  max-width: 100%;
}

.agent-graph-branch-part {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
  flex: 1 1 auto;
}

.agent-graph-base-part {
  flex: none;
  white-space: nowrap;
  color: var(--ink-mist);
}

/* 마지막 한마디는 인용이다 (round three). 도구 줄 아래에서 같은 잉크로 서면
 * 도구의 대상처럼 읽혔다 — 따옴표가 그것이 말이었음을 알린다. */
.agent-graph-node-message {
  margin-top: 0;
  color: var(--ink-label);
  font-size: var(--agent-graph-text-line);
  font-weight: 500;
}

.agent-graph-node-message::before {
  content: "“";
  color: var(--ink-glyph);
}

.agent-graph-node-message::after {
  content: "”";
  color: var(--ink-glyph);
}

/* 다섯 칸이 한 줄에 들지 않으면 줄을 바꾼다 (t-2374).
 *
 * 상태 낱말 · 턴 단계 · 모델 id · 마지막 소식 · 이 턴의 길이. 267px 레인에
 * 다섯이 한 줄로 들어가지 않아 시계가 「8…」로 잘렸다(실측, 한국어). 잘린
 * 숫자는 정보가 아니므로 줄을 하나 내어 준다 — 카드가 한 줄 자라는 편이
 * 「8분째」를 「8…」로 적는 것보다 낫다. */
.agent-graph-node-status,
.board-card-status {
  display: flex;
  flex-wrap: nowrap;
  gap: var(--space-1);
  align-items: center;
  min-width: 0;
  color: var(--ink-mist);
  font-size: var(--agent-graph-text-line);
  font-weight: 500;
}

/* 시계는 줄지 않는다 — 줄어들 자리가 있으면 그 자리는 낱말이 가져간다. */
.agent-graph-node-clock,
.agent-card-model,
.agent-card-phase {
  flex: none;
}

/* 상태 낱말은 끊기지 않고(「작업\n중」이 실측된 그림이다), 단계가 남는 자리를
 * 받아 말줄임표로 물러난다. */
.agent-graph-state-word {
  flex: none;
  white-space: nowrap;
}

.agent-graph-node-status > .agent-card-phase,
.board-card-status > .agent-card-phase {
  flex: 0 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

.agent-graph-node-status > .agent-card-phase::before,
.board-card-status > .agent-card-phase::before,
.agent-card-meta > :not(:first-child)::before {
  content: "·";
  margin-right: var(--space-1);
  color: var(--edge-mark);
}

/* Model and both clocks are the card's foot, never a fifth and sixth word
 * competing with the state. Empty prebuilt clock slots fold without churn. */
.agent-card-meta {
  display: flex;
  gap: var(--space-1);
  align-items: center;
  min-width: 0;
  color: var(--ink-mist);
  font-size: var(--agent-graph-text-line);
  font-weight: 500;
}

.agent-card-meta > :empty {
  display: none;
}

/* 상태 낱말은 제 상태의 잉크를 입는다 (round three). 다섯 상태만 색을 갖는다는
 * 계약 안이고, 마크의 모양이 색 없이도 같은 말을 한다. */
.agent-graph-state-word {
  color: var(--ink-label);
  font-size: var(--text-2xs);
  font-weight: 600;
}

.agent-graph-node.is-attention .agent-graph-state-word,
.board-card.is-needs-attention .agent-graph-state-word,
.board-card.is-waiting .agent-graph-state-word,
.board-card.is-blocked .agent-graph-state-word,
.board-card.is-awaiting_permission .agent-graph-state-word {
  color: var(--signal-wait-ink);
}

.agent-graph-node.is-working .agent-graph-state-word,
.board-card.is-working .agent-graph-state-word,
.board-card.is-streaming .agent-graph-state-word {
  color: var(--signal-ready);
}

.agent-graph-node.is-done .agent-graph-state-word,
.board-card.is-done:not(.is-settled) .agent-graph-state-word,
.board-card.is-exited:not(.is-settled) .agent-graph-state-word {
  color: var(--signal-done);
}

.agent-graph-node.is-failed .agent-graph-state-word,
.board-card.is-failed .agent-graph-state-word {
  color: var(--signal-halt-ink);
}

/* 칩은 **모델**이지 벤더가 아니다 (t-2374). 벤더는 머리의 마크가 이미
 * 말했고, 「Claude」 셋이 나란히 선 화면에서 여태 아무 데도 적혀 있지 않던
 * 것이 무엇이 Opus이고 무엇이 Haiku인가였다. 그래프 노드와 인스펙터 카드가
 * 같은 클래스를 쓰는 것은 둘이 같은 조립기에서 나오기 때문이다. */
.agent-card-model {
  padding: var(--agent-graph-chip-inset);
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-pill);
  background: var(--surface-well);
  color: var(--ink-label);
  font-family: var(--font-mono);
  font-size: var(--agent-graph-text-fine);
  font-weight: 500;
  white-space: nowrap;
}

/* 턴 단계 — 상태 낱말 옆의 한 마디이고 여섯째 상태가 아니다. 유채색이 없는
 * 것이 그 뜻이다: 다섯 상태만 색을 갖는다는 계약을 이 낱말이 깨면 화면에
 * 여섯째 상태가 생긴다. 「조용해짐」만 예외인데, 그것은 이 낱말이 아니라
 * `went_quiet`이라는 이미 있는 층이 입고 있던 옷이다. */
.agent-card-phase {
  color: var(--ink-mist);
  font-size: var(--text-2xs);
  font-weight: 500;
  white-space: nowrap;
}

.agent-card-phase.is-quiet {
  padding: 1px 5px;
  border: var(--rule-width) solid color-mix(in srgb, var(--signal-wait) 46%, transparent);
  border-radius: var(--radius-pill);
  background: color-mix(in srgb, var(--signal-wait) 10%, transparent);
  color: var(--signal-wait-ink);
  font-size: var(--agent-graph-text-fine);
  letter-spacing: 0.02em;
}

/* 빈 칸은 접힌다 (t-2374). 상태 줄의 다섯 자리는 언제나 서 있고 — 조건부
 * 자식이 카드를 다시 짓게 만들기 때문에 — 말할 것이 없는 칸만 물러난다.
 * 가운뎃점을 다는 규칙이 `:not(:first-child)`인 것은 첫 칸(상태 낱말)이
 * 비는 일이 없기 때문이다: 그 칸은 다섯 상태 중 하나를 언제나 든다. */
.agent-graph-node-status > :empty,
.board-card-status > :empty {
  display: none;
}

.agent-graph-node-clock {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--text-2xs);
  font-weight: 500;
}

.agent-graph-node-clock.is-running {
  color: var(--ink-label);
}

.agent-graph-node-meta {
  color: var(--ink-mist);
  font-size: var(--agent-graph-text-line);
  font-weight: 500;
}

/* ---- the live wire ------------------------------------------------------ */

/* What the agent is doing, in its own three fields. This is the half of the
 * ontology that moves: the containment above it is a fact about where the work
 * lives, and this is the fact about what the work IS, one tool call at a time.
 *
 * 상자가 아니라 줄이다 (round three). 카드 안의 두 번째 상자는 카드를 두 장으로
 * 읽히게 했다. 위의 룰 하나가 「여기부터 지금」을 가르고, 활동 줄은 카드에서
 * 가장 큰 글자로 선다 — 그것이 사람이 이 판을 여는 이유이기 때문이다. */
.agent-card-doing,
.agent-graph-wire {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
  padding-top: var(--space-2);
  border-top: var(--rule-width) solid var(--edge-rule);
}

.agent-card-doing.is-bare {
  display: none;
}

.agent-card-activity {
  display: flex;
  gap: var(--space-2);
  align-items: baseline;
  min-width: 0;
  font-size: var(--agent-graph-text-now);
  line-height: 1.5;
}

.agent-card-activity.is-none {
  display: none;
}

/* 활동 줄이 **바뀔 때** 한 번 (설계 §4). 이름이 다른 두 keyframes를 번갈아
 * 가리키므로 규칙이 갈리고, 규칙이 갈리면 브라우저가 애니메이션을 새로
 * 세운다 — 상시 애니메이션을 하나도 늘리지 않고 얻는 강조다. */
.agent-card-activity[data-beat="a"] {
  animation: zc-card-beat-a var(--motion-fast) var(--ease-standard);
}

.agent-card-activity[data-beat="b"] {
  animation: zc-card-beat-b var(--motion-fast) var(--ease-standard);
}

@keyframes zc-card-beat-a {
  from { opacity: 0.35; }
  to { opacity: 1; }
}

@keyframes zc-card-beat-b {
  from { opacity: 0.35; }
  to { opacity: 1; }
}

.agent-card-activity-mark {
  flex: none;
  align-self: center;
  width: var(--agent-graph-mark-size);
  height: var(--agent-graph-mark-size);
  border-radius: 50%;
  background: var(--ink-glyph);
}

.agent-card-activity.is-edit .agent-card-activity-mark,
.agent-card-activity.is-run .agent-card-activity-mark {
  background: var(--signal-ready);
}

.agent-card-activity.is-ask .agent-card-activity-mark {
  background: var(--signal-wait);
}

.agent-card-activity-verb {
  flex: none;
  color: var(--ink-mist);
  font-weight: 600;
  white-space: nowrap;
}

/* 경로는 꼬리 두 마디로 이미 줄여서 온다(`agentGraphTargetWord`) — 오른쪽에서
 * 자르는 상자는 절대 경로의 앞선 `/`를 반대편으로 옮겨 없는 경로를 그린다. */
.agent-card-activity-target {
  min-width: 0;
  overflow: hidden;
  /* 사람이 보드를 여는 이유 그 자체 — 카드에서 가장 진한 잉크. */
  color: var(--ink-chalk);
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agent-card-activity.is-run .agent-card-activity-target {
  font-family: var(--font-mono);
}

.agent-card-activity.is-asking .agent-card-activity-target {
  color: var(--signal-wait-ink);
}

.agent-card-activity-when {
  flex: none;
  margin-left: auto;
  color: var(--ink-glyph);
  font-size: var(--agent-graph-text-line);
  font-variant-numeric: tabular-nums;
}

.agent-card-ticker {
  display: flex;
  gap: var(--space-1);
  align-items: center;
  min-width: 0;
  overflow: hidden;
  color: var(--ink-label);
  font-size: var(--agent-graph-text-line);
  line-height: 1.4;
  white-space: nowrap;
}

.agent-card-ticker-more {
  flex: none;
  color: var(--ink-glyph);
  font-variant-numeric: tabular-nums;
}

.agent-card-ticker-more:empty {
  display: none;
}

.agent-card-tool {
  display: flex;
  gap: var(--space-1);
  min-width: 0;
  overflow: hidden;
}

.agent-card-ticker-more:not(:empty) + .agent-card-tool::before,
.agent-card-tool + .agent-card-tool::before {
  content: "·";
  flex: none;
  color: var(--edge-mark);
}

.agent-card-tool.is-empty {
  display: none;
}

.agent-card-tool-verb {
  flex: none;
  color: var(--ink-glyph);
  font-weight: 600;
}

.agent-card-tool-target {
  min-width: 0;
  overflow: hidden;
  color: var(--ink-label);
  text-overflow: ellipsis;
}

.agent-card-tool.is-run .agent-card-tool-target {
  font-family: var(--font-mono);
}

/* The eight-slot ring is retained for stable updates and detailed tips. Its
 * glyph row no longer competes with the three readable tool phrases. */
.agent-card-ticker-glyphs {
  display: none;
}

/* 여덟 칸은 언제나 DOM에 있고, 아직 안 쓴 칸만 물러난다 — 링 버퍼라 칸의
 * 수가 절대 움직이지 않고, 도는 것은 글리프와 클래스뿐이다(설계 §5). */
.agent-card-tick {
  flex: none;
  color: var(--ink-glyph);
  font-size: var(--agent-graph-tick-size);
  font-style: normal;
  line-height: 1;
}

.agent-card-tick.is-empty {
  display: none;
}

/* 마지막 것이 **지금**이다. 색 하나로 그 한 칸을 앞세우면 여덟 개를 세지
 * 않고도 어느 쪽이 새것인지 읽힌다. */
.agent-card-tick.is-last {
  color: var(--ink-chalk);
}

.agent-card-tick:not([data-repeat=""])::after {
  content: "×" attr(data-repeat);
  font-size: var(--text-3xs);
}

.agent-card-ticker:not(:has(> .agent-card-tool:not(.is-empty))),
.agent-card-ticker.is-echo {
  display: none;
}

/* 컨텍스트 미터. 값이 없으면 그리지 않는다 — 분모를 지어내면 「거의 찼다」와
 * 「이제 시작」을 구별하지 못하는 그림이 된다. */
.agent-card-meter {
  height: var(--agent-graph-meter-height);
  margin-top: var(--space-1);
  overflow: hidden;
  border-radius: var(--radius-pill);
  background: var(--meter-track);
}

.agent-card-meter-fill {
  display: block;
  width: calc(var(--meter-ratio, 0) * 100%);
  height: 100%;
  border-radius: inherit;
  /* 홈은 `--meter-track` 그대로이되 채움은 이 창의 조용한 회색이다. 사용량
   * 패널의 `--meter-fill`은 다른 바탕에 맞춰 고른 톤이라 여기서는 제 홈에
   * 대해 3:1을 넘지 못한다(실측 1.97 어두운 테마 / 1.70 밝은 테마) — 채움과
   * 홈이 갈리지 않는 막대는 비율을 말하지 않는다. */
  background: var(--ink-mist);
  transition: width var(--motion-fast) var(--ease-standard);
}

/* 창이 차 오르면 기다림의 색으로 — 새 색이 아니라 이 창이 이미 「사람이
 * 필요하다」에 쓰는 그 색이다. */
.agent-card-meter.is-full .agent-card-meter-fill {
  background: var(--signal-wait);
}

.agent-graph-beat {
  display: block;
  min-width: 0;
}

.agent-graph-beat-summary {
  display: grid;
  grid-template-columns: 12px auto minmax(0, 1fr) auto auto;
  gap: var(--agent-graph-gap);
  align-items: center;
  min-width: 0;
  font-size: var(--agent-graph-text-fine);
  line-height: 1.5;
  list-style: none;
  cursor: pointer;
}

.agent-graph-beat-summary::-webkit-details-marker {
  display: none;
}

.agent-graph-beat-mark {
  display: grid;
  place-items: center;
  width: 12px;
  height: 12px;
  color: var(--ink-mist);
}

.agent-graph-beat-mark .icon {
  width: 10px;
  height: 10px;
}

.agent-graph-beat.is-started .agent-graph-beat-mark {
  color: var(--signal-ready);
  animation: zc-graph-pulse 1.4s var(--ease-standard) infinite;
}

.agent-graph-beat.is-failed .agent-graph-beat-mark {
  color: var(--signal-halt);
}

.agent-graph-beat-verb {
  color: var(--ink-mist);
  font-weight: 600;
  white-space: nowrap;
}

.agent-graph-beat.is-started .agent-graph-beat-verb {
  color: var(--signal-ready);
}

.agent-graph-beat.is-failed .agent-graph-beat-verb {
  color: var(--signal-halt-ink);
}

.agent-graph-beat-repeat {
  color: var(--ink-mist);
  font-family: var(--font-mono);
  font-size: var(--text-3xs);
}

.agent-graph-beat-when {
  color: var(--ink-glyph);
  font-size: var(--text-3xs);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.agent-graph-beat-raw {
  display: block;
  margin: var(--space-1) 0 0
    calc(var(--agent-graph-mark-size) + var(--agent-graph-gap) * 2);
  padding: var(--space-1) var(--space-2);
  overflow-wrap: anywhere;
  border-left: var(--rule-width) solid var(--edge-rule);
  color: var(--ink-mist);
  font-family: var(--font-mono);
  font-size: var(--text-3xs);
  line-height: 1.45;
  white-space: pre-wrap;
}

/* The tail of a path is the half that identifies it, so a long one is shortened
 * to its last segments BEFORE it gets here (`agentGraphTargetWord`) rather than
 * by a right-to-left clip: a bidi flip moves the leading `/` of an absolute path
 * to the other end, and a path drawn backwards is worse than a path cut off. A
 * command is the opposite — `cargo test --workspace` is identified by its front —
 * so what reaches this rule is already the right half and the clip is ordinary. */
.agent-graph-beat-target {
  overflow: hidden;
  color: var(--ink-label);
  font-family: inherit;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agent-graph-beat-target.is-mono,
.agent-graph-beat[data-verb="bash"] .agent-graph-beat-target {
  font-family: var(--font-mono);
}

.agent-graph-wire > .agent-graph-beat:first-child {
  animation: zc-graph-beat-in var(--motion-dialog) var(--ease-standard);
}

.agent-graph-wire > .agent-graph-beat:not(:first-child) {
  opacity: 0.62;
}

/* A card with an open tool call is the one card on the surface that is moving
 * right now, and it says so on its own edge rather than by growing.
 *
 * 후광은 돌지 않는다 (round three). 카드마다 2초짜리 상시 애니메이션은 판이
 * 바쁠수록 — 여덟 카드가 돌 때 — 여덟 겹의 다시 그리기였다. 도는 것은 상태
 * 마크 하나면 충분하고, 살아 있는 테두리는 서 있는 색으로 말한다. */
.agent-graph-node.is-live {
  border-color: color-mix(in srgb, var(--signal-ready) 42%, transparent);
  box-shadow:
    0 0 0 1px color-mix(in srgb, var(--signal-ready) 14%, transparent),
    var(--shadow-node);
}

/* ---- the workspace pips ------------------------------------------------- */

.agent-graph-pips {
  display: flex;
  /* 후광을 두른 pip 하나가 옆의 pip을 물지 않을 만큼 (1-t385). */
  gap: var(--space-1);
  align-items: center;
  min-height: 7px;
}

/* 대기 중은 사이드바의 대기 중과 같은 토큰이다 (t-1853).
 *
 * 다섯 중 이 하나만 `--edge-mark`였다 — 사이드바가 대기 중에 쓰는 것은
 * `--ink-mist`이고(`.workspace-board-card-state.is-idle`), `--edge-mark`는 그
 * 잉크를 바탕에 62% 섞은 **선 색**이다. 즉 보드가 혼자 만든 상태 색이었고,
 * 온톨로지가 금지한 바로 그것이다. 픽셀도 같은 말을 했다: 찍힌 그림에서 이
 * 6px 고리의 가장 진한 픽셀이 바탕(#0d1418)에 대해 2.75:1로, 다섯 중 유일하게
 * 3:1 밑이었다(확인 필요 7.90, 작업 중 10.94, 완료 7.32, 실패 7.06). 토큰을
 * 사이드바의 것으로 되돌리면 같은 자리에서 7.19:1이 된다. */
.agent-graph-pip {
  width: 6px;
  height: 6px;
  border: var(--rule-width) solid var(--ink-mist);
  border-radius: 50%;
}

/* 색만으로 말하지 않는다 (1-t385).
 *
 * 이 셋은 같은 6px 원반이었고 다른 것은 색뿐이었다. 카드는 이미 그러지 않는다 —
 * `.agent-graph-node-state`의 셋은 빈 원 + 후광 / 트인 원 / 채운 원으로, 색을
 * 구별하지 못하는 눈에도 갈린다. 워크스페이스 카드가 제 에이전트들의 상태를
 * 말하는 이 줄은 그 낱말을 데려오지 못하므로(`aria-hidden`이고 이름도 없다)
 * 색만 다른 점 여덟은 그 눈에게 점 여덟이다. 같은 모양 어휘를 그대로 쓴다.
 * 도는 것만 빼고 — 여덟 개가 함께 도는 줄은 상태가 아니라 소음이다. */
/* 후광은 옅어야 고리가 읽힌다 (t-2374).
 *
 * 24%였고, 그 값은 6px 고리의 안티에일리어싱된 가장자리와 거의 같은 밝기였다 —
 * 그래서 찍은 픽셀에서 **후광이 바탕으로 셈해졌고**, 고리는 제 후광에 대해
 * 2.72:1이었다(밝은 테마). 모양의 단서는 그대로 남기면서 값을 벌린다. */
.agent-graph-pip.is-attention {
  border-color: var(--signal-wait);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--signal-wait) 14%, transparent);
}

.agent-graph-pip.is-working {
  border-color: var(--signal-ready);
  border-top-color: transparent;
}

.agent-graph-pip.is-done {
  border-color: var(--signal-done);
  background: var(--signal-done);
}

.agent-graph-pip.is-failed {
  border-color: var(--signal-halt);
  background: var(--signal-halt);
}

.agent-graph-pip-more {
  color: var(--ink-mist);
  font-size: var(--text-3xs);
}

.agent-graph-empty {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  margin: 0;
  color: var(--ink-mist);
  font-size: var(--text-xs);
}

.agent-graph-empty[hidden] {
  display: none;
}

/* ---- the legend and the zoom -------------------------------------------- */

/* 범례는 뜨기를 그만두고 판의 흐름 안에 선다 (1-t431).
 *
 * 캔버스 위에 뜬 겹은 카드를 가리고 띠 머리에 덮였다. 제 줄에 서면 아무것도
 * 가리지 않고, 폭이 넉넉하면 한 줄, 좁으면 줄을 바꾼다 — 맞춤 셈은 판의 제
 * 여백에서 나누므로 줄어든 판을 저절로 따라간다. round three는 그 줄을
 * 한 단 얇게 두었다: 열두 항목이 11px에 서면 판에서 가장 조용한 줄이 된다. */
/* 판의 바닥 (t-4145, 시안의 canvas-footer): 범례 · 손짓 힌트 · 배율이 한
 * 줄이다. 범례는 뜨지 않고(1-t431), 배율 상자도 이제 뜨지 않는다. */
.agent-graph-canvas-foot {
  grid-row: 3;
  display: flex;
  gap: var(--space-2) var(--space-3);
  align-items: center;
  min-width: 0;
  padding: var(--space-3) var(--space-5);
  border-top: var(--rule-width) solid var(--edge-rule);
  background-color: var(--surface-deck);
}

.agent-graph-legend {
  display: flex;
  flex: 1 1 auto;
  flex-wrap: wrap;
  gap: var(--space-1) var(--space-4);
  align-items: center;
  min-width: 0;
  background-color: var(--surface-deck);
  font-size: var(--text-2xs);
}

.agent-graph-gesture-hint {
  margin-left: auto;
  color: var(--ink-mist);
  font-size: var(--text-3xs);
  white-space: nowrap;
}

.agent-graph-legend[hidden] {
  display: none;
}

/* 그릴 것이 하나도 없을 때는 그림에 딸린 상자도 서지 않는다 — 없는 선의 뜻을
 * 풀어 주는 범례와 없는 그림의 배율은, 빈 판을 "아직 시작 전"이 아니라 "무언가
 * 잘못됨"으로 읽히게 하는 두 상자다. */
.agent-graph-surface.is-empty .agent-graph-canvas-foot,
.agent-graph-surface.is-empty .agent-graph-legend,
.agent-graph-surface.is-empty .agent-graph-zoom {
  display: none;
}

.agent-graph-legend-head {
  margin: 0;
  font-size: var(--text-3xs);
}

.agent-graph-legend-list {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-1) var(--space-3);
  align-items: center;
  margin: 0;
  padding: 0;
  color: var(--ink-mist);
  font-size: var(--text-2xs);
  list-style: none;
}

.agent-graph-legend-list li {
  display: flex;
  gap: var(--agent-graph-gap);
  align-items: center;
  font-size: var(--text-2xs);
}

/* 범례의 마크는 그림의 모양을 따른다: 절은 위의 룰, 이름표는 레인 색 레일,
 * 카드는 상태 레일을 단 상자. */
.agent-graph-legend-mark {
  width: 16px;
  height: 11px;
  border: var(--rule-width) solid var(--edge-mark);
  border-radius: var(--radius-xs);
  background: var(--surface-deck);
}

.agent-graph-legend-mark.is-project {
  border-color: transparent;
  border-top-color: var(--edge-mark);
  border-radius: 0;
  background: transparent;
}

.agent-graph-legend-mark.is-workspace {
  border-color: transparent;
  border-left: var(--rail-width) solid var(--lane-1);
  background: transparent;
}

.agent-graph-legend-mark.is-agent {
  border-left: var(--rail-width) solid var(--signal-ready);
}

.agent-graph-legend-line {
  width: 34px;
  height: 8px;
}

/* 배율은 그림 위에 뜬 채로 남는다 — 굴리는 손이 닿는 자리에 있어야 하는,
 * 판 하나 몫도 되지 않는 상자다. 다만 뜬 것은 위에 있어야 뜬 것이다: 카드가
 * `z-index: 2`, 띠 머리가 5, 레인 줄이 6인 판에서 이 상자에는 `z-index`가
 * 없었고, 그래서 그림이 자라면 먹혔다. 격자의 첫 줄에 겹쳐 두는 것은, 이것이
 * 덮는 것이 **그림**이지 제 줄에 선 범례가 아니게 하기 위해서다 (1-t431). */
.agent-graph-zoom {
  display: flex;
  flex: none;
  gap: var(--agent-graph-gap-tight);
  align-items: center;
  padding: 2px;
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-sm);
  background-color: var(--surface-deck);
}

.agent-graph-zoom button {
  display: grid;
  place-items: center;
  width: 24px;
  height: 24px;
  padding: 0;
  border: 0;
  border-radius: var(--radius-xs);
  background: none;
  color: var(--ink-mist);
  cursor: pointer;
  transition:
    background-color var(--motion-fast) var(--ease-standard),
    color var(--motion-fast) var(--ease-standard);
}

.agent-graph-zoom button:hover,
.agent-graph-zoom button:focus-visible {
  background: var(--row-hover);
  color: var(--ink-chalk);
  outline: none;
}

.agent-graph-zoom button:disabled {
  cursor: default;
  opacity: 0.4;
}

.agent-graph-zoom .icon {
  width: 13px;
  height: 13px;
}

.agent-graph-zoom-label {
  min-width: 4ch;
  color: var(--ink-mist);
  font-size: var(--text-3xs);
  font-variant-numeric: tabular-nums;
  text-align: center;
}

/* ---- task board: work, current activity, and a person's next action ------ */
/* The two view switches — 작업/관계 here, 목록/칸반 on the workspace board — and
 * the workbench nav's tabs are one control (t-3818): a recessed track at a
 * control's height, and the chosen segment as a raised thumb. The thumb
 * answers with weight and depth as well as fill, so it reads in grey. The
 * nav's track is its whole strip (the connected workbench section). */
.board-mode {
  display: inline-flex;
  flex: none;
  flex-wrap: wrap;
  max-width: 100%;
  gap: var(--workbench-track-inset);
  padding: var(--workbench-track-inset);
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-md);
  background: var(--surface-well);
}

.board-mode button,
.workbench-nav-link {
  min-height: calc(var(--control-height-sm) - var(--workbench-track-inset) * 2);
  padding: 0 var(--space-3);
  border: 0;
  border-radius: var(--radius-sm);
  background: transparent;
  box-shadow: none;
  color: var(--ink-label);
  font: inherit;
  font-size: var(--text-xs);
  cursor: pointer;
  transition:
    background-color var(--motion-fast) var(--ease-standard),
    box-shadow var(--motion-fast) var(--ease-standard),
    color var(--motion-fast) var(--ease-standard);
}

.board-mode button:hover,
.workbench-nav-link:hover {
  background: var(--row-hover);
  color: var(--ink-chalk);
}

.board-mode button[aria-pressed="true"],
.workbench-nav-link[aria-current="page"] {
  background: var(--workbench-thumb);
  box-shadow: var(--shadow-2);
  color: var(--ink-chalk);
  font-weight: 600;
}

/* The status filter is a row of counted pills, not a switch: any of them can
 * be the lens, and the chosen one takes the view's hue as its edge. */
.task-board-filter {
  min-height: var(--control-height-sm);
  padding: 0 var(--space-3);
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-pill);
  background: transparent;
  color: var(--ink-label);
  font: inherit;
  font-size: var(--text-xs);
  font-variant-numeric: tabular-nums;
  cursor: pointer;
  transition:
    background-color var(--motion-fast) var(--ease-standard),
    border-color var(--motion-fast) var(--ease-standard),
    color var(--motion-fast) var(--ease-standard);
}

.task-board-filter:hover {
  border-color: var(--edge-mark);
  color: var(--ink-chalk);
}

.task-board-filter[aria-pressed="true"] {
  border-color: var(--workbench-edge);
  background: var(--workbench-tint);
  color: var(--ink-chalk);
  font-weight: 600;
}

.is-task-board .agent-graph-eyebrow,
.is-task-board .agent-graph-summary,
.is-task-board .agent-graph-run,
.is-task-board .agent-graph-overlays,
.is-task-board .agent-graph-follow,
.is-task-board .agent-graph-legend-toggle,
.is-task-board .agent-graph-focus,
.agent-graph-surface[hidden],
.task-board-surface[hidden] {
  display: none;
}

.is-task-board .agent-graph-layout {
  grid-template-columns: minmax(0, 1fr);
}

.is-task-board.is-inspector-open .agent-graph-layout {
  grid-template-columns: minmax(0, 1fr) minmax(0, var(--agent-graph-inspector-width));
}

.is-task-board:not(.is-inspector-open) .agent-inspector {
  display: none;
}

.is-task-board .icon-btn.agent-inspector-close {
  display: inline-flex;
}

.task-board-surface {
  min-width: 0;
  min-height: 0;
  padding: var(--space-6);
  overflow: auto;
  background: var(--surface-well);
  scrollbar-gutter: stable;
}

.task-board-intro,
.task-board-filters,
.task-board-sections,
.task-board-empty {
  max-width: 76em;
  margin-inline: auto;
}

.task-board-intro h2 {
  margin: 0;
  color: var(--ink-chalk);
  font-family: var(--font-display);
  font-size: var(--text-xl);
  font-weight: 600;
  letter-spacing: -0.03em;
}

.task-board-summary {
  margin: var(--space-2) 0 0;
  color: var(--ink-label);
  font-size: var(--text-sm);
}

.task-board-filters {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-1);
  padding-block: var(--space-5);
}

.task-board-section + .task-board-section {
  margin-top: var(--space-5);
}

/* A section is headed by its word and count over one rule, so four stacked
 * sections read as a ledger's chapters rather than as loose captions. */
.task-board-section-head {
  margin: 0 0 var(--space-3);
  padding: 0 0 var(--space-2);
  border-bottom: var(--rule-width) solid var(--edge-rule);
  color: var(--ink-label);
  font-size: var(--text-sm);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

details.task-board-section > summary {
  cursor: pointer;
}

.task-board-section[data-task-section="attention"] > .task-board-section-head {
  border-bottom-color: color-mix(in srgb, var(--signal-wait) 45%, var(--edge-rule));
  color: var(--signal-wait);
}

.task-board-list {
  display: grid;
  gap: var(--space-3);
}

/* A task is a card on the recess: the studio's layered material — a lit top
 * edge over the deck, the board card's own cast shadow — at the workbench's
 * card radius. */
.task-board-row {
  min-width: 0;
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--workbench-card-radius);
  background: linear-gradient(180deg, var(--workbench-sheen), transparent 48%), var(--surface-deck);
  box-shadow: var(--shadow-node);
  overflow: hidden;
  transition:
    border-color var(--motion-fast) var(--ease-standard),
    box-shadow var(--motion-fast) var(--ease-standard);
}

.task-board-row:hover {
  border-color: var(--edge-mark);
  box-shadow: var(--shadow-node-raised);
}

.task-board-row.is-attention {
  border-color: color-mix(in srgb, var(--signal-wait) 55%, var(--edge-rule));
  background: linear-gradient(180deg, var(--workbench-sheen), transparent 48%),
    color-mix(in srgb, var(--signal-wait) 4%, var(--surface-deck));
}

/* The row the inspector is reading. Selection is the view's own fact, so it
 * wears the view's hue: an edge, and the rail down its leading side. A row
 * that also needs the person keeps its amber ground under the ring. */
.task-board-row.is-selected {
  border-color: var(--workbench-edge);
  box-shadow: inset var(--rail-width) 0 0 var(--workbench-accent), var(--shadow-node-raised);
}

.task-board-main {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: var(--space-2) var(--space-4);
  width: 100%;
  padding: var(--space-4) var(--space-5) var(--space-3);
  border: 0;
  background: transparent;
  color: var(--ink-chalk);
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.task-board-main:hover,
.task-board-member:hover,
.task-board-action:hover {
  background: var(--row-hover);
}

.task-board-main,
.task-board-member,
.task-board-action {
  transition: background-color var(--motion-fast) var(--ease-standard),
    color var(--motion-fast) var(--ease-standard);
}

.task-board-cap {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: var(--space-2) var(--space-3);
  min-width: 0;
}

.task-board-title {
  display: -webkit-box;
  overflow: hidden;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow-wrap: anywhere;
  font-size: var(--text-lg);
  font-weight: 600;
  line-height: 1.45;
}

.task-board-project {
  color: var(--ink-label);
  font-size: var(--text-xs);
  overflow-wrap: anywhere;
}

.task-board-activity {
  grid-column: 1;
  display: -webkit-box;
  overflow: hidden;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow-wrap: anywhere;
  color: var(--ink-chalk);
  font-size: var(--text-sm);
  line-height: 1.6;
}

/* The state is a pill — its mark, its word, and a wash of its own signal —
 * so it is read as a status and never as the title's tail. On the amber
 * ground the word takes the wait signal's INK (the 1-t385 arithmetic). */
.task-board-state {
  display: inline-flex;
  grid-column: 2;
  grid-row: 1;
  align-items: center;
  align-self: start;
  gap: var(--space-2);
  padding: var(--space-1) var(--space-3);
  border-radius: var(--radius-pill);
  background: color-mix(in srgb, currentColor 10%, transparent);
  white-space: nowrap;
  color: var(--ink-label);
  font-size: var(--text-xs);
  font-weight: 600;
}

.task-board-row.is-attention .task-board-state { color: var(--signal-wait-ink); }
.task-board-row.is-working .task-board-state { color: var(--signal-ready); }

.task-board-members {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  padding: 0 var(--space-5) var(--space-3);
}

.task-board-members[hidden],
.task-board-message[hidden],
.task-board-empty[hidden] { display: none; }

.task-board-member {
  display: inline-flex;
  align-items: baseline;
  gap: var(--space-2);
  min-width: 0;
  max-width: 100%;
  padding: var(--space-2) var(--space-3);
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-md);
  background: color-mix(in srgb, var(--surface-well) 60%, transparent);
  color: var(--ink-label);
  font: inherit;
  font-size: var(--text-xs);
  text-align: left;
  cursor: pointer;
}

.task-board-member[aria-pressed="true"] {
  border-color: var(--workbench-edge);
  background: var(--workbench-tint);
  color: var(--ink-chalk);
}
.task-board-member-name { flex: none; font-weight: 600; }
.task-board-member-work { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.task-board-member-status { flex: none; font-size: var(--text-2xs); }

.task-board-message {
  display: flex;
  gap: var(--space-3);
  margin: 0;
  padding: 0 var(--space-5) var(--space-3);
  color: var(--ink-label);
  font-size: var(--text-xs);
  line-height: 1.6;
}

.task-board-message-label { flex: none; }
.task-board-message-text { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

.task-board-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: var(--space-2);
  padding: var(--space-2) var(--space-5);
  border-top: var(--rule-width) solid var(--edge-rule);
  background: color-mix(in srgb, var(--surface-well) 45%, transparent);
  color: var(--ink-label);
  font-size: var(--text-xs);
}

/* The row's next step is a door, drawn as one: a pill in the view's hue, or
 * in the wait signal's ink where the next step is the person's answer. */
.task-board-action {
  flex: none;
  min-height: var(--control-height-sm);
  padding: 0 var(--space-3);
  border: var(--rule-width) solid var(--workbench-edge);
  border-radius: var(--radius-pill);
  background: transparent;
  color: var(--workbench-accent-ink);
  font: inherit;
  font-weight: 600;
  cursor: pointer;
}

.task-board-row.is-attention .task-board-action {
  border-color: color-mix(in srgb, var(--signal-wait) 55%, var(--edge-rule));
  color: var(--signal-wait-ink);
}

.task-board-empty {
  padding: var(--space-6) var(--space-5);
  border: var(--rule-width) dashed var(--edge-mark);
  border-radius: var(--workbench-card-radius);
  color: var(--ink-label);
  font-size: var(--text-sm);
  text-align: center;
}

/* The inspector's reading blocks: a quiet eyebrow over the words, and the
 * words on a recess so a request or a message reads as quoted material. */
/* 참고한 지식(작업 상황판) — 참여자 단추와 같은 옷, 오른쪽에 시각. */
.task-board-recalls-list {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
  margin: 0;
  padding: 0;
  list-style: none;
}
.task-board-recalls-list li {
  display: flex;
  gap: var(--space-2);
  align-items: center;
  min-width: 0;
}
.task-board-recall {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-align: left;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.task-board-recall-when {
  flex: none;
  color: var(--ink-mist);
  font-size: var(--text-2xs);
}

.task-board-detail-block h3 {
  margin: 0 0 var(--space-2);
  color: var(--ink-label);
  font-family: var(--font-display);
  font-size: var(--text-2xs);
  font-weight: 600;
  letter-spacing: var(--workbench-eyebrow-tracking);
  text-transform: uppercase;
}

.task-board-detail-block p {
  margin: 0;
  padding: var(--space-3);
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-md);
  background: var(--surface-well);
  color: var(--ink-chalk);
  font-size: var(--text-sm);
  line-height: 1.7;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.task-board-detail-members { display: grid; gap: var(--space-2); }

@container board (max-width: 1099px) {
  .is-task-board.is-inspector-open .agent-graph-layout { grid-template-columns: minmax(0, 1fr); }
  .task-board-surface { padding: var(--space-4); }
}

@container board (max-width: 699px) {
  .is-task-board .agent-graph-head { flex-wrap: wrap; }
  .task-board-intro h2 { font-size: var(--text-lg); }
  .task-board-main { grid-template-columns: minmax(0, 1fr); padding-inline: var(--space-4); }
  .task-board-state { grid-column: 1; grid-row: 3; }
  .task-board-title { font-size: var(--text-md); }
  .task-board-members, .task-board-message, .task-board-foot { padding-inline: var(--space-4); }
}

/* ---- the inspector ------------------------------------------------------ */

/* The relations workbench keeps the grid's measured ports while giving the
 * person a task scope, concise cards and a persistent evidence inspector. */
.agent-relations-toolbar {
  grid-row: 3;
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--space-4);
  min-width: 0;
  padding: var(--space-3) var(--space-5);
  border-bottom: var(--rule-width) solid var(--edge-rule);
  background: var(--surface-deck);
  color: var(--ink-mist);
  font-size: var(--text-xs);
}
/* 작업 보기에서 툴바는 검색만 든다 — 관계에만 있는 셋과 레일은 접힌다. */
.is-task-board .agent-relations-rail,
.is-task-board .agent-graph-scope-label,
.is-task-board .agent-graph-density,
.is-task-board .agent-inspector-toggle {
  display: none;
}

.is-task-board .agent-relations-toolbar .board-search {
  flex: 1 1 auto;
  max-width: none;
  margin-left: 0;
}

/* 범위 선택은 폴더 아이콘을 단 상자이고 (시안의 scope-select), 상자 안의
 * 셀렉트는 테두리를 벗는다. 「범위」라는 낱말은 낭독기의 것이다. */
.agent-graph-scope-label {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  min-width: 0;
  max-width: 100%;
  min-height: var(--agent-graph-control-height);
  padding-inline: var(--space-2) 0;
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-sm);
}

.agent-graph-scope-label > .icon {
  flex: none;
  color: var(--ink-mist);
}

.agent-graph-scope {
  min-width: 0;
  max-width: min(50vw, var(--agent-relations-card-width));
  min-height: calc(var(--agent-graph-control-height) - var(--rule-width) * 2);
  padding: var(--space-1) var(--space-2);
  padding-inline-end: var(--select-room);
  border: 0;
  border-radius: var(--radius-sm);
  background-color: transparent;
  color: var(--ink-chalk);
  font: inherit;
  font-size: var(--text-2xs);
  text-overflow: ellipsis;
}
.agent-graph-scroll { overflow-anchor: none; }
.agent-graph-edge-targets {
  position: absolute;
  z-index: 1;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  pointer-events: none;
}
.agent-graph-edge-hit {
  fill: none;
  stroke: transparent;
  stroke-width: var(--agent-graph-edge-hit-width);
  pointer-events: stroke;
  cursor: pointer;
}
.agent-graph-nodes { pointer-events: none; }
.agent-graph-node, .agent-graph-band-head { pointer-events: auto; }
.agent-graph-node.is-relation-endpoint {
  outline: var(--rule-width) solid var(--ink-label);
  outline-offset: var(--space-1);
}
.file-view:not(.is-detailed-relations) .agent-graph-node.is-agent {
  gap: var(--space-2);
  background-image: none;
}
.file-view:not(.is-detailed-relations) .agent-graph-node.is-agent .agent-card-ticker,
.file-view:not(.is-detailed-relations) .agent-graph-node.is-agent .agent-card-meter,
.file-view:not(.is-detailed-relations) .agent-graph-node.is-agent .agent-card-model,
.file-view:not(.is-detailed-relations) .agent-graph-node.is-agent .agent-graph-node-message { display: none; }
.file-view:not(.is-detailed-relations) .agent-graph-node.is-agent .agent-card-doing {
  padding-block: var(--space-1);
  border: 0;
  background: none;
}
.file-view:not(.is-detailed-relations) .agent-graph-node.is-agent .agent-card-meta {
  margin-top: 0;
  border: 0;
  padding: 0;
}
.agent-inspector-tabs {
  display: flex;
  flex: none;
  gap: var(--space-5);
  padding: 0 var(--space-5);
  border-bottom: var(--rule-width) solid var(--edge-rule);
}
.agent-inspector-tabs > button {
  flex: none;
  min-width: 0;
  margin-bottom: calc(-1 * var(--rule-width));
  padding: var(--space-2) 0 var(--space-3);
  border: 0;
  border-bottom: var(--accent-rule) solid transparent;
  border-radius: 0;
  background: none;
  color: var(--ink-mist);
  font: inherit;
  font-size: var(--text-2xs);
  white-space: nowrap;
  cursor: pointer;
}
.agent-inspector-tabs > button[aria-selected="true"] { border-bottom-color: var(--ink-chalk); color: var(--ink-chalk); }
.agent-inspector-pane { display: grid; grid-template-columns: minmax(0, 1fr); gap: var(--space-3); min-width: 0; }
.agent-inspector-pane[hidden], .agent-inspector-tabs[hidden] { display: none; }
.agent-inspector-pane.is-response-only .board-card { border: 0; padding: 0; background: none; box-shadow: none; }
.agent-inspector-pane.is-response-only .board-card > :not(.board-ask):not(.board-approve):not(.board-card-ask) { display: none; }

.agent-relation-row {
  transition: background-color var(--motion-fast) var(--ease-standard), color var(--motion-fast) var(--ease-standard);
  display: grid;
  gap: var(--space-1);
  width: 100%;
  padding: var(--space-3) 0;
  border: 0;
  border-bottom: var(--rule-width) solid var(--edge-rule);
  border-radius: 0;
  background: none;
  color: var(--ink-label);
  text-align: left;
  font: inherit;
  font-size: var(--text-2xs);
  cursor: pointer;
  overflow-wrap: anywhere;
}
.agent-relation-row:hover, .agent-relation-row[aria-pressed="true"] { background: var(--row-hover); color: var(--ink-chalk); }
.agent-relation-row-kind, .agent-relation-row > small { color: var(--ink-mist); font-size: var(--text-3xs); }
.agent-relation-row > strong { color: var(--ink-chalk); font-weight: 500; }
.agent-relation-route {
  display: grid;
  gap: var(--space-2);
  padding: var(--space-3);
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-md);
  background: var(--surface-well);
}
.agent-relation-route > button {
  border: 0;
  padding: 0;
  background: none;
  color: var(--ink-chalk);
  font: inherit;
  font-size: var(--text-2xs);
  text-align: left;
  overflow-wrap: anywhere;
  cursor: pointer;
}
.agent-relation-route-kind, .agent-relation-route .is-unavailable { padding-left: var(--space-2); color: var(--ink-mist); font-size: var(--text-3xs); }
.agent-relation-explanation { margin: 0; color: var(--ink-chalk); font-size: var(--text-xs); line-height: 1.8; overflow-wrap: anywhere; word-break: keep-all; }
.agent-relation-note { margin: 0; color: var(--ink-mist); font-size: var(--text-3xs); line-height: 1.8; overflow-wrap: anywhere; }
.agent-relation-detail, .agent-relation-dependency-fact { display: grid; gap: var(--space-3); min-width: 0; }
/* 연결 근거 (시안의 evidence): 위의 룰 한 줄 아래, 이름은 왼쪽·값은 오른쪽. */
.agent-relation-evidence { display: grid; gap: var(--space-3); min-width: 0; margin-top: var(--space-2); padding-top: var(--space-4); border-top: var(--rule-width) solid var(--edge-rule); }
.agent-relation-fact { display: flex; gap: var(--space-3); justify-content: space-between; overflow-wrap: anywhere; line-height: 1.6; }
.agent-relation-fact > span { flex: none; color: var(--ink-mist); font-size: var(--text-3xs); }
.agent-relation-fact > strong { min-width: 0; color: var(--ink-chalk); font-size: var(--text-3xs); font-weight: 450; text-align: right; user-select: text; }
.agent-relation-row:focus-visible, .agent-relation-route > button:focus-visible,
.agent-inspector-tabs > button:focus-visible, .agent-graph-scope:focus-visible {
  outline: var(--rule-width) solid var(--ink-chalk);
  outline-offset: var(--space-1);
}
@container board (max-width: 699px) {
  .agent-graph-edge-targets { display: none; }
  .agent-relations-toolbar { gap: var(--space-2); padding-inline: var(--space-3); }
}

.agent-inspector {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  border-left: var(--rule-width) solid var(--edge-rule);
  background: var(--workbench-ambient-crown), var(--surface-deck);
}

.agent-inspector-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  flex: none;
  gap: var(--space-3);
  padding: var(--space-4) var(--space-5) var(--space-5);
  border-bottom: var(--rule-width) solid var(--edge-rule);
}

/* 시안의 detail-icon: 종류 줄 아래, 제목 위의 글리프 타일 — 그림의 노드 아이콘
 * 타일(`.agent-graph-node-icon`) 그대로에 테두리 하나. */
.agent-inspector-icon {
  border: var(--rule-width) solid var(--edge-rule);
}

.agent-inspector-icon[hidden] {
  display: none;
}

.agent-inspector-title {
  margin: 0;
  color: var(--ink-chalk);
  font-family: var(--font-display);
  font-size: var(--text-lg);
  font-weight: 650;
  letter-spacing: -0.02em;
  line-height: 1.4;
  overflow-wrap: anywhere;
}

.agent-inspector-meta {
  margin: 0;
  color: var(--ink-mist);
  font-size: var(--text-2xs);
  line-height: 1.7;
  overflow-wrap: anywhere;
}

.agent-inspector-id {
  font-family: var(--font-mono);
}

.agent-inspector-breadcrumb {
  color: var(--ink-mist);
  font-size: var(--text-2xs);
  line-height: 1.5;
}

.agent-inspector-breadcrumb > span {
  color: var(--ink-label);
}

.agent-inspector-breadcrumb .agent-inspector-lineage {
  color: var(--accent-ink, var(--ink-chalk));
}

.agent-inspector-body {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: var(--space-3);
  min-height: 0;
  padding: var(--space-5);
  overflow: auto;
  scrollbar-width: thin;
}

.agent-inspector-body .board-card {
  width: 100%;
  border-radius: var(--agent-graph-card-radius);
  cursor: default;
}

.agent-inspector-body .board-card:hover {
  border-color: color-mix(in srgb, var(--edge-rule) 60%, transparent);
  background: var(--surface-deck);
}

.agent-inspector-facts {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.agent-inspector-facts p {
  margin: 0;
}

.agent-inspector-summary-card {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  padding: var(--space-3);
  border: var(--rule-width) solid color-mix(in srgb, var(--edge-rule) 80%, transparent);
  border-radius: var(--radius-sm);
  background: color-mix(in srgb, var(--surface-well) 60%, transparent);
}

.agent-inspector-stats {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(80px, 1fr));
  gap: var(--space-2);
}

.agent-inspector-stat-item {
  display: flex;
  flex-direction: column;
  gap: var(--agent-graph-gap-tight);
  min-width: 0;
  padding: var(--space-2);
  border: var(--rule-width) solid color-mix(in srgb, var(--edge-rule) 60%, transparent);
  border-radius: var(--radius-xs);
  background: color-mix(in srgb, var(--surface-deck) 70%, transparent);
}

.agent-inspector-stat-item b {
  min-width: 0;
  overflow-wrap: anywhere;
  word-break: break-word;
  color: var(--ink-chalk);
  font-family: var(--font-display);
  font-size: var(--text-sm);
  font-weight: 600;
  line-height: 1.2;
}

.agent-inspector-stat-item span {
  color: var(--ink-mist);
  font-size: var(--text-3xs);
  font-weight: 500;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.agent-inspector-triples {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
}

/* Subject, relation, object. The canvas draws the relations as lines because a
 * line is readable at a glance; this says them in words, because a line cannot
 * say WHICH relation it is once two of them meet at the same node. */
.agent-inspector-triple {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1.2fr);
  gap: var(--space-2);
  align-items: center;
  padding: var(--agent-graph-gap) var(--space-2);
  border: var(--rule-width) solid color-mix(in srgb, var(--edge-rule) 80%, transparent);
  border-radius: var(--radius-xs);
  background: color-mix(in srgb, var(--surface-well) 50%, transparent);
  font-size: var(--text-2xs);
  transition:
    background-color var(--motion-fast) var(--ease-standard),
    border-color var(--motion-fast) var(--ease-standard);
}

.agent-inspector-triple.is-navigable {
  cursor: pointer;
}

.agent-inspector-triple.is-navigable:hover,
.agent-inspector-triple.is-navigable:focus-visible {
  border-color: var(--edge-mark);
  background: var(--surface-raised);
  outline: none;
}

.agent-inspector-triple span {
  overflow: hidden;
  color: var(--ink-mist);
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agent-inspector-triple em {
  padding: var(--agent-graph-chip-inset);
  border: var(--rule-width) solid color-mix(in srgb, var(--ink-chalk) 12%, transparent);
  border-radius: var(--radius-pill);
  background: color-mix(in srgb, var(--surface-deck) 80%, transparent);
  color: var(--ink-label);
  font-size: var(--text-3xs);
  font-style: normal;
  font-weight: 500;
  letter-spacing: 0.04em;
  white-space: nowrap;
}

.agent-inspector-triple strong {
  overflow-wrap: anywhere;
  color: var(--ink-chalk);
  font-weight: 600;
}

/* 연대기는 레일을 따라 내려간다 (round three). 스무 줄의 회색 목록이 아니라
 * 한 줄의 레일에 구슬을 꿴 것 — 위가 새것이고, 새것만 밝다. */
.agent-inspector-stream .agent-graph-wire.is-stream {
  max-height: var(--agent-graph-stream-height);
  overflow-y: auto;
  padding: var(--space-1) 0 var(--space-1) var(--space-2);
  gap: 0;
  border-top: 0;
  border-left: var(--rule-width) solid var(--edge-rule);
}

.agent-inspector-backtrace {
  padding: var(--space-3);
  border-bottom: var(--rule-width) solid var(--edge-rule);
}

.agent-inspector-backtrace[hidden] {
  display: none;
}

.agent-inspector-backtrace ol {
  display: grid;
  gap: var(--space-1);
  margin: 0;
  padding-left: var(--space-4);
  color: var(--ink-label);
  font-size: var(--text-2xs);
}

.agent-inspector-more {
  align-self: flex-start;
  margin-top: var(--space-2);
  padding: var(--space-1) var(--space-2);
  font-size: var(--text-2xs);
}

.agent-inspector-stream .agent-graph-beat-summary {
  grid-template-columns: 14px auto minmax(0, 1fr) auto auto;
  gap: var(--agent-graph-gap);
  padding-block: 3px;
  font-size: var(--text-2xs);
  line-height: 1.45;
}

.agent-inspector-stream .agent-graph-beat-target {
  font-family: inherit;
  white-space: nowrap;
}

.agent-inspector-stream .agent-graph-beat-target.is-mono,
.agent-inspector-stream .agent-graph-beat[data-verb="bash"] .agent-graph-beat-target {
  font-family: var(--font-mono);
}

.agent-inspector-stream-quiet {
  margin: 0;
  color: var(--ink-mist);
  font-size: var(--text-2xs);
}

.agent-inspector-context-actions {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  margin-top: var(--space-2);
  padding-top: var(--space-3);
  border-top: var(--rule-width) solid var(--edge-rule);
}

.agent-inspector-context-actions > .btn {
  align-self: flex-start;
  padding: var(--space-1) var(--space-3);
  border-radius: var(--radius-xs);
  font-weight: 500;
  transition:
    background-color var(--motion-fast) var(--ease-standard),
    border-color var(--motion-fast) var(--ease-standard),
    color var(--motion-fast) var(--ease-standard);
}

.agent-inspector-context-heading {
  margin: var(--space-2) 0 var(--space-1);
  color: var(--ink-glyph);
  font-family: var(--font-display);
  font-size: var(--text-3xs);
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.agent-inspector-triples > .agent-inspector-context-heading {
  margin-top: 0;
}

.agent-inspector-agent {
  display: flex;
  gap: var(--space-2);
  align-items: center;
  width: 100%;
  padding: var(--agent-graph-gap) var(--space-2);
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-xs);
  background: var(--surface-well);
  color: var(--ink-chalk);
  font: inherit;
  font-size: var(--text-xs);
  text-align: left;
  cursor: pointer;
  transition:
    background-color var(--motion-fast) var(--ease-standard),
    border-color var(--motion-fast) var(--ease-standard),
    color var(--motion-fast) var(--ease-standard);
}

.agent-inspector-agent:hover,
.agent-inspector-agent:focus-visible {
  border-color: var(--edge-mark);
  background: var(--surface-raised);
  outline: none;
}

.agent-inspector-agent > :last-child {
  display: grid;
  place-items: center;
  margin-left: auto;
  color: var(--ink-mist);
}

.agent-inspector-agent > :last-child .icon {
  width: 12px;
  height: 12px;
}

.agent-inspector-actions {
  display: flex;
  flex: none;
  flex-direction: column;
  gap: var(--space-2);
  padding: var(--space-4) var(--space-5);
  border-top: var(--rule-width) solid var(--edge-rule);
}

.agent-inspector-actions > .btn {
  justify-content: center;
  width: 100%;
  font-size: var(--text-2xs);
}

.agent-inspector-actions[hidden] {
  display: none;
}

@keyframes zc-graph-pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.45; transform: scale(0.72); }
}

@keyframes zc-graph-beat-in {
  from { opacity: 0; transform: translateY(-3px); }
  to { opacity: 1; transform: none; }
}

@keyframes zc-graph-node-in {
  from { opacity: 0; transform: translateX(-6px); }
  to { opacity: 1; transform: none; }
}

@keyframes zc-graph-mail-flow {
  to { stroke-dashoffset: -18; }
}

@keyframes zc-graph-mail-pulse {
  0%, 100% { opacity: 0.25; transform: scale(0.72); }
  50% { opacity: 1; transform: scale(1.18); }
}

/* 움직임을 끈 사람에게는 맥박이 색으로 남는다 — 사라지지 않는다. 무엇이
 * 실행 중인지는 이 표면이 존재하는 이유이고, 애니메이션은 그것을 말하는 한
 * 가지 방법일 뿐이다. */
@media (prefers-reduced-motion: reduce) {
  .agent-graph-stat.is-working .agent-graph-stat-mark,
  .agent-graph-node-state.is-working::before,
  .agent-graph-beat.is-started .agent-graph-beat-mark,
  .agent-graph-wire > .agent-graph-beat:first-child,
  .agent-card-activity[data-beat="a"],
  .agent-card-activity[data-beat="b"] {
    animation: none;
  }

  /* 서랍·시트·미터·검색은 미끄러지지 않고 그냥 그 자리에 선다 (t-2374). */
  .agent-inspector,
  .agent-graph-scrim,
  .agent-graph-overlay-controls,
  .agent-card-meter-fill,
  .agent-relations-rail-item {
    transition: none;
  }

  .agent-graph-node.is-agent {
    animation: none;
  }

  .agent-graph-stat.is-working .agent-graph-stat-mark,
  .agent-graph-node-state.is-working::before {
    border-top-color: var(--signal-ready);
  }

  .agent-graph-edge.is-selected {
    stroke-dasharray: none;
    animation: none;
  }

  .agent-graph-edge.is-mail,
  .agent-graph-mail-pulse {
    animation: none;
  }
}

/* ---- 세 티어, DOM 하나 (t-2374) -------------------------------------------
 *
 * 여기 있던 것은 `@container 600 / 300` 둘이었고, 좁은 판에서 하는 일이
 * 「인스펙터를 아래로」와 「범례를 `display: none`」이었다. 둘 다 모자랐다.
 *
 * ① **가로 스크롤.** 자동 맞춤은 폭을 나누고 바닥은 밀도의 역수(0.65)이므로,
 * 세 레인이 담기지 않는 폭에서는 그림이 바닥까지 눌린 뒤 옆으로 흘렀다 —
 * 실측: 560px 판에서 레인 셋은 267 × 3 × 0.65 = 520, 간격 둘 20 × 1.0 = 40,
 * 판의 여백 48 → 608px. 에이전트 셋을 한 화면에 보려고 그림을 여는 사람에게
 * 가로 스크롤은 실패다. 그래서 700 아래는 **목록 모드**다: 같은 격자가 한
 * 열로 접히고 층은 열이 아니라 들여쓰기가 말한다.
 *
 * ② **지운 목적지.** `display: none`이 된 범례는 좁은 화면의 사람에게만
 * 없는 것이 되고, 그것을 여는 단추는 없는 것을 열었다고 말했다
 * (`aria-expanded="true"`). 여기서 목적지는 지워지지 않는다 — 접히거나
 * 팝오버로 옮겨 앉는다(direction.md §3).
 *
 * 문턱 셋은 `--agent-graph-tier-*`에 적혀 있다. 컨테이너 쿼리의 조건에는
 * `var()`가 들어가지 못하므로 그 수가 아래 조건에 한 번 더 서 있고, 이 주석이
 * 그 사본을 짊어진다 — JS는 토큰에서 읽으므로 세 번째 사본은 없다
 * (`agentGraphTierWidths`).
 *
 * 질의는 `board`라는 이름을 부른다 (round three): 그림의 스크롤 판도 이제
 * 컨테이너이므로(레인의 몫을 재는 `cqw`의 기준), 이름 없는 질의는 안쪽 노드에
 * 대해 그 판을 잡는다. 티어는 보드의 폭이지 판의 폭이 아니다.
 *
 * DOM 은 하나다. 아래 어느 블록도 새 렌더 경로를 만들지 않는다: `data-graph-part`
 * 로 키를 맨 같은 노드가 같은 순서로 서 있고, 격자만 다시 접힌다. JS가 인라인
 * 으로 써 넣은 좌표를 되돌리는 자리에만 `!important`가 서는데, 그것이 곧
 * 「좌표는 JS가, 배치는 CSS가」라는 이 절의 계약이다. */

/* ---- 티어 ②: 서랍 (`--agent-graph-tier-side`, 1100px) ---- */
@container board (max-width: 1099px) {
  /* 인스펙터가 제 열을 내어놓고 그림 위로 미끄러진다. 자리를 나눠 갖기에는
   * 둘 다 좁고, 사라지기에는 인스펙터가 이 표면의 절반이다. */
  .agent-graph-layout {
    position: relative;
    /* 닫힌 서랍은 오른쪽으로 101% 밀려 서 있고, 밀린 상자도 스크롤 넓이에는
     * 든다 — 그래서 이 자름이 없으면 판 자체가 옆으로 흐른다(실측: 900px
     * 판에서 `scrollWidth > clientWidth`). 안쪽 그림은 제 스크롤 판을 따로
     * 들고 있으므로 잘려 잃는 것은 없다. */
    overflow: hidden;
    grid-template-columns: minmax(0, 1fr);
  }

  .agent-inspector {
    position: absolute;
    z-index: 7;
    inset-block: 0;
    right: 0;
    width: min(var(--agent-graph-drawer-width), 100%);
    border-left: var(--rule-width) solid var(--edge-rule);
    background: var(--workbench-ambient-crown), var(--surface-deck);
    box-shadow: var(--shadow-node-raised);
    transform: translateX(101%);
    transition: transform var(--motion-panel, var(--motion-dialog)) var(--ease-standard);
  }

  .file-view.is-inspector-open .agent-inspector {
    transform: none;
  }

  /* 열려 있는 동안에만 서는 배경막. 서랍의 일부이지 목적지가 아니므로, 서랍이
   * 없는 폭에서는 이것도 없다. */
  .agent-graph-scrim {
    display: block;
  }

  .icon-btn.agent-inspector-close {
    display: inline-flex;
  }

  /* 오버레이 셋은 세그먼트 하나 뒤로 물러난다 — 지우는 것이 아니라 옮기는
   * 것이라 세 단추는 그대로 DOM에 있고, 팝오버는 흐름 밖이라 자리도 뺏지
   * 않는다. `visibility`인 것은 `display: none`이 그 셋을 낭독기에서까지
   * 지우기 때문이다: 닫힌 팝오버는 없는 것이 아니라 닫힌 것이다. */
  .icon-btn.agent-graph-overlay-toggle {
    display: inline-flex;
  }

  .agent-graph-overlay-controls {
    position: absolute;
    z-index: 8;
    top: calc(100% + var(--space-1));
    right: 0;
    visibility: hidden;
    padding: var(--space-1);
    border: var(--rule-width) solid var(--edge-rule);
    border-radius: var(--radius-sm);
    background: var(--surface-raised);
    box-shadow: var(--shadow-node-raised);
    opacity: 0;
    transition:
      opacity var(--motion-fast) var(--ease-standard),
      visibility var(--motion-fast) var(--ease-standard);
  }

  .file-view.is-overlays-open .agent-graph-overlay-controls {
    visibility: visible;
    opacity: 1;
  }

  /* 시안의 사이드바가 좁아지는 폭 (t-4145): 레일은 서랍 폭의 그 수로 줄고,
   * 서랍의 손잡이가 머리에 선다. 그림 판의 옆 여백은 한 단 줄어, 2레인 그림이
   * 맞춤 바닥에서도 이 티어의 가장 좁은 폭(700)에 든다 — 실측: 레일 155 +
   * 여백 32 를 뺀 513px ≥ 필요 504px. */
  .agent-relations-rail {
    width: var(--agent-relations-rail-width-drawer);
  }

  .icon-btn.agent-inspector-toggle {
    display: inline-flex;
  }

  .agent-graph-scroll {
    padding-inline: var(--space-4);
  }

  .board-search-keys {
    display: none;
  }
}

/* ---- 티어 ③: 목록 (`--agent-graph-tier-list`, 700px) ---- */
@container board (max-width: 699px) {
  /* 같은 격자, 한 열. JS가 써 넣은 열 번호를 CSS가 되돌리는 유일한 자리이고,
   * 그것이 이 절의 계약이다 — 좌표는 JS가 알고 **배치**는 CSS가 안다. */
  .agent-graph-nodes {
    grid-template-columns: minmax(0, 1fr) !important;
    width: 100%;
    column-gap: 0;
  }

  /* 열뿐 아니라 **행**도 CSS가 다시 놓는다 (t-2374).
   *
   * 행 번호는 레인 배치의 좌표다 — 부모와 자식은 서로 다른 열에 나란히 서므로
   * 같은 행을 받는다. 한 열로 접으면 그 둘이 같은 자리에 겹쳐 그려지고,
   * 실측한 그림에서 카드 하나가 다른 하나 밑으로 사라졌다(560px: term:2390과
   * term:2391이 둘 다 row 3). `auto`로 흘리면 DOM 순서가 곧 차례가 되는데,
   * 그 순서는 이미 담김의 순서다 — 띠 머리, 워크스페이스, 그 워크스페이스가
   * 품은 에이전트들, 각자의 헬퍼가 바로 뒤에(`paintAgentGraph`). 목록이
   * 원하는 차례가 정확히 그것이고, `role="tree"` 걷기도 같은 순서를 쓴다. */
  .agent-graph-nodes > [data-graph-part] {
    grid-column: 1 !important;
    grid-row: auto !important;
  }

  /* 띠의 바탕과 워크스페이스의 수영 레인은 **격자의 배경**이다: 여러 행에
   * 걸쳐 그 뒤를 칠하는 것이 하는 일의 전부이고, 둘 다 `aria-hidden`이다.
   * 한 열에서는 걸칠 행이 없으므로 흐름에 빈 칸만 만든다 — 담김을 말하는
   * 일은 들여쓰기와 레일이 이어받았고, lane 색도 카드의 제 테두리로 옮겼다. */
  .agent-graph-band,
  .agent-graph-swimlane {
    display: none;
  }

  .agent-graph-canvas {
    width: 100%;
  }

  /* 층은 이제 열이 아니라 들여쓰기가 말한다. 레일은 사이드바의 워크트리 행이
   * 쓰는 그 두께이고(`--rail-width`), 자리는 카드 제 왼쪽 테두리다 — 상태
   * 레일(`::before`)은 그 안쪽에 서므로 둘이 겹치지 않는다: 바깥이 혈통,
   * 안쪽이 상태. */
  .agent-graph-node {
    /* 들여쓰기는 **자리에서** 나온다 — `width: 100%`인 채로 왼쪽 여백을 주면
     * 카드가 제 열 밖으로 그만큼 밀려 나가고, 그것이 이 티어가 없애려던 바로
     * 그 가로 넘침이다. */
    width: auto;
    margin-inline-start: calc(var(--graph-depth, 0) * var(--nav-indent));
    border-inline-start: var(--rail-width) solid var(--edge-mark);
  }

  .agent-graph-node.is-agent {
    border-inline-start-color: color-mix(
      in srgb,
      var(--lane, var(--lane-1)) 55%,
      transparent
    );
  }

  /* 이름표는 목록에서 절의 소제목이 된다. 레인 색 레일은 넓은 판에서처럼
   * 제 `::before`가 들고(어느 티어에서도 같은 3px), 테두리 쪽은 비운다 —
   * 둘 다 서면 레일이 둘이다. */
  .agent-graph-node.is-workspace {
    border-inline-start-color: transparent;
    border-radius: 0;
  }

  /* 한 열에 lineage 선은 그릴 자리가 없다 — 들여쓰기가 이미 그 말을 한다.
   * 지우지 않고 물러나게 하는 것은 이 그림이 다시 넓어질 때 같은 `<path>`가
   * 같은 자리에 서야 하기 때문이다. */
  .agent-graph-edges {
    visibility: hidden;
  }

  /* 열이 없는 자리에 열 이름은 설명이 아니라 잡음이다. 목적지가 아니라
   * 사라진 축의 눈금이므로 이것은 접는다. */
  .agent-graph-lane {
    display: none;
  }

  /* 띠 머리의 수도 접는다 — 한 열에서 「3 워크스페이스 · 2 에이전트」는
   * 상태 칩과 자리를 다투다 「3」만 남는 줄이었다. 이름과 상태가 남는다. */
  .agent-graph-band-line {
    display: none;
  }

  /* 인스펙터는 아래에서 올라오는 시트로. 서랍만 한 폭이 없으면 남은 축은
   * 세로뿐이고, 비율과 바닥 높이를 함께 두는 것은 짧은 판에서 시트가 제
   * 머리조차 담지 못하는 일을 막기 위해서다. */
  .agent-inspector {
    inset-block: auto 0;
    inset-inline: 0;
    width: auto;
    height: max(var(--agent-graph-sheet-min-height), var(--agent-graph-sheet-height));
    border-left: 0;
    border-top: var(--rule-width) solid var(--edge-rule);
    border-radius: var(--radius) var(--radius) 0 0;
    transform: translateY(101%);
  }

  /* 시안은 이 폭에서 사이드바를 아이콘만 남기고 작업 목록을 접었다 — 여기서
   * 목록은 레일이고, 범위 선택이 툴바에 남으므로 목적지는 그대로다. */
  .agent-relations-rail {
    display: none;
  }

  .agent-relations-toolbar .board-search {
    flex: 1 1 12em;
    margin-left: 0;
  }

  .agent-graph-canvas-head {
    padding-inline: var(--space-4);
  }
}

/* ---- 티어 ④: 좁음 (`--agent-graph-tier-tight`, 400px) ---- */
@container board (max-width: 399px) {
  .agent-graph-scroll {
    padding: var(--space-3);
  }

  /* 상태 칩은 점과 숫자만 남는다. 낱말을 DOM에서 지우지 않는 것은 마크가
   * `aria-hidden`이기 때문이다 — 지우면 단추에 남는 이름이 「0」이 된다.
   * 아래 여섯 줄은 이 시트의 `.sr` 그대로이고, 클래스로 붙이지 못하는 것은
   * 이 감춤이 보드의 폭에 딸린 조건이며 마크업의 클래스는 폭을 모르기
   * 때문이다. 상태는 색만으로 갈리지 않는다: 모양과 숫자가 남고 같은 세
   * 낱말이 범례에 그대로 서 있다. */
  .agent-graph-stat {
    padding-inline: var(--space-1);
  }

  .agent-graph-stat > span:not(.agent-graph-stat-mark) {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  /* 범례는 팝오버로 물러난다 — `display: none`이 아니다 (direction.md §3).
   * 여기 있던 규칙은 범례와 그것을 여는 단추를 함께 지웠고, 그래서 좁은
   * 화면의 사람만 이 그림의 선 둘과 상태 다섯을 읽을 방법이 없었다. */
  .agent-graph-legend {
    position: absolute;
    z-index: 6;
    right: var(--space-3);
    bottom: var(--space-3);
    left: var(--space-3);
    max-height: 40%;
    overflow: auto;
    border-radius: var(--radius-sm);
    background: var(--surface-raised);
    box-shadow: var(--shadow-node-raised);
  }

  /* 카드는 정체·상태·활동 줄만. 띠와 미터와 발화는 접힌다 — 여기서 그 셋은
   * 한 줄에 들어가지 못하고, 들어가지 못한 줄은 정보가 아니라 말줄임표다. */
  .agent-card-ticker,
  .agent-card-meter,
  .agent-card-meta,
  .agent-graph-node-message {
    display: none;
  }
}

/* Orca: `group flex w-full flex-col gap-1.5 rounded-lg border p-2.5 text-left
 * transition-colors`. The border is drawn at rest so the hover state arrives as
 * colour and never as a size change — the same rule the workspace card follows. */
.board-card {
  /* The branch rails of a nested card are drawn in its own margin, so the card
   * is their positioning context. */
  position: relative;
  margin-left: calc(var(--card-depth, 0) * var(--nav-indent));
  display: flex;
  flex: none;
  flex-direction: column;
  gap: var(--agent-graph-gap);
  padding: var(--space-3);
  border: var(--rule-width) solid color-mix(in srgb, var(--edge-rule) 60%, transparent);
  /* 그래프의 카드와 같은 반경 (round three) — 한 화면의 두 그림이 같은
   * 에이전트를 다른 모양으로 그리지 않는다. */
  border-radius: var(--agent-graph-card-radius);
  background: var(--surface-deck);
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
  /* Orca's `transition-colors` is the default .15s, not the 200ms the
   * workspace card uses — a board card answers a pointer sweeping across a
   * column, where the card in the sidebar answers a considered click. */
  transition:
    background-color var(--motion-fast) var(--ease-standard),
    border-color var(--motion-fast) var(--ease-standard);
}

.board-card:hover,
.board-card:focus-visible {
  border-color: var(--edge-mark);
  background: var(--row-hover);
  outline: none;
}

/* The two states that carry a hue, and Orca's own pairing: amber for a card
 * that wants a person, emerald for one that has finished. Everything between
 * keeps the ordinary surface — three coloured columns would be no signal at
 * all. */
.board-card.is-needs-attention,
.board-card.is-waiting,
.board-card.is-blocked,
.board-card.is-awaiting_permission {
  border-color: color-mix(in srgb, var(--signal-wait) 40%, transparent);
  background: color-mix(in srgb, var(--signal-wait) 6%, var(--surface-deck));
}

.board-card.is-needs-attention:hover,
.board-card.is-waiting:hover,
.board-card.is-blocked:hover,
.board-card.is-awaiting_permission:hover {
  border-color: color-mix(in srgb, var(--signal-wait) 60%, transparent);
  background: color-mix(in srgb, var(--signal-wait) 10%, var(--surface-deck));
}

.board-card.is-done,
.board-card.is-exited {
  border-color: color-mix(in srgb, var(--signal-done) 40%, transparent);
  background: color-mix(in srgb, var(--signal-done) 6%, var(--surface-deck));
}

.board-card.is-done:hover,
.board-card.is-exited:hover {
  border-color: color-mix(in srgb, var(--signal-done) 60%, transparent);
  background: color-mix(in srgb, var(--signal-done) 10%, var(--surface-deck));
}

/* Done, and seen: the dress settles — Orca's `dashboardCardDisplayState`
 * returns idle for an acked done card ("Completed agents stay green until
 * acknowledged, then settle into gray idle", dashboard-snapshot.ts:39-43),
 * and the emerald is keyed to that display state (AgentKanbanCard.tsx). The
 * column stays: buckets read the raw state, only the dress reads the
 * display. */
.board-card.is-done.is-settled,
.board-card.is-exited.is-settled {
  border-color: color-mix(in srgb, var(--edge-rule) 60%, transparent);
  background: var(--surface-deck);
}

.board-card.is-done.is-settled:hover,
.board-card.is-exited.is-settled:hover {
  border-color: var(--edge-mark);
  background: var(--row-hover);
}

/* The footer's leading tiles — Orca's 18px `rounded-[5px]` glyph chips on a
 * tenth-strength fill: the repo first, then the machine when it is not this
 * one (AgentKanbanCard.tsx footer; DashboardHostBadge renders nothing for a
 * local card). */
.board-card-repo,
.board-card-host {
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  border-radius: 5px;
  background: color-mix(in srgb, var(--ink-mist) 10%, transparent);
  color: var(--ink-mist);
}

.board-card-repo svg,
.board-card-host svg {
  width: 12px;
  height: 12px;
}

.board-card-head {
  display: flex;
  gap: var(--agent-graph-gap);
  align-items: center;
  min-width: 0;
}

.board-card-mark {
  flex: none;
}

/* Orca's `text-[12.5px]`, which is a real measurement and not a rounding — the
 * card's heading is deliberately between this window's xs and sm. */
/* Muted and ordinary by default, semibold full ink while unseen — Orca's
 * measured pair (`font-normal text-muted-foreground` against
 * `font-semibold text-foreground`, I18nProvider:96425). The weight is the
 * unseen signal; the dot beside it stays the agent's. */
.board-card-heading {
  flex: 1;
  overflow: hidden;
  color: var(--ink-mist);
  font-size: 12.5px;
  font-weight: 400;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.board-card.is-unseen .board-card-heading {
  color: var(--ink-chalk);
  font-weight: 600;
}

/* The precise state, where the column carries only the coarse one — and in
 * the state's own shape, Orca's AgentStateDot vocabulary: a spinner while
 * working, a check when done "so completion is visually distinct from 'idle'
 * (grey dot)", the question glyph for the attention family, and the grey dot
 * for everything quiet (AgentStateDot.tsx). The spinner ring is the
 * sidebar's measured one — `border-2 border-t-transparent`, `animate-spin`
 * at `1s steps(12)` — because the two surfaces share one state vocabulary. */
.board-card-state {
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
}

.board-card-state.is-dot {
  width: 6px;
  height: 6px;
  border-radius: var(--radius-pill);
  background: var(--ink-glyph);
}

.board-card-state.is-spin {
  width: 10px;
  height: 10px;
  border: 2px solid var(--signal-ready);
  border-top-color: transparent;
  border-radius: var(--radius-pill);
  animation: wt-agent-spin 1s steps(12, end) infinite;
}

.board-card-state.is-check {
  color: var(--signal-done);
}

.board-card-state.is-ask {
  color: var(--signal-wait);
}

.board-card-state.is-check svg,
.board-card-state.is-ask svg {
  width: 12px;
  height: 12px;
}

.board-card-task {
  overflow: hidden;
  /* Orca clamps this to two lines (`line-clamp-2`): a card is a summary, and a
   * prompt somebody pasted is often a page. */
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  color: color-mix(in srgb, var(--ink-chalk) 90%, transparent);
  font-size: var(--text-xs);
  line-height: 1.375;
}

/* The conversation's two lines, in the task's spot. Orca's measured clamp is
 * asymmetric on purpose (I18nProvider-4EBrmTGg.js:96433-96438): the question
 * gets ONE line at 11px, the answer TWO at xs — the answer is what a
 * supervisor is scanning for, the question is only its context. */
.board-card-you,
.board-card-said {
  overflow: hidden;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  line-height: 1.375;
}

.board-card-you {
  -webkit-line-clamp: 1;
  color: var(--ink-mist);
  font-size: var(--text-2xs);
}

.board-card-said {
  -webkit-line-clamp: 2;
  color: color-mix(in srgb, var(--ink-chalk) 90%, transparent);
  font-size: var(--text-xs);
}

/* Who said it — Orca's `text-foreground/45` prefix on both lines. */
.board-card-who {
  color: color-mix(in srgb, var(--ink-chalk) 45%, transparent);
  font-weight: 500;
}

/* The question the agent is stuck on. Orca's measured box: amber at a tenth
 * for the fill, the text in the signal colour itself, 11px, the icon 12px and
 * pinned to the first line (`items-start` + `mt-px`) so a two-line question
 * does not centre it (I18nProvider-4EBrmTGg.js:96444-96448). The waiting
 * signal is this window's amber — the same hue the card's dot would have
 * shown, which is why the dot goes away when this is on. */
.board-card-ask {
  display: flex;
  gap: var(--space-1);
  align-items: flex-start;
  padding: var(--space-1) 6px;
  border-radius: var(--radius-sm);
  background: color-mix(in srgb, var(--signal-wait) 10%, transparent);
  color: var(--signal-wait);
  font-size: var(--text-2xs);
  line-height: 1.375;
}

.board-card-ask svg {
  flex: none;
  margin-top: 1px;
  width: 12px;
  height: 12px;
}

.board-card-ask-words {
  overflow: hidden;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

/* When the question carries its choices, the amber box is a real button and
 * says so on hover. Its own styling stays exactly the summary box's. */
.board-card-ask.is-openable {
  width: 100%;
  border: none;
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.board-card-ask.is-openable:hover {
  background: color-mix(in srgb, var(--signal-wait) 16%, transparent);
}

/* The answer panel, unfolded under the amber box — Orca's ask card
 * (`NativeChatQuestionCard`) at card scale: a bordered sheet, option rows
 * divided by rules, the free-text row at the bottom with the one button. */
.board-ask {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
}

.board-ask-steps {
  display: flex;
  gap: var(--space-1);
  overflow-x: auto;
}

.board-ask-step {
  flex: none;
  padding: 2px 6px;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--ink-mist);
  font: inherit;
  font-size: var(--text-2xs);
  font-weight: 500;
  cursor: pointer;
}

.board-ask-step:hover {
  color: var(--ink-chalk);
}

.board-ask-step.is-here {
  background: var(--row-hover);
  color: var(--ink-chalk);
}

.board-ask-step.is-answered::after {
  content: " ✓";
}

.board-ask-question {
  overflow: hidden;
  padding: 2px 0;
  color: var(--ink-chalk);
  font-size: var(--text-xs);
  font-weight: 600;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.board-ask-rows {
  display: flex;
  overflow: hidden;
  flex-direction: column;
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-sm);
  background: var(--surface-well);
}

.board-ask-rows > :not(:first-child) {
  border-top: var(--rule-width) solid var(--edge-rule);
}

.board-ask-option {
  display: flex;
  gap: var(--space-2);
  align-items: center;
  padding: var(--agent-graph-gap) var(--space-2);
  border: none;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.board-ask-option:hover {
  background: var(--row-hover);
}

.board-ask-option.is-picked {
  background: var(--row-selected);
}

.board-ask-badge {
  display: flex;
  flex: none;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  border-radius: var(--radius-sm);
  background: var(--surface-raised);
  color: var(--ink-mist);
  font-size: var(--text-3xs);
  font-weight: 500;
}

.board-ask-option.is-picked .board-ask-badge {
  background: var(--ink-chalk);
  color: var(--surface-abyss);
}

.board-ask-option-words {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.board-ask-option-label {
  overflow: hidden;
  color: var(--ink-chalk);
  font-size: var(--text-xs);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.board-ask-option-description {
  overflow: hidden;
  color: var(--ink-mist);
  font-size: var(--text-2xs);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.board-ask-other {
  display: flex;
  gap: var(--space-2);
  align-items: center;
  padding: 5px var(--space-2);
}

.board-ask-field {
  flex: 1;
  min-width: 0;
  border: none;
  background: transparent;
  color: var(--ink-chalk);
  font: inherit;
  font-size: var(--text-xs);
  outline: none;
}

.board-ask-field::placeholder {
  color: var(--ink-mist);
}

.board-ask-send {
  flex: none;
  padding: 3px 10px;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--ink-mist);
  font: inherit;
  font-size: var(--text-2xs);
  font-weight: 600;
  cursor: pointer;
}

.board-ask-send:hover {
  background: var(--row-hover);
  color: var(--ink-chalk);
}

.board-ask-send.is-live {
  background: var(--ink-chalk);
  color: var(--surface-abyss);
}

.board-ask-send:disabled,
.board-ask-option:disabled,
.board-ask-step:disabled,
.board-ask-field:disabled {
  opacity: 0.55;
  cursor: default;
}

.board-ask-count {
  color: var(--ink-mist);
  font-size: var(--text-2xs);
  text-align: right;
}

/* The approval panel, unfolded under the same amber box — Orca's
 * NativeChatApprovalCard: the shield and the question in a strong weight,
 * the summary in mono, Allow filled and Deny bordered. */
.board-approve {
  display: flex;
  flex-direction: column;
  gap: var(--agent-graph-gap);
  padding: var(--space-2);
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-sm);
  background: var(--surface-well);
}

.board-approve-title {
  display: flex;
  gap: var(--agent-graph-gap);
  align-items: flex-start;
  color: var(--ink-chalk);
  font-size: var(--text-xs);
  font-weight: 600;
}

.board-approve-title svg {
  flex: none;
  margin-top: 1px;
  width: 14px;
  height: 14px;
  color: var(--ink-mist);
}

.board-approve-detail {
  overflow-wrap: break-word;
  color: var(--ink-mist);
  font-family: var(--font-mono);
  font-size: var(--text-2xs);
}

.board-approve-acts {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
}

.board-approve-act {
  padding: 3px var(--space-3);
  border: var(--rule-width) solid transparent;
  border-radius: var(--radius-sm);
  font: inherit;
  font-size: var(--text-2xs);
  font-weight: 600;
  cursor: pointer;
}

.board-approve-act.is-allow {
  border-color: var(--ink-chalk);
  background: var(--ink-chalk);
  color: var(--surface-abyss);
}

.board-approve-act.is-allow:hover {
  background: color-mix(in srgb, var(--ink-chalk) 90%, transparent);
}

.board-approve-act.is-deny {
  border-color: var(--edge-rule);
  background: transparent;
  color: var(--ink-chalk);
}

.board-approve-act.is-deny:hover {
  background: var(--row-hover);
}

/* The conversation's third road: decline, and say what to do instead. */
.board-approve-act.is-instead {
  border-color: var(--edge-rule);
  color: var(--ink-chalk);
  background: none;
}

.board-approve-act.is-instead:hover {
  border-color: var(--chat-accent);
}

.board-approve-act:disabled {
  opacity: 0.55;
  cursor: default;
}

/* The tail of what this agent is printing, right on the card.
 *
 * The one surface in this window that shows every agent at once, and until it
 * existed there was none: the stage unhides one tab's panes, so however many
 * agents were running exactly one screen was live and the rest stopped at the
 * pump ("지금 에이전트가 떠도 화면을 볼수없음").
 *
 * Words only — no colour. The ink rules (bold's bright promotion, the contrast
 * floor the screen decides) live inside the terminal view and are not copied
 * here; a card answers "what is this agent doing", and that answer is text.
 * `pre-wrap` rather than `pre` so a long line folds instead of widening the
 * column, and the box crops at its own height rather than scrolling — a card
 * is not a place to read from, it is a place to notice from. */
.board-card-screen {
  overflow: hidden;
  max-height: calc(
    var(--card-screen-font-size) * var(--card-screen-leading) * var(--card-screen-max-rows)
  );
  padding: var(--agent-graph-gap) var(--space-2);
  border-radius: var(--radius-sm);
  background: color-mix(in srgb, var(--term-screen-bg) 55%, transparent);
  color: color-mix(in srgb, var(--ink-chalk) 70%, transparent);
  font-size: var(--card-screen-font-size);
  font-family: var(--font-mono);
  line-height: var(--card-screen-leading);
  white-space: pre-wrap;
  /* The tail's newest line sits at the BOTTOM, so a box that crops must crop
   * from the top — the last thing printed is the thing worth seeing. */
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
}

/* 인스펙터의 화면 꼬리는 더 크고 더 길다 (round three). 사람이 카드를 골라
 * 곁판을 여는 이유가 「지금 무엇을 찍고 있는가」이므로, 여기서 꼬리는 카드의
 * 곁가지가 아니라 본문이다 — 아홉 줄, 11px, 제 테두리. */
.agent-inspector-body .board-card-screen {
  max-height: calc(
    var(--agent-graph-screen-text) * var(--card-screen-leading) * var(--agent-graph-screen-rows)
  );
  padding: var(--space-2) var(--space-3);
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-sm);
  background: color-mix(in srgb, var(--term-screen-bg) 75%, transparent);
  color: color-mix(in srgb, var(--ink-chalk) 82%, transparent);
  font-size: var(--agent-graph-screen-text);
}

.board-card-foot {
  display: flex;
  gap: var(--space-2);
  align-items: center;
  min-width: 0;
  color: var(--ink-mist);
  font-size: var(--text-2xs);
}

.board-card-where {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* 원장만 아는 워커의 표. 이 창에 터미널이 없다는 사실을 **말로** 나르므로
 * 여기서 정하는 것은 그 말이 딸림말로 읽히게 하는 테두리뿐이다 — 색이 빠져도
 * 문장은 그대로 남는다. */
.board-card-seatless {
  flex: none;
  padding: 0 var(--space-1);
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-xs);
  white-space: nowrap;
}

/* 이 체크아웃이 올라 있는 리뷰 — Orca의 ReviewPill. 알약의 모양은 이 창이
 * 이미 쓰는 그 알약(`.wt-gh-pill`)이고, 여기서 정하는 것은 네 상태의 톤뿐이다:
 * 열린 것은 살아 있는 색, 병합된 것은 `.gl-item-state`가 고른 그 색(실측의
 * 보라는 이 창에 토큰이 없다), 닫힌 것은 멈춘 색. 초안은 톤이 없는 것이 톤이다
 * — 알약의 기본이 이미 muted다. */
.board-card-review {
  display: inline-flex;
  gap: var(--space-1);
  align-items: center;
}

.board-card-review .icon {
  flex: none;
  width: 11px;
  height: 11px;
}

.board-card-review-words {
  white-space: nowrap;
}

.board-card-review.is-open {
  color: var(--signal-ready);
  border-color: var(--signal-ready);
}

.board-card-review.is-merged {
  color: var(--signal-done);
  border-color: var(--signal-done);
}

.board-card-review.is-closed {
  color: var(--signal-halt);
  border-color: var(--signal-halt);
}

.board-card-when {
  margin-left: auto;
  flex: none;
  font-variant-numeric: tabular-nums;
}

/* 이 턴이 얼마나 오래 돌고 있는지 (1-t1153).
 *
 * 이 턴의 길이라는 다른 질문을 답하므로 잉크를 한 칸 올린다 — 딸림말들
 * 사이에서 눈이 그 낱말을 먼저 찾게. 두 테마 다 토큰이 답하므로 여기서 정할
 * 것은 어느 잉크인지 하나뿐이고, 색이 빠져도(고대비·색각) 낱말 자체가 이미
 * 「50분」과 「50분째」로 다르다 — 색은 강조지 문장이 아니다. */
.board-card-when.is-running {
  margin-left: 0;
  color: var(--ink-chalk);
}

/* ---- 그리다 멈춘 보드 (1-g78d) ---------------------------------------------
 *
 * Orca의 `recoverableError`. 세 그림이 서던 자리에 서므로 같은 칸(`grid-row: 3`)
 * 이고, 얼굴은 작업판의 빈 카드(`.task-empty`)와 같다 — 이것도 "여기에 있어야
 * 할 것이 지금 없다"는 한 장이고, 두 표면이 같은 사실을 다른 얼굴로 말할 이유가
 * 없다. 다른 것은 여기에 나가는 문이 하나 있다는 것뿐이다. */
.board-broken {
  display: grid;
  align-content: center;
  justify-items: center;
  gap: var(--space-3);
  min-height: 0;
  grid-row: 4;
  padding: var(--space-6) var(--space-5);
  text-align: center;
  color: var(--ink-mist);
  font-size: var(--text-sm);
}

.board-broken[hidden] {
  display: none;
}

.board-broken-title {
  margin: 0;
  color: var(--ink-chalk);
  font-family: var(--font-display);
  font-size: var(--text-md);
  font-weight: 600;
}

/* 한 문장이 화면 폭만큼 늘어나면 읽는 눈이 줄마다 처음으로 돌아가지 못한다 —
 * 카드 하나의 폭이 이 사본의 읽는 폭이다. */
.board-broken-copy {
  max-width: 42ch;
  margin: 0;
}

/* ---- the pop-out surface --------------------------------------------------
 *
 * The SAME document, in a second OS window, with everything that is not the
 * board folded away. Nothing is drawn twice: `index.html?surface=popout` is
 * this file's own markup and `ui/shell.js` boots into `bootPopout`, so a card
 * here and a card in the main window are the one renderer.
 *
 * Folded rather than removed, because the fold is what makes that possible —
 * a second document with only the board in it would be a second board. */
:root[data-surface="popout"] body {
  /* The titlebar and the status bar are the main window's chrome; this window
   * wears the operating system's own frame instead (there is no close button
   * inside it, and the OS frame is the only way out). */
  grid-template-rows: minmax(0, 1fr);
}

:root[data-surface="popout"] .titlebar,
:root[data-surface="popout"] .statusbar,
:root[data-surface="popout"] .threads,
:root[data-surface="popout"] .files,
:root[data-surface="popout"] .panel-grip,
/* The empty stage's invitation to open a terminal is the main window's — this
 * window's stage is never empty and has no `⌘T`. */
:root[data-surface="popout"] .placeholder,
/* Already this window — a button that opens it would open nothing. */
:root[data-surface="popout"] .board-popout {
  display: none;
}

:root[data-surface="popout"] .body {
  grid-template-columns: minmax(0, 1fr);
}

/* The stage holds one surface here and it fills the window. */
:root[data-surface="popout"] .stage {
  padding: 0;
}

/* The count of stuck agents, on the closed door. */
.nav-badge {
  margin-left: auto;
  padding-inline: 5px;
  border-radius: var(--radius-pill);
  background: var(--signal-wait);
  color: var(--surface-abyss);
  font-size: var(--text-3xs);
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  line-height: 15px;
}

/* One rule, not per-effect opt-outs: the NEXT animation added to this sheet
 * must arrive already muted. */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation: none !important;
    transition: none !important;
  }
}

/* ---- the session vault ----
 *
 * Orca's `AiVaultPanel`. Its own numbers where they exist: the group header is
 * 32px tall and a session row is 98px (`VAULT_GROUP_HEADER_ROW_HEIGHT`,
 * `VAULT_SESSION_ROW_HEIGHT`, AiVaultPanel-_kbRUyaA.js:3186-3187), and a header's
 * word is 11px semibold uppercase on 0.05em (:2153).
 *
 * Orca hangs this off the right sidebar and virtualizes it; here it is a surface
 * with a tab, and the list is bounded in Rust instead — a scan stops at two
 * hundred sessions, so there is never a list long enough to need a windowing
 * layer in the webview. */

#vault-view,
.vault-view {
  display: flex;
  flex-direction: column;
}

.vault-head {
  display: flex;
  flex: none;
  flex-wrap: wrap;
  gap: var(--space-2);
  align-items: center;
  padding: var(--space-2) var(--space-3);
  border-bottom: 1px solid var(--edge-rule);
}

.vault-search {
  display: flex;
  flex: 1;
  gap: var(--space-2);
  align-items: center;
  min-width: 180px;
  padding-inline: var(--space-2);
  border-radius: var(--radius-sm);
  background: var(--surface-raised);
}

.vault-search .icon {
  flex: none;
  width: 14px;
  height: 14px;
  color: var(--ink-glyph);
}

.vault-query {
  flex: 1;
  min-width: 0;
  height: 28px;
  border: 0;
  background: none;
  color: var(--ink-chalk);
  font: inherit;
  font-size: var(--text-xs);
  outline: none;
}

.vault-count {
  flex: none;
  color: var(--ink-glyph);
  font-size: var(--text-xs);
  font-variant-numeric: tabular-nums;
}

.vault-toggle {
  display: flex;
  flex: none;
  gap: var(--space-1);
  align-items: center;
  color: var(--ink-glyph);
  font-size: var(--text-xs);
  cursor: pointer;
}

.vault-toggle select {
  height: 24px;
  padding-inline: var(--space-1);
  border: 1px solid var(--edge-rule);
  border-radius: var(--radius-sm);
  background-color: var(--surface-raised);
  color: var(--ink-chalk);
  font: inherit;
  font-size: var(--text-xs);
}

/* 한 판의 머리에 서는 아이콘 단추. 판의 「다시 훑기」와 「에이전트 고르기」,
 * 보드의 설정 톱니, 그리고 낱말 대신 글리프만 선 단추 전부(`.icon-btn` — 사용량
 * 분석의 필터·공유·다시 확인, 에뮬레이터 도구 단)가 같은 자리의 같은 물건이므로
 * 한 규칙을 쓴다 — 두 번째 사본은 곧 두 개의 크기다.
 *
 * `.icon-btn`은 마크업이 먼저 있고 규칙이 없던 이름이다: 이 창의 어떤
 * 스타일시트도 선언하지 않아, 그것만 입은 단추 일곱 개가 OS 기본 단추로 서 있었다
 * (옆의 트리거는 40, 그것들은 20). 낱말을 입은 단추보다 작은 것은 결함이 아니다 —
 * 원본도 그렇고, 줄이 `align-items: center`라 가운데 선다. 결함은 얼굴이 없던
 * 것이다. */
.icon-btn,
.vault-filters,
.vault-refresh,
.board-settings {
  display: flex;
  flex: none;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  padding: 0;
  border: 1px solid var(--edge-rule);
  border-radius: var(--radius-sm);
  background: var(--surface-raised);
  color: var(--ink-glyph);
  cursor: pointer;
  /* 테두리도 함께 건넌다 — 셋 중 하나가 상태를 가지면서 테두리를 바꾸고,
   * 바탕은 흐르는데 테두리만 끊기면 그 하나가 덜 만든 것으로 보인다. */
  transition:
    background var(--motion-fast),
    border-color var(--motion-fast),
    color var(--motion-fast);
}

.icon-btn:hover,
.vault-filters:hover,
.vault-refresh:hover,
.board-settings:hover {
  background: var(--row-hover);
  color: var(--ink-chalk);
}

.icon-btn .icon,
.vault-filters .icon,
.vault-refresh .icon,
.board-settings .icon {
  width: 14px;
  height: 14px;
}

/* 셋 중 이 하나만 상태를 갖는다. 좁혀 놓은 것은 팝오버를 열지 않고도 보여야
 * 하고(GitHub 필터 단추가 같은 자리에서 같은 규칙을 쓴다), 나머지 둘은 누를
 * 때마다 같은 일을 하므로 상태가 없다. 뒤집기는 `.task-chip.is-active`의 것
 * 그대로다 — 한 창에 두 벌의 「켜짐」이 생기지 않는다. hover 뒤에 서는 것이
 * 규칙이다: 이미 최대 대비로 선 단추는 손이 얹혀도 물러서지 않는다. */
.vault-filters.is-active {
  border-color: var(--ink-chalk);
  background: var(--ink-chalk);
  color: var(--surface-abyss);
}

/* What the scan could not do. A rule above it rather than a colour, because this
 * is a fact about completeness and not a warning about a failure. */
.vault-note {
  flex: none;
  margin: 0;
  padding: var(--space-1) var(--space-3);
  border-bottom: 1px solid var(--edge-rule);
  color: var(--ink-glyph);
  font-size: var(--text-xs);
}

.vault-list {
  flex: 1;
  min-height: 0;
  padding: var(--space-2) var(--space-3) var(--space-4);
  overflow-y: auto;
}

.vault-group + .vault-group {
  margin-top: var(--space-3);
}

/* Sticky, because the header names the directory every row under it belongs to
 * and a list scrolled past its header is a list of paths with no context. */
.vault-group-head {
  display: flex;
  gap: var(--space-2);
  align-items: center;
  position: sticky;
  top: calc(var(--space-2) * -1);
  z-index: 1;
  height: 32px;
  background: var(--surface-deck);
}

.vault-group-label {
  min-width: 0;
  overflow: hidden;
  color: var(--ink-glyph);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-overflow: ellipsis;
  text-transform: uppercase;
  white-space: nowrap;
}

.vault-group-count {
  flex: none;
  margin-left: auto;
  padding-inline: 6px;
  border-radius: 999px;
  background: var(--surface-raised);
  color: var(--ink-glyph);
  font-size: 10px;
  font-variant-numeric: tabular-nums;
}

.vault-row {
  display: flex;
  gap: var(--space-2);
  align-items: flex-start;
  padding: var(--space-2);
  border: 1px solid var(--edge-rule);
  border-radius: var(--radius-sm);
  background: var(--surface-deck);
  transition: background var(--motion-fast), border-color var(--motion-fast);
}

.vault-row + .vault-row {
  margin-top: var(--space-1);
}

.vault-row:hover {
  border-color: var(--edge-mark);
  background: var(--row-hover);
}

.vault-row-body {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.vault-row-title {
  overflow: hidden;
  color: var(--ink-chalk);
  font-size: var(--text-sm);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.vault-row-meta {
  color: var(--ink-glyph);
  font-size: var(--text-xs);
}

/* The path is the longest thing on the row and the least urgent, so it wraps at
 * the front — the tail of a path is the part that identifies it. */
.vault-row-path {
  overflow: hidden;
  color: var(--ink-label);
  font-size: var(--text-xs);
  direction: rtl;
  text-align: left;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.vault-row-actions {
  display: flex;
  flex: none;
  gap: var(--space-1);
  align-items: center;
}

.vault-act {
  padding: 3px var(--space-2);
  border: 1px solid var(--edge-rule);
  border-radius: var(--radius-sm);
  background: var(--surface-raised);
  color: var(--ink-glyph);
  font: inherit;
  font-size: var(--text-xs);
  white-space: nowrap;
  cursor: pointer;
  transition: background var(--motion-fast), color var(--motion-fast);
}

.vault-act:hover {
  background: var(--row-hover);
  color: var(--ink-chalk);
}

/* ---- the docked session history (right column, 1-g77) ----
 *
 * Orca's AiVaultPanel as the right column wears it. The measured scale:
 * header px-2.5 py-2 (10px/8px), title text-xs semibold, subtitle 11px muted,
 * scope row h-7, search h-8, card px-3 py-2 with a border-b seam, title
 * 13px/20px medium, preview 12px/16px two-line clamp, meta 11px muted with an
 * icon at size-4 holding a 14px mark, group header h-8 on the accent wash. */
.vdock-head {
  flex: none;
  padding: var(--space-2) 10px;
  border-bottom: var(--rule-width) solid var(--edge-rule);
}

.vdock-title-row {
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

.vdock-titles {
  display: flex;
  flex-direction: column;
  min-width: 0;
  flex: 1;
}

.vdock-title {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--text-xs);
  font-weight: 600;
  color: var(--ink-chalk);
}

.vdock-sub {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--text-2xs);
  color: var(--ink-mist);
}

.vdock-refresh,
.vdock-tool {
  flex: none;
  display: grid;
  place-items: center;
  width: 24px;
  height: 24px;
  border: 0;
  border-radius: var(--radius-sm);
  background: none;
  color: var(--ink-mist);
  cursor: pointer;
  transition:
    background-color var(--motion-fast) var(--ease-standard),
    color var(--motion-fast) var(--ease-standard);
}

.vdock-refresh:hover,
.vdock-tool:hover {
  background: var(--row-hover);
  color: var(--ink-chalk);
}

/* 호스트 칩 — 아이콘과 호스트 이름이 함께 서는 넓은 도구. */
.vdock-host {
  width: auto;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 0 var(--space-1);
  font-size: var(--text-2xs);
  white-space: nowrap;
}

/* Orca's three-way is a bordered ToggleGroup on a faint accent wash; the
 * chosen third stands up with its own border and a foreground tint
 * (VAULT_SCOPE_TOGGLE_ITEM_CLASS: aria-[checked=true]:border-foreground/20
 * aria-[checked=true]:bg-foreground/10). */
.vdock-scope {
  display: flex;
  margin-top: var(--space-2);
  height: 28px;
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-sm);
  background: color-mix(in srgb, var(--surface-raised) 35%, transparent);
}

.vdock-scope-item {
  flex: 1;
  min-width: 0;
  border: var(--rule-width) solid transparent;
  border-radius: var(--radius-sm);
  background: none;
  font-size: var(--text-2xs);
  font-weight: 500;
  color: var(--ink-chalk);
  cursor: pointer;
}

.vdock-scope-item:hover {
  background: var(--row-hover);
}

.vdock-scope-item.is-on {
  border-color: color-mix(in srgb, var(--ink-chalk) 20%, transparent);
  background: color-mix(in srgb, var(--ink-chalk) 10%, transparent);
}

.vdock-scope-item:disabled {
  opacity: 0.5;
  cursor: default;
}

.vdock-search {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: var(--space-2);
  height: 32px;
  padding-inline: var(--space-2);
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-sm);
  background: var(--surface-raised);
}

.vdock-search .icon {
  flex: none;
  width: 14px;
  height: 14px;
  color: var(--ink-glyph);
}

.vdock-query {
  flex: 1;
  min-width: 0;
  border: 0;
  background: none;
  color: var(--ink-chalk);
  font: inherit;
  font-size: var(--text-xs);
  outline: none;
}

.vdock-note {
  margin: 0;
  padding: 6px var(--space-3);
  border-bottom: var(--rule-width) solid var(--edge-rule);
  font-size: var(--text-2xs);
  color: var(--ink-mist);
}

.vdock-list {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
}

.vdock-group-head {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  width: 100%;
  height: 32px;
  padding-inline: var(--space-3);
  border: 0;
  border-block: var(--rule-width) solid var(--edge-rule);
  background: color-mix(in srgb, var(--surface-raised) 60%, transparent);
  font-size: var(--text-xs);
  font-weight: 600;
  color: var(--ink-chalk);
  text-align: left;
  cursor: pointer;
}

.vdock-group-head:hover {
  background: var(--row-hover);
}

.vdock-group-twist {
  display: inline-flex;
  flex: none;
}

.vdock-group-label {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.vdock-group-count {
  flex: none;
  padding: 2px var(--space-2);
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-sm);
  /* Orca's pill stands on bg-background — the page's own ground — so it
   * reads as a window cut into the header's wash. */
  background: var(--surface-abyss);
  font-size: var(--text-2xs);
  font-variant-numeric: tabular-nums;
  line-height: 1;
  color: var(--ink-chalk);
}

.vdock-card {
  position: relative;
  padding: var(--space-2) var(--space-3);
  border-bottom: var(--rule-width) solid var(--edge-rule);
}

.vdock-card:hover {
  background: var(--row-hover);
}

.vdock-card-top {
  display: flex;
  align-items: center;
  gap: var(--space-1);
}

.vdock-card-title {
  flex: 1;
  min-width: 0;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 1;
  overflow: hidden;
  font-size: 13px;
  font-weight: 500;
  line-height: 20px;
  color: var(--ink-chalk);
}

/* 제목 줄의 늘 보이는 두 손 — 접힘 화살표(장식이다: 카드 몸이 문)와 ⋯. */
.vdock-twist {
  display: grid;
  place-items: center;
  flex: none;
  width: 16px;
  height: 16px;
  color: var(--ink-mist);
}

.vdock-twist .icon {
  width: 12px;
  height: 12px;
}

.vdock-more {
  flex: none;
  background: none;
}

.vdock-card-preview {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  overflow: hidden;
  margin: 2px 0 0;
  font-size: var(--text-xs);
  line-height: 16px;
  color: var(--ink-mist);
}

.vdock-role {
  font-weight: 500;
  color: color-mix(in srgb, var(--ink-chalk) 80%, transparent);
}

.vdock-card-meta {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: var(--space-1);
  font-size: var(--text-2xs);
  line-height: 16px;
  color: var(--ink-mist);
}

.vdock-agent-face {
  display: grid;
  place-items: center;
  flex: none;
  width: 16px;
  height: 16px;
}

.vdock-agent-face .agent-ico {
  width: 14px;
  height: 14px;
  font-size: 8px;
}

.vdock-meta-words {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* The three hands, on hover and while focused — the same rule as `.scm-act`:
 * a control that only exists under a pointer does not exist for everybody. */
.vdock-acts {
  position: absolute;
  top: var(--space-1);
  right: var(--space-2);
  display: flex;
  gap: 2px;
  opacity: 0;
}

.vdock-card:hover .vdock-acts,
.vdock-acts:focus-within {
  opacity: 1;
}

.vdock-act {
  display: grid;
  place-items: center;
  width: 22px;
  height: 22px;
  border: 0;
  border-radius: var(--radius-sm);
  background: var(--surface-deck);
  color: var(--ink-mist);
  cursor: pointer;
}

.vdock-act .icon {
  width: 12px;
  height: 12px;
}

.vdock-act:hover {
  background: var(--row-hover);
  color: var(--ink-chalk);
}

.vdock-empty {
  margin: 0;
  padding: var(--space-3);
  text-align: center;
  font-size: var(--text-xs);
  color: var(--ink-mist);
}

/* Orca's own clear hand in the search box (ghost icon-xs ✕) — the native
 * search-cancel is styled away window-wide. */
.vdock-clear {
  display: grid;
  place-items: center;
  flex: none;
  width: 20px;
  height: 20px;
  border: 0;
  border-radius: var(--radius-sm);
  background: none;
  color: var(--ink-mist);
  cursor: pointer;
}

.vdock-clear .icon {
  width: 12px;
  height: 12px;
}

.vdock-clear:hover {
  color: var(--ink-chalk);
}

/* The inline details — Orca's expanded row: `mt-2 rounded-lg border
 * border-sidebar-border/80 bg-background/50`, an action strip on a rule
 * (`border-b bg-sidebar-accent/15 px-3 py-2`, h-7 11px buttons), then a
 * `space-y-3 p-3` receipt body. */
.vdock-detail {
  margin-top: var(--space-2);
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius);
  background: var(--surface-abyss);
  overflow: hidden;
  cursor: default;
}

.vdock-detail-acts {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  padding: var(--space-2) var(--space-3);
  border-bottom: var(--rule-width) solid var(--edge-rule);
  background: var(--surface-deck);
}

.vdock-detail-act {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  height: 28px;
  padding: 0 10px;
  border: 0;
  border-radius: var(--radius-sm);
  background: var(--surface-well);
  font: inherit;
  font-size: 11px;
  color: var(--ink-chalk);
  cursor: pointer;
}

.vdock-detail-act .icon {
  width: 14px;
  height: 14px;
}

.vdock-detail-act:hover {
  background: var(--row-hover);
}

.vdock-detail-act--primary {
  background: var(--ink-chalk);
  color: var(--surface-abyss);
}

.vdock-detail-act--primary:hover {
  background: color-mix(in srgb, var(--ink-chalk) 88%, transparent);
}

.vdock-detail-body {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  padding: var(--space-3);
}

/* The receipt heads: 11px semibold uppercase, letter-spaced, muted. */
.vdock-receipt {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.vdock-receipt-label {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--ink-mist);
}

.vdock-receipt-line {
  margin: 0;
  font-size: var(--text-2xs);
  font-family: var(--font-mono);
  color: var(--ink-mist);
  overflow-wrap: anywhere;
}

/* One turn: a bordered card, the speaker in 10px uppercase, the words
 * clamped to four lines — user and agent wear different fills, Orca's
 * `bg-foreground/[0.04]` against `bg-sidebar-accent/25`. */
.vdock-turn {
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-sm);
  padding: var(--space-2) 10px;
}

.vdock-turn[data-role="user"] {
  background: color-mix(in srgb, var(--ink-chalk) 4%, transparent);
}

.vdock-turn[data-role="assistant"] {
  background: var(--surface-deck);
}

.vdock-turn-role {
  margin-bottom: 4px;
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--ink-mist);
}

.vdock-turn-text {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 4;
  overflow: hidden;
  margin: 0;
  font-size: var(--text-xs);
  line-height: 1.35;
  color: var(--ink-chalk);
  overflow-wrap: anywhere;
  user-select: text;
}

.vdock-turn-none {
  margin: 0;
  font-size: var(--text-2xs);
  color: var(--ink-mist);
}

/* The section keeps its own scroll out of the way so the list scrolls under
 * a standing header — only `overflow`, never `display`, or the id would
 * outrank `.activity-item[hidden]` and the panel could not be put away. */
#activity-vault {
  overflow: hidden;
}

/* ---- 첫 실행 마법사 (Orca의 OnboardingFlow, 1-ea) ----
 *
 * 전체화면에 가까운 한 장. Orca의 상자는 `h-[calc(100vh-2rem)] max-h-[960px]
 * w-[calc(100vw-2rem)] max-w-[1100px]`이라 창을 거의 다 덮되 가장자리 한 겹은
 * 남긴다 — 그 한 겹이 "이것은 앱 안의 화면"임을 말한다. 같은 비례를 여기
 * 토큰으로 옮겼다. */
.scrim--onboard {
  z-index: 32;
  padding: var(--space-4);
}

.onboard {
  display: flex;
  flex-direction: column;
  gap: var(--space-5);
  width: min(1100px, 100%);
  height: min(960px, 100%);
  padding: var(--space-6);
  border: 1px solid var(--edge-rule);
  border-radius: var(--radius);
  background: var(--surface-deck);
  box-shadow: var(--shadow-float);
  overflow: hidden auto;
}

.onb-head {
  display: flex;
  flex: none;
  gap: var(--space-4);
  align-items: center;
}

.onb-brand {
  font-size: var(--text-sm);
  font-weight: 600;
  letter-spacing: var(--tracking-label);
  color: var(--ink-chalk);
}

/* 지나온 단계·지금 단계·아직인 단계. 지금 것만 길다 — Orca의 `w-10` 대 `w-6`
 * 이고, 색이 아니라 길이로 갈리므로 대비 설정과 무관하게 읽힌다. */
.onb-progress {
  display: flex;
  gap: var(--space-1);
  align-items: center;
  margin-right: auto;
}

.onb-dot {
  width: 24px;
  height: 4px;
  padding: 0;
  border: 0;
  border-radius: 999px;
  /* 칠이지 테두리가 아니다. `--edge-rule`은 7% 흰색이라 도형으로 칠하면
   * 도형이 사라진다 — 이 창이 이미 여섯 번 겪은 실수다. */
  background: var(--edge-mark);
  cursor: pointer;
}

.onb-dot[data-state="done"] {
  background: var(--ink-mist);
}

.onb-dot[data-state="here"] {
  width: 40px;
  background: var(--ink-chalk);
}

.onb-dot:disabled {
  cursor: default;
}

.onb-count {
  flex: none;
  font-size: var(--text-2xs);
  color: var(--ink-mist);
  font-variant-numeric: tabular-nums;
}

.onb-lede {
  flex: none;
}

.onb-eyebrow {
  margin: 0 0 var(--space-2);
  font-size: var(--text-2xs);
  letter-spacing: var(--tracking-label);
  text-transform: uppercase;
  color: var(--ink-mist);
}

.onb-eyebrow[hidden] {
  display: none;
}

.onb-title {
  margin: 0;
  font-size: var(--text-xl);
  font-weight: 600;
  line-height: var(--leading-tight);
  color: var(--ink-chalk);
}

.onb-subtitle {
  margin: var(--space-2) 0 0;
  font-size: var(--text-sm);
  line-height: var(--leading-body);
  color: var(--ink-mist);
}

.onb-body {
  flex: 1 1 auto;
  min-height: 0;
  overflow: auto;
}

.onb-section {
  margin: 0 0 var(--space-3);
  font-size: var(--text-2xs);
  letter-spacing: var(--tracking-label);
  text-transform: uppercase;
  color: var(--ink-mist);
}

.onb-warn {
  margin: 0 0 var(--space-3);
  padding: var(--space-2) var(--space-3);
  border: 1px solid var(--edge-rule);
  border-radius: var(--radius-sm);
  font-size: var(--text-xs);
  line-height: var(--leading-body);
  color: var(--ink-glyph);
}

.onb-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: var(--space-3);
}

.onb-grid--theme {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.onb-card {
  display: flex;
  gap: var(--space-2);
  align-items: center;
  min-height: 56px;
  padding: var(--space-3);
  border: 1px solid var(--edge-rule);
  border-radius: var(--radius-sm);
  background: var(--surface-raised);
  color: var(--ink-chalk);
  font: inherit;
  font-size: var(--text-xs);
  text-align: left;
  cursor: pointer;
  transition: background var(--motion-fast), border-color var(--motion-fast);
}

.onb-card:hover {
  background: var(--row-hover);
}

.onb-card[aria-pressed="true"] {
  border-color: var(--ink-chalk);
  background: var(--row-hover);
}

.onb-card-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.onb-bullets {
  margin: 0 0 var(--space-4);
  padding-left: var(--space-4);
  font-size: var(--text-xs);
  line-height: var(--leading-body);
  color: var(--ink-glyph);
}

.onb-row {
  display: flex;
  gap: var(--space-2);
  align-items: center;
  flex-wrap: wrap;
}

.onb-badge {
  padding: 2px var(--space-2);
  border: 1px solid var(--edge-rule);
  border-radius: var(--radius-edge);
  font-size: var(--text-3xs);
  color: var(--ink-mist);
}

.onb-badge[data-standing="connected"] {
  color: var(--ink-chalk);
  border-color: var(--edge-mark);
}

.onb-foot {
  display: flex;
  flex: none;
  gap: var(--space-3);
  align-items: center;
  justify-content: space-between;
}

.onb-foot-right {
  display: flex;
  gap: var(--space-2);
  align-items: center;
  margin-left: auto;
}

/* ---- 프로젝트가 없을 때의 첫 화면 (Orca의 Landing) ----
 *
 * 빈 무대의 문단 자리에 앉으므로 그 규칙 하나를 되돌려야 한다: `.placeholder`는
 * 클릭을 삼키지 않으려고 `pointer-events: none`인데, 여기 두 버튼은 자기 클릭을
 * 되찾아야 한다. */
.placeholder .landing-mark,
.placeholder .landing-wordmark,
.placeholder .landing-lede,
.placeholder .landing-doors {
  display: block;
}

.landing-mark {
  width: 64px;
  height: 64px;
  margin: 0 auto var(--space-4);
  border: 1px solid var(--edge-rule);
  border-radius: var(--radius);
  background: var(--surface-raised);
  color: var(--ink-chalk);
  font-size: var(--text-xl);
  font-weight: 600;
  line-height: 64px;
  text-align: center;
}

.landing-wordmark {
  font-size: var(--text-xl);
  font-weight: 600;
  letter-spacing: var(--tracking-label);
  color: var(--ink-chalk);
}

.landing-lede {
  margin-top: var(--space-2);
  font-size: var(--text-sm);
  color: var(--ink-mist);
}

.landing-doors {
  display: flex;
  gap: var(--space-2);
  justify-content: center;
  margin-top: var(--space-4);
  pointer-events: auto;
}

/* ---- 시작 체크리스트 (Orca의 Setup Guide, 1-eb) ----
 *
 * 사이드바의 한 줄은 `.wsclean-entry`와 같은 몸을 쓴다 — 둘 다 "있을 때만 서는
 * 한 줄"이고, 둘을 다르게 그리면 사이드바 바닥이 서로 다른 두 관용구를 갖게
 * 된다. 다른 것은 앞의 글리프뿐: 저쪽은 아이콘, 이쪽은 진행 링이다. */
.guide-entry {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  margin: 0 var(--nav-gutter) var(--space-2);
  padding: var(--space-2) var(--space-3);
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-sm);
  background: none;
  color: var(--ink-mist);
  font-family: inherit;
  font-size: var(--text-xs);
  text-align: left;
  cursor: pointer;
  transition:
    background-color var(--motion-fast) var(--ease-standard),
    color var(--motion-fast) var(--ease-standard);
}

.guide-entry:hover {
  background: var(--row-hover);
  color: var(--ink-chalk);
}

/* 몇 칸이 끝났나를 한 눈에. `--guide-done`은 0~1이고 창이 매 그리기마다
 * 다시 쓴다 — 숫자를 읽지 않아도 남은 양이 보이는 것이 이 글리프의 전부다. */
.guide-ring {
  flex: none;
  width: var(--icon-size);
  height: var(--icon-size);
  border-radius: 50%;
  background: conic-gradient(
    var(--signal-ready) calc(var(--guide-done, 0) * 360deg),
    var(--edge-mark) 0
  );
  mask: radial-gradient(circle, transparent 52%, #000 54%);
}

/* 목록 다이얼로그. 파인더보다 넓다: 한 줄에 표시·이름·이유가 함께 서야 하고,
 * 팔레트 폭에서는 이유가 이름 아래로 접혀 목록이 두 배 길어진다. */
.guide,
.wall {
  width: min(720px, calc(100% - var(--space-6)));
  display: flex;
  flex-direction: column;
}

.guide-lede {
  margin: 0;
  padding: var(--space-2) var(--space-4) 0;
  font-size: var(--text-xs);
  color: var(--ink-mist);
}

.guide-body {
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
  padding: var(--space-4);
  overflow: hidden auto;
}

.guide-section-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin: 0 0 var(--space-2);
  font-family: var(--font-display);
  font-size: var(--text-2xs);
  font-weight: 600;
  letter-spacing: var(--tracking-label);
  color: var(--ink-mist);
}

.guide-step {
  display: flex;
  gap: var(--space-3);
  align-items: flex-start;
  padding: var(--space-2) var(--space-3);
  border-radius: var(--radius-sm);
  transition: background-color var(--motion-fast) var(--ease-standard);
}

.guide-step:hover {
  background: var(--row-hover);
}

/* 끝난 칸과 남은 칸. 색 하나로만 가르지 않는다 — 채워진 원과 빈 원은 색을 못
 * 가리는 사람에게도 다르게 보인다. */
.guide-mark {
  flex: none;
  width: var(--icon-size-sm);
  height: var(--icon-size-sm);
  margin-top: 3px;
  border: var(--rule-width) solid var(--edge-mark);
  border-radius: 50%;
}

.guide-step[data-done="true"] .guide-mark {
  border-color: var(--signal-ready);
  background: var(--signal-ready);
}

.guide-step-name {
  display: block;
  font-size: var(--text-sm);
  color: var(--ink-chalk);
}

.guide-step[data-done="true"] .guide-step-name {
  color: var(--ink-mist);
}

.guide-step-why {
  display: block;
  margin-top: var(--space-1);
  font-size: var(--text-xs);
  line-height: var(--leading-body);
  color: var(--ink-mist);
}

.guide-foot,
.wall-foot {
  display: flex;
  gap: var(--space-3);
  align-items: center;
  justify-content: space-between;
  padding: var(--space-3) var(--space-4);
  border-top: var(--rule-width) solid var(--edge-rule);
}

/* ---- 기능 투어 (Orca의 FeatureWall, 1-eb) ---- */

.wall-body {
  display: flex;
  gap: var(--space-4);
  padding: var(--space-4);
  overflow: hidden auto;
}

.wall-rail {
  display: flex;
  flex: none;
  flex-direction: column;
  gap: var(--space-1);
  width: 160px;
}

.wall-rail-item {
  padding: var(--space-2) var(--space-3);
  border: 0;
  border-radius: var(--radius-sm);
  background: none;
  color: var(--ink-mist);
  font-family: inherit;
  font-size: var(--text-xs);
  text-align: left;
  cursor: pointer;
  transition:
    background-color var(--motion-fast) var(--ease-standard),
    color var(--motion-fast) var(--ease-standard);
}

.wall-rail-item:hover {
  background: var(--row-hover);
  color: var(--ink-chalk);
}

.wall-rail-item[aria-current="page"] {
  background: var(--row-selected);
  color: var(--ink-chalk);
}

/* 읽은 갈래에 붙는 점. 목록을 다시 열었을 때 어디까지 갔는지가 이것 하나로
 * 남는다. */
.wall-rail-item[data-seen="true"]::after {
  content: "";
  display: inline-block;
  width: var(--dot-size);
  height: var(--dot-size);
  margin-left: var(--space-2);
  border-radius: 50%;
  background: var(--signal-ready);
  vertical-align: middle;
}

.wall-step {
  flex: 1;
  min-width: 0;
}

.wall-step-title {
  margin: 0;
  font-size: var(--text-md);
  font-weight: 600;
  color: var(--ink-chalk);
}

.wall-step-meta {
  margin: var(--space-1) 0 0;
  font-size: var(--text-2xs);
  letter-spacing: var(--tracking-label);
  color: var(--ink-mist);
}

.wall-step-lede {
  margin: var(--space-3) 0 0;
  font-size: var(--text-sm);
  line-height: var(--leading-body);
  color: var(--ink-chalk);
}

.wall-points {
  margin: var(--space-3) 0 0;
  padding-left: var(--space-4);
  font-size: var(--text-xs);
  line-height: var(--leading-body);
  color: var(--ink-mist);
}

.wall-note {
  margin: 0;
  font-size: var(--text-2xs);
  color: var(--ink-mist);
}

/* ---- 일회성 팁 (Orca의 FeatureTipsModal, 1-eb) ----
 *
 * 권한 다이얼로그의 몸을 그대로 쓴다: 한 문장과 두 버튼이라는 모양이 같고, 두
 * 번째 사본을 만들면 그중 하나는 반드시 다른 여백을 갖게 된다. */
.tip .perm-agent {
  text-transform: uppercase;
}

/* ---- 코치마크 투어 (Orca의 ContextualTour, 1-eb) ----
 *
 * 백드롭이 없다. 뿌리는 `pointer-events: none`이라 아래 화면이 그대로 눌리고,
 * 말풍선만 자기 클릭을 되찾는다 — "이 버튼을 눌러 보세요" 류의 스텝은 그래야만
 * 성립한다. */
.tour {
  position: fixed;
  inset: 0;
  z-index: 29;
  pointer-events: none;
}

.tour[hidden] {
  display: none;
}

/* 타깃 둘레의 고리. 스포트라이트 컷아웃이 아니다 — 아래를 어둡게 덮으면 조작
 * 가능하다는 사실이 화면에서 사라진다. */
.tour-ring {
  position: absolute;
  border: var(--accent-rule) solid var(--ai-accent);
  border-radius: var(--radius-sm);
  animation: tour-pulse 1800ms var(--ease-standard) infinite;
}

@keyframes tour-pulse {
  0% {
    opacity: 0.72;
  }

  100% {
    opacity: 0.18;
  }
}

.tour-panel {
  position: absolute;
  width: min(20rem, calc(100vw - var(--space-6)));
  padding: var(--space-4);
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius);
  background: var(--surface-deck);
  box-shadow: var(--shadow-float);
  pointer-events: auto;
  animation: tour-enter var(--motion-fast) var(--ease-standard);
}

@keyframes tour-enter {
  from {
    opacity: 0;
    transform: scale(var(--enter-scale));
  }

  to {
    opacity: 1;
    transform: scale(1);
  }
}

/* 화살표. 회전한 정사각형의 두 변만 보이게 잘라 쓴다 — 삼각형 SVG를 배치마다
 * 네 벌 두는 것보다 한 벌이 낫다. */
.tour-arrow {
  position: absolute;
  width: 10px;
  height: 10px;
  border: var(--rule-width) solid var(--edge-rule);
  background: var(--surface-deck);
  transform: rotate(45deg);
  clip-path: polygon(100% 0, 100% 100%, 0 100%);
}

.tour-head {
  display: flex;
  gap: var(--space-2);
  align-items: flex-start;
  justify-content: space-between;
}

.tour-title {
  margin: 0;
  font-size: var(--text-sm);
  font-weight: 600;
  color: var(--ink-chalk);
}

.tour-x {
  flex: none;
  padding: 0;
  border: 0;
  background: none;
  color: var(--ink-mist);
  cursor: pointer;
  transition: color var(--motion-fast) var(--ease-standard);
}

.tour-x:hover {
  color: var(--ink-chalk);
}

.tour-body {
  margin: var(--space-2) 0 0;
  font-size: var(--text-xs);
  line-height: var(--leading-body);
  color: var(--ink-mist);
}

.tour-foot {
  display: flex;
  gap: var(--space-3);
  align-items: center;
  justify-content: space-between;
  margin-top: var(--space-4);
}

.tour-count {
  font-size: var(--text-2xs);
  font-variant-numeric: tabular-nums;
  color: var(--ink-mist);
}

.tour-doors {
  display: flex;
  gap: var(--space-2);
  align-items: center;
}

/* ---- 이 창이 만들지 않은 워크트리 ----
 *
 * 저장소마다 하나씩 있는 스위치의 세 겉모습: 다이얼로그 안의 카드 한 장, 그리고
 * 사이드바에 서는 인라인 카드 두 장(최초 1회 / 인박스). 셋이 한 벌의 규칙을
 * 공유하므로 한자리에 둔다. */

/* 다이얼로그는 카드 한 장이 전부이므로 제목 아래 여백을 줄인다. */
.ext .ext-repo {
  margin-bottom: var(--space-3);
}

/* 아이콘 · 말 · 버튼 한 줄. Orca의 것도 `rounded-lg border bg-muted/30 p-3`
   한 장이다. */
.ext-card {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  padding: var(--space-3);
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-sm);
  background: var(--row-hover);
}

.ext-eye {
  flex: none;
  width: var(--icon-size);
  height: var(--icon-size);
  color: var(--ink-mist);
}

.ext-said {
  display: grid;
  gap: 2px;
  min-width: 0;
  flex: 1;
}

.ext-state {
  font-size: var(--text-xs);
  font-weight: 600;
  color: var(--ink-chalk);
}

.ext-count {
  font-size: var(--text-2xs);
  font-variant-numeric: tabular-nums;
  color: var(--ink-mist);
}

.ext-go {
  flex: none;
}

/* 되돌리는 길을 이름으로 가리키는 줄. 문장 안의 버튼이므로 링크처럼 앉는다. */
.ext-back {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  align-items: baseline;
}

.ext-link {
  padding: 0;
  border: 0;
  background: none;
  color: var(--ink-chalk);
  font: inherit;
  text-decoration: underline;
  cursor: pointer;
}

/* 사이드바의 인라인 카드. 워크스페이스 행이 아니라 물음이므로 목록의 리듬을
   따르지 않고 자기 테두리를 갖는다 — 행처럼 생긴 물음은 눌러야 하는 것으로
   보이지 않는다. */
.ext-line {
  display: grid;
  gap: var(--space-2);
  margin: 0 var(--nav-gutter) var(--space-2);
  padding: var(--space-2) var(--space-3);
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-sm);
  color: var(--ink-mist);
  font-size: var(--text-xs);
}

.ext-line-mark {
  display: flex;
  align-items: center;
  color: var(--ink-mist);
}

.ext-line-mark .icon {
  width: var(--icon-size-sm);
  height: var(--icon-size-sm);
}

.ext-line-said {
  color: var(--ink-chalk);
  font-weight: 600;
}

.ext-line-why {
  font-size: var(--text-2xs);
}

.ext-line-rows {
  display: grid;
  gap: 2px;
}

.ext-line-row {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  min-width: 0;
}

/* 경로의 마지막 조각. 잘릴 때 앞이 아니라 뒤가 잘리는 것이 맞다 — 이름을 읽는
   것이 목적이고, 전체 경로는 툴팁이 든다. */
.ext-line-path {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-mono);
  font-size: var(--text-2xs);
}

.ext-line-acts {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
}

.ext-line-act {
  padding: 2px var(--space-2);
  font-size: var(--text-2xs);
}

/* ---- 공간 (Orca의 Space) -------------------------------------------------
 *
 * 설정과 같은 층에 사는 전체 화면이다 — 사이드바까지 덮는다. 바닥은 창 자신의
 * 바닥(`--surface-abyss`)이고, 그것이 설정 화면과 같은 이유로 같은 값이다:
 * 창을 대신하는 화면은 창의 땅 위에 선다. */
.space-view {
  position: absolute;
  inset: 0;
  /* 설정과 같은 층. 떠 있는 터미널(그 위)과 무대(그 아래) 사이. */
  z-index: 6;
  overflow: auto;
  background: var(--surface-abyss);
}

/* 읽는 폭. 넓은 화면에서 전면 재단하면 상태 배지가 자기 이름에서 손 한 뼘
 * 떨어져 서고, 그 둘을 잇는 것이 이 화면의 일이다. */
.space-frame {
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
  width: min(1180px, 100%);
  margin: 0 auto;
  padding: var(--space-5) var(--space-5) var(--space-6);
}

.space-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-areas:
    "back back"
    "titles acts";
  gap: var(--space-3);
  align-items: end;
}

.space-back {
  grid-area: back;
  width: max-content;
  padding-left: 0;
}

.space-titles {
  grid-area: titles;
  min-width: 0;
}

.space-head-acts {
  grid-area: acts;
  display: flex;
  gap: var(--space-2);
}

.space-title {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  margin: 0;
  font-size: var(--text-xl);
  font-weight: 600;
  color: var(--ink-chalk);
}

.space-title .icon {
  width: 20px;
  height: 20px;
  color: var(--ink-mist);
}

/* Orca의 `Badge variant="secondary"` — 이 화면이 아직 자기 값을 증명하는
 * 중이라는 말이고, 그 말을 제목 옆에 두는 것이 그 말의 전부다. */
.space-beta {
  padding: 1px var(--space-2);
  border-radius: var(--radius-sm);
  background: var(--surface-raised);
  color: var(--ink-mist);
  font-size: var(--text-2xs);
  font-weight: 500;
  letter-spacing: 0.02em;
}

.space-lede {
  margin: var(--space-1) 0 0;
  color: var(--ink-mist);
  font-size: var(--text-sm);
}

/* 넷. 좁아지면 둘씩 접힌다 — 한 줄에 넷을 우겨넣으면 숫자가 자기 이름보다
 * 작아진다. */
.space-metrics {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: var(--space-3);
}

.space-metric {
  padding: var(--space-3);
  border: 1px solid var(--edge-rule);
  border-radius: var(--radius);
  background: var(--surface-deck);
}

.space-metric-name {
  margin: 0;
  color: var(--ink-label);
  font-size: var(--text-2xs);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.space-metric-value {
  margin: var(--space-1) 0 0;
  color: var(--ink-chalk);
  font-size: var(--text-lg);
  font-variant-numeric: tabular-nums;
}

.space-status {
  margin: 0;
  color: var(--ink-mist);
  font-size: var(--text-sm);
}

.space-repo-errors {
  margin: 0;
  padding: var(--space-2) var(--space-3);
  border: 1px solid var(--edge-rule);
  border-radius: var(--radius-md);
  background: var(--surface-deck);
  color: var(--signal-wait);
  font-size: var(--text-xs);
}

.space-visual {
  display: grid;
  grid-template-columns: minmax(0, 2fr) minmax(240px, 1fr);
  gap: var(--space-3);
}

@media (max-width: 900px) {
  .space-visual {
    grid-template-columns: minmax(0, 1fr);
  }
}

.space-map-box,
.space-breakdown {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  padding: var(--space-3);
  border: 1px solid var(--edge-rule);
  border-radius: var(--radius);
  background: var(--surface-deck);
  min-width: 0;
}

.space-map-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-2);
}

.space-panel-title {
  margin: 0;
  color: var(--ink-label);
  font-size: var(--text-2xs);
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.space-zoom {
  padding: 2px var(--space-2);
  font-size: var(--text-2xs);
}

/* 18rem — Orca의 `h-72`. 백분율 좌표계가 그 안에 눕는다. */
.space-map {
  position: relative;
  height: 288px;
  border-radius: var(--radius-md);
  background: var(--surface-well);
  overflow: hidden;
}

.space-map-note {
  margin: 0;
  color: var(--ink-mist);
  font-size: var(--text-xs);
}

/* 사각형 하나. 자리는 Rust가 정했고 여기서는 그것을 백분율로 앉힐 뿐이다.
 *
 * 다섯 칠을 돈다. Orca의 다섯 슬롯 중 셋은 차트 토큰이고 둘은 `--foreground`와
 * `--primary`인데, 이 창에서 그 둘은 이미 뜻이 있다 — 잉크로 물든 타일은
 * "골랐다"로 읽히고, 우리에게 `--primary`에 해당하는 역할은 AI 액센트뿐이라
 * "에이전트가 여기서 움직인다"로 읽힌다. 그래서 **섞는 비율은 Orca의 실측값
 * 그대로 두고 그 두 슬롯에만 우리 램프의 남은 두 칸을 넣었다.** */
.space-tile {
  position: absolute;
  display: block;
  overflow: hidden;
  padding: var(--space-2);
  border: 1px solid var(--surface-abyss);
  background: var(--treemap-fill);
  color: var(--ink-chalk);
  font-family: inherit;
  text-align: left;
  transition: border-color var(--motion-fast) var(--ease-standard);
  cursor: pointer;
}

.space-tile--1 {
  --treemap-fill: color-mix(in srgb, var(--chart-2) 34%, var(--surface-deck));
}

.space-tile--2 {
  --treemap-fill: color-mix(in srgb, var(--chart-3) 20%, var(--surface-deck));
}

.space-tile--3 {
  --treemap-fill: color-mix(in srgb, var(--chart-4) 28%, var(--surface-deck));
}

.space-tile--4 {
  --treemap-fill: color-mix(in srgb, var(--chart-5) 24%, var(--surface-deck));
}

.space-tile--5 {
  --treemap-fill: color-mix(in srgb, var(--chart-1) 38%, var(--surface-deck));
}

.space-tile:hover {
  border-color: var(--ink-mist);
}

/* 고른 것은 테두리로 말한다. 칠을 바꾸면 그 타일의 크기가 달라 보인다 —
 * 이 그림에서 색은 순서이지 값이 아니고, 값은 면적 하나뿐이다. */
.space-tile.is-picked {
  border-color: var(--ink-chalk);
  outline: 1px solid var(--ink-chalk);
  outline-offset: -2px;
}

.space-tile-name,
.space-tile-size {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--text-2xs);
  line-height: var(--leading-tight);
}

.space-tile-name {
  font-weight: 500;
}

.space-tile-size {
  margin-top: 2px;
  color: var(--ink-mist);
}

.space-breakdown-rows {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
  min-width: 0;
}

.space-break-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 2px var(--space-2);
  align-items: baseline;
}

.space-break-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--text-xs);
  color: var(--ink-chalk);
}

.space-break-size {
  color: var(--ink-mist);
  font-size: var(--text-2xs);
  font-variant-numeric: tabular-nums;
}

.space-break-bar {
  grid-column: 1 / -1;
  height: 4px;
  border-radius: 999px;
  background: var(--surface-well);
  overflow: hidden;
}

.space-break-fill {
  display: block;
  height: 100%;
  border-radius: 999px;
  background: color-mix(in srgb, var(--chart-2) 60%, var(--surface-deck));
}

.space-breakdown-note {
  margin: 0;
  color: var(--ink-mist);
  font-size: var(--text-xs);
}

/* 고른 것이 있을 때만 나타나고, 나타나면 표 위에 붙어 따라온다 — 스무 행을
 * 스크롤하는 동안 "선택한 N개 삭제"가 화면 밖으로 나가면, 사람은 자기가 무엇을
 * 골랐는지 확인하려고 위로 되돌아가야 한다. */
.space-picked {
  position: sticky;
  top: 0;
  z-index: 1;
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-2) var(--space-3);
  border: 1px solid var(--edge-rule);
  border-radius: var(--radius);
  background: var(--surface-raised);
}

.space-picked-label {
  color: var(--ink-chalk);
  font-size: var(--text-sm);
}

.space-picked-gap {
  flex: 1;
}

.space-filters {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
}

.space-search {
  flex: 1;
  min-width: 180px;
}

.space-table {
  display: flex;
  flex-direction: column;
  border: 1px solid var(--edge-rule);
  border-radius: var(--radius);
  background: var(--surface-deck);
  overflow: hidden;
}

/* Orca의 `max-h-[28rem]` — 표가 화면을 다 먹으면 위의 그림과 아래의 요약이
 * 함께 보이지 않는다. */
.space-rows {
  max-height: 448px;
  overflow-y: auto;
}

.space-row {
  display: grid;
  grid-template-columns: minmax(0, 2.2fr) minmax(0, 1fr) 96px 148px 116px;
  gap: var(--space-2);
  align-items: center;
  padding: var(--space-2) var(--space-3);
  border-top: 1px solid var(--edge-rule);
}

.space-row:first-child {
  border-top: 0;
}

.space-row--head {
  border-top: 0;
  border-bottom: 1px solid var(--edge-rule);
  background: var(--surface-well);
}

.space-row.is-picked {
  background: var(--row-hover);
}

.space-col {
  padding: 0;
  border: 0;
  background: none;
  color: var(--ink-label);
  font-family: inherit;
  font-size: var(--text-2xs);
  font-weight: 500;
  text-align: left;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.space-col--sort {
  transition: color var(--motion-fast) var(--ease-standard);
  cursor: pointer;
}

.space-col--sort:hover {
  color: var(--ink-chalk);
}

.space-col--num {
  text-align: right;
}

.space-col[aria-sort]::after {
  content: " ↓";
}

.space-col[aria-sort="ascending"]::after {
  content: " ↑";
}

.space-cell {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--text-xs);
  color: var(--ink-mist);
}

.space-cell--name {
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

.space-cell--size {
  text-align: right;
  color: var(--ink-chalk);
  font-variant-numeric: tabular-nums;
}

.space-name {
  min-width: 0;
  padding: 0;
  border: 0;
  background: none;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--ink-chalk);
  font-family: inherit;
  font-size: var(--text-xs);
  text-align: left;
  transition: text-decoration-color var(--motion-fast) var(--ease-standard);
  cursor: pointer;
}

.space-name:hover {
  text-decoration: underline;
}

.space-pick {
  flex: none;
}

.space-pill {
  display: inline-block;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  padding: 1px var(--space-2);
  border-radius: var(--radius-sm);
  background: var(--surface-raised);
  color: var(--ink-mist);
  font-size: var(--text-2xs);
}

.space-pill.is-ready {
  background: color-mix(in srgb, var(--signal-ready) 18%, var(--surface-deck));
  color: var(--signal-ready);
}

/* 실패는 그 행 안에서 말한다. 격자의 전체 폭을 차지하므로 어느 행의 실패인지
 * 헷갈릴 자리가 없다. */
.space-row-error {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  gap: var(--space-2);
  margin-top: var(--space-2);
  padding: var(--space-2);
  border-radius: var(--radius-md);
  background: color-mix(in srgb, var(--signal-halt) 14%, var(--surface-deck));
  color: var(--ink-chalk);
  font-size: var(--text-2xs);
}

.space-force {
  margin-left: auto;
  flex: none;
  padding: 2px var(--space-2);
  font-size: var(--text-2xs);
}

.space-empty,
.space-summary {
  margin: 0;
  color: var(--ink-mist);
  font-size: var(--text-xs);
}

/* ---- 리소스 관리자 팝오버 ---------------------------------------------
 *
 * Orca 1.4.187의 ResourceUsageStatusSegment 실측 구조: 26rem 폭, 420px
 * 트리, 오른쪽에 고정된 CPU/RSS 두 열, 2초마다 쌓이는 48×14 메모리
 * 스파크라인, 그리고 같은 표면 안의 Space 요약. 프로세스 수가 늘어도 패널
 * 자체가 자라지 않고 가운데 트리만 스크롤한다. */
.resource-pop {
  display: flex;
  flex-direction: column;
  width: min(26rem, calc(100vw - var(--space-4)));
  max-height: calc(100vh - var(--statusbar-height) - var(--space-4));
}

.resource-head {
  min-height: 38px;
  flex: none;
}

.resource-head-actions,
.resource-space-actions,
.resource-space-title {
  display: inline-flex;
  align-items: center;
}

.resource-head-actions {
  gap: var(--space-1);
}

.resource-head-action {
  display: grid;
  place-items: center;
  width: 24px;
  height: 24px;
  padding: 0;
  border: 0;
  border-radius: var(--radius-sm);
  background: none;
  color: var(--ink-mist);
  cursor: pointer;
  transition:
    color var(--motion-fast) var(--ease-standard),
    background-color var(--motion-fast) var(--ease-standard),
    opacity var(--motion-fast) var(--ease-standard);
}

.resource-head-action .icon {
  width: 13px;
  height: 13px;
}

.resource-head-action:hover:not(:disabled) {
  background: var(--row-hover);
  color: var(--ink-chalk);
}

.resource-head-action.is-danger:hover:not(:disabled) {
  color: var(--signal-halt);
}

.resource-head-action:disabled {
  opacity: 0.38;
  cursor: default;
}

.resource-head-action.is-spinning .icon,
.resource-session-end:disabled .icon,
.resource-space-scan.is-spinning .icon {
  animation: check-spin 1s linear infinite;
}

.resource-alert {
  display: flex;
  align-items: flex-start;
  gap: var(--space-2);
  flex: none;
  padding: var(--space-2) var(--space-3);
  border-bottom: var(--rule-width) solid var(--edge-rule);
  background: color-mix(in srgb, var(--signal-wait) 10%, transparent);
  color: var(--signal-wait);
  font-size: var(--text-2xs);
  line-height: var(--leading-ui);
}

.resource-alert .icon {
  width: 12px;
  height: 12px;
  flex: none;
  margin-top: 1px;
}

.resource-summary {
  display: flex;
  align-items: center;
  gap: 5px;
  min-height: 30px;
  flex: none;
  padding: var(--space-1) var(--space-3);
  border-bottom: var(--rule-width) solid var(--edge-rule);
  color: var(--ink-mist);
  font-size: var(--text-2xs);
  font-variant-numeric: tabular-nums;
}

.resource-summary-primary {
  color: var(--ink-chalk);
  font-weight: 500;
}

.resource-summary-kind {
  color: var(--ink-disabled);
}

.resource-orphans,
.sb-resource-orphans,
.sb-resource-warn {
  color: var(--signal-wait);
}

.sb-resource-orphans {
  margin-left: -3px;
  font-size: 10px;
  font-variant-numeric: tabular-nums;
}

.sb-resource-warn {
  width: 11px;
  height: 11px;
}

.resource-orphans {
  margin-left: auto;
}

.resource-columns {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 132px;
  align-items: center;
  min-height: 27px;
  flex: none;
  padding: 0 var(--space-2) 0 var(--space-3);
  border-bottom: var(--rule-width) solid var(--edge-rule);
  background: color-mix(in srgb, var(--surface-raised) 52%, transparent);
}

.resource-columns button {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  min-width: 0;
  padding: 0;
  border: 0;
  background: none;
  color: var(--ink-disabled);
  font: inherit;
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  cursor: pointer;
  transition: color var(--motion-fast) var(--ease-standard);
}

.resource-columns > button {
  justify-self: start;
}

.resource-columns button:hover,
.resource-columns button[aria-pressed="true"] {
  color: var(--ink-chalk);
}

.resource-columns button[data-direction="asc"]::after {
  content: "↑";
}

.resource-columns button[data-direction="desc"]::after {
  content: "↓";
}

.resource-column-metrics {
  display: grid;
  grid-template-columns: 48px 64px 20px;
  align-items: center;
}

.resource-column-metrics button {
  justify-content: flex-end;
}

.resource-body {
  height: 420px;
  min-height: 180px;
  flex: 0 1 420px;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
}

.resource-empty {
  margin: 0;
  padding: var(--space-6) var(--space-3);
  color: var(--ink-mist);
  font-size: var(--text-xs);
  text-align: center;
}

.resource-project,
.resource-worktree,
.resource-app {
  min-width: 0;
}

.resource-project + .resource-project,
.resource-app {
  border-top: var(--rule-width) solid var(--edge-rule);
}

.resource-project-head,
.resource-worktree-head,
.resource-app-head {
  display: grid;
  grid-template-columns: 20px minmax(0, 1fr) auto;
  align-items: center;
  min-height: 30px;
  padding: 0 var(--space-2) 0 var(--space-2);
  transition: background-color var(--motion-fast) var(--ease-standard);
}

.resource-project-head,
.resource-app-head {
  min-height: 32px;
}

.resource-project-head:hover,
.resource-worktree-head:hover,
.resource-app-head:hover {
  background: color-mix(in srgb, var(--row-hover) 70%, transparent);
}

.resource-twist {
  display: grid;
  place-items: center;
  width: 20px;
  height: 24px;
  padding: 0;
  border: 0;
  border-radius: var(--radius-sm);
  background: none;
  color: var(--ink-disabled);
  cursor: pointer;
  transition:
    color var(--motion-fast) var(--ease-standard),
    background-color var(--motion-fast) var(--ease-standard);
}

.resource-twist:hover {
  background: var(--row-hover);
  color: var(--ink-chalk);
}

.resource-twist.is-empty {
  pointer-events: none;
}

.resource-chevron,
.resource-chevron .icon {
  display: block;
  width: 11px;
  height: 11px;
}

.resource-project-name,
.resource-worktree-name,
.resource-session-name,
.resource-worktree-open {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.resource-project-name {
  color: var(--ink-chalk);
  font-size: var(--text-xs);
  font-weight: 600;
}

.resource-worktree-open {
  display: inline-flex;
  align-items: baseline;
  gap: var(--space-1);
  justify-self: start;
  max-width: 100%;
  padding: 2px 0;
  border: 0;
  background: none;
  color: var(--ink-label);
  font: inherit;
  font-size: var(--text-xs);
  cursor: pointer;
  transition: color var(--motion-fast) var(--ease-standard);
}

.resource-worktree-open:hover:not(:disabled) {
  color: var(--ink-chalk);
}

.resource-worktree-open:disabled {
  color: var(--ink-mist);
  cursor: default;
}

.resource-remote {
  flex: none;
  color: var(--ink-disabled);
  font-size: 10px;
  font-weight: 400;
}

.resource-project-trailing,
.resource-worktree-trailing {
  display: grid;
  align-items: center;
}

.resource-project-trailing {
  grid-template-columns: 112px 20px;
}

.resource-worktree-trailing {
  grid-template-columns: 48px 112px 20px;
}

.resource-worktree-graph {
  position: relative;
  display: grid;
  place-items: center;
  width: 48px;
  height: 24px;
}

.resource-sparkline {
  display: block;
  width: 48px;
  height: 14px;
  overflow: visible;
  color: color-mix(in srgb, var(--ink-mist) 72%, transparent);
  opacity: 0.8;
  transition: opacity var(--motion-fast) var(--ease-standard);
}

.resource-sparkline polyline {
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.25;
  vector-effect: non-scaling-stroke;
}

.resource-worktree-delete {
  position: absolute;
  inset: 2px 12px;
  display: grid;
  place-items: center;
  width: 24px;
  height: 20px;
  padding: 0;
  border: 0;
  border-radius: var(--radius-sm);
  background: var(--surface-raised);
  color: var(--signal-halt);
  opacity: 0;
  pointer-events: none;
  cursor: pointer;
  transition:
    opacity var(--motion-fast) var(--ease-standard),
    color var(--motion-fast) var(--ease-standard),
    background-color var(--motion-fast) var(--ease-standard);
}

.resource-worktree-delete .icon {
  width: 11px;
  height: 11px;
}

.resource-worktree-delete:hover:not(:disabled) {
  background: color-mix(in srgb, var(--signal-halt) 14%, var(--surface-raised));
}

.resource-worktree-delete:disabled {
  color: var(--ink-disabled);
  cursor: not-allowed;
}

.resource-worktree-head:hover .resource-worktree-graph:has(.resource-worktree-delete) .resource-sparkline,
.resource-worktree-head:focus-within .resource-worktree-graph:has(.resource-worktree-delete) .resource-sparkline {
  opacity: 0;
}

.resource-worktree-head:hover .resource-worktree-delete,
.resource-worktree-head:focus-within .resource-worktree-delete {
  opacity: 1;
  pointer-events: auto;
}

.resource-metrics {
  display: grid;
  grid-template-columns: 48px 64px;
  width: 112px;
  color: var(--ink-mist);
  font-size: 11px;
  font-variant-numeric: tabular-nums;
  line-height: 1;
}

.resource-metrics > span {
  overflow: hidden;
  text-align: right;
  text-overflow: clip;
  white-space: nowrap;
}

.resource-metrics.is-small {
  font-size: 10px;
}

.resource-metrics.is-unavailable {
  color: var(--ink-disabled);
}

.resource-action-gutter {
  display: grid;
  place-items: center;
  width: 20px;
  min-width: 20px;
  height: 24px;
}

.resource-session,
.resource-browser,
.resource-app-subrow {
  display: grid;
  grid-template-columns: 8px minmax(0, 1fr) 112px 20px;
  align-items: center;
  min-height: 27px;
  width: 100%;
  padding: 0 var(--space-2) 0 36px;
  border: 0;
  background: none;
  color: var(--ink-mist);
  font: inherit;
  font-size: var(--text-xs);
  text-align: left;
  transition:
    color var(--motion-fast) var(--ease-standard),
    background-color var(--motion-fast) var(--ease-standard);
}

.resource-session-open {
  padding: 0;
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
  text-align: left;
}

.resource-session-open,
.resource-browser {
  cursor: pointer;
}

.resource-session:hover,
.resource-session:focus-visible,
.resource-browser:hover,
.resource-browser:focus-visible,
.resource-app-subrow:hover {
  background: color-mix(in srgb, var(--row-hover) 70%, transparent);
  color: var(--ink-label);
}

.resource-session-state {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--ink-disabled);
}

.resource-session-state.is-bound {
  background: var(--signal-ready);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--signal-ready) 12%, transparent);
}

.resource-session-end {
  display: grid;
  place-items: center;
  width: 20px;
  height: 20px;
  padding: 0;
  border: 0;
  border-radius: var(--radius-sm);
  background: none;
  color: var(--ink-mist);
  opacity: 0;
  cursor: pointer;
  transition:
    opacity var(--motion-fast) var(--ease-standard),
    color var(--motion-fast) var(--ease-standard),
    background-color var(--motion-fast) var(--ease-standard);
}

.resource-session-end .icon {
  width: 11px;
  height: 11px;
}

.resource-session:hover .resource-session-end,
.resource-session:focus-within .resource-session-end,
.resource-session-end:disabled {
  opacity: 1;
}

.resource-session-end:hover:not(:disabled) {
  background: color-mix(in srgb, var(--signal-halt) 12%, transparent);
  color: var(--signal-halt);
}

.resource-browser > .icon {
  width: 10px;
  height: 10px;
  color: var(--ink-disabled);
}

.resource-app-head .resource-project-trailing {
  grid-template-columns: 48px 112px 20px;
}

.resource-app-subrow {
  grid-template-columns: minmax(0, 1fr) 112px 20px;
  padding-left: 36px;
  color: var(--ink-disabled);
  font-size: 11px;
}

.resource-cleanup {
  flex: none;
  border-top: var(--rule-width) solid var(--edge-rule);
}

.resource-cleanup > button {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  min-height: 33px;
  padding: 0 var(--space-3);
  border: 0;
  background: none;
  color: var(--ink-mist);
  font: inherit;
  font-size: var(--text-xs);
  cursor: pointer;
  transition:
    color var(--motion-fast) var(--ease-standard),
    background-color var(--motion-fast) var(--ease-standard);
}

.resource-cleanup > button:hover {
  background: var(--row-hover);
  color: var(--ink-chalk);
}

.resource-cleanup .icon {
  width: 11px;
  height: 11px;
}

.resource-space {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  flex: none;
  padding: var(--space-3);
  border-top: var(--rule-width) solid var(--edge-rule);
  background: color-mix(in srgb, var(--surface-raised) 35%, transparent);
}

.resource-space-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3);
}

.resource-space-title {
  gap: var(--space-2);
  min-width: 0;
  color: var(--ink-chalk);
  font-size: var(--text-xs);
  font-weight: 500;
}

.resource-space-title .icon {
  width: 12px;
  height: 12px;
  color: var(--ink-mist);
}

.resource-beta {
  padding: 1px 5px;
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: 999px;
  color: var(--ink-disabled);
  font-size: 9px;
  font-weight: 500;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.resource-space-actions {
  gap: var(--space-1);
  flex: none;
}

.resource-space-actions .btn {
  min-height: 24px;
  padding: 2px var(--space-2);
  font-size: var(--text-2xs);
}

.resource-space-actions .icon {
  width: 10px;
  height: 10px;
}

.resource-space-line {
  min-height: 14px;
  margin: 0;
  overflow: hidden;
  color: var(--ink-mist);
  font-size: var(--text-2xs);
  line-height: var(--leading-ui);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.resource-space-metrics {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--space-2);
}

.resource-space-metrics > span {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.resource-space-metrics small {
  overflow: hidden;
  color: var(--ink-disabled);
  font-size: 9px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.resource-space-metrics strong {
  overflow: hidden;
  color: var(--ink-label);
  font-size: var(--text-2xs);
  font-variant-numeric: tabular-nums;
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}

@media (max-height: 640px) {
  .resource-pop {
    overflow-y: auto;
  }

  .resource-body {
    min-height: 120px;
  }

  .resource-space-metrics {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .resource-head-action.is-spinning .icon,
  .resource-session-end:disabled .icon,
  .resource-space-scan.is-spinning .icon {
    animation: none;
  }
}

/* ---- 브라우저 탭 (1-fy) --------------------------------------------------
 *
 * Orca의 BrowserPane 툴바 실측(unsaved-close-queue-BHrI4TA0.js): ←/→/새로고침,
 * 주소창이 남는 폭을 다 갖고, 오른쪽 끝에 바깥으로 여는 문. 페이지 자체는
 * 네이티브 자식 웹뷰가 .browser-body 사각형 위에 얹혀 그린다 — 여기 규칙은
 * 그 구멍의 테두리까지만이다. */

.browser-view {
  display: flex;
  flex-direction: column;
}

/* 시뮬레이터 거울(1-g28): 위 한 줄 툴바, 아래는 프레임이 앉는 어두운 몸.
 * 프레임은 몸 안에 맞춰 줄고, 안내문은 첫 프레임이 오기 전과 멈춘 뒤에만. */
.emulator-view {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 0;
}
.emulator-toolbar {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-1) var(--space-2);
  border-bottom: var(--rule-width) solid var(--edge-rule);
}
/* 붙지 못한 이유가 다음 성공까지 서 있는 자리. 토스트와 달리 다시 읽을 수
 * 있고, 기기 화면 위가 아니라 도구모음 아래라 그림을 가리지 않는다. */
.emulator-alert {
  padding: var(--space-1) var(--space-2);
  border-bottom: var(--rule-width) solid var(--edge-rule);
  background: color-mix(in srgb, var(--signal-halt) 10%, transparent);
  color: var(--signal-halt);
  font-size: var(--text-2xs);
}
.emulator-name {
  font-size: var(--text-xs);
  font-weight: 500;
  color: var(--ink-chalk);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.emulator-gap {
  flex: 1;
}
/* 기기가 놓이는 바닥. 원본의 `bg-muted`(EmulatorPane.tsx:67)와 같은 값을
 * 우리 이름으로 부른다 — 밝은 테마 #f5f5f5, 어두운 테마 #262626.
 *
 * 여백은 여기 padding 하나가 소유한다. 레이아웃은 이 요소의 사각형에서 그
 * padding을 빼고 남은 자리를 재므로(`layoutEmulatorScreen`), 값은 토큰 한
 * 곳에만 있고 창은 그것을 읽기만 한다. */
.emulator-body {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: var(--device-stage-inset-y) var(--device-stage-inset-x);
  background: var(--surface-raised);
  position: relative;
  /* 레이아웃이 픽셀을 재기 전 한 박자의 넘침도 판 밖으로 못 나간다(1-g45). */
  overflow: hidden;
}
/* 잰 픽셀이 앉는 껍데기(1-g45) — 베젤과, 그 밖 여유에 서는 폰 옆 버튼. */
.emulator-shell {
  position: relative;
  flex: none;
  display: flex;
  align-items: center;
  justify-content: center;
  max-width: 100%;
  max-height: 100%;
}
.emulator-side-key {
  position: absolute;
  padding: 0;
  border: 0;
  background: var(--device-key);
  cursor: pointer;
  transition:
    background var(--motion-press) var(--ease-standard),
    transform var(--motion-press) var(--ease-standard);
}
.emulator-side-key:hover:not(:disabled) {
  background: var(--device-key-lit);
}
.emulator-side-key:active:not(:disabled) {
  transform: translateX(var(--emulator-key-travel, 0));
  background: var(--device-key-pressed);
}
.emulator-side-key:disabled {
  cursor: default;
}
.emulator-side-key[data-side="left"] {
  border-radius: var(--radius-xs) 0 0 var(--radius-xs);
  --emulator-key-travel: var(--rule-width);
}
.emulator-side-key[data-side="right"] {
  border-radius: 0 var(--radius-xs) var(--radius-xs) 0;
  --emulator-key-travel: calc(-1 * var(--rule-width));
}
/* 상태를 낱말로도 형태로도 말한다.
 *
 * 꽉 찬 원 / 속 빈 고리 / 헤어라인 원 셋은 색과 독립적으로 같은 정보를 나르므로
 * 색을 못 보는 눈에서도 살아남고(`docs/design/direction.md` 1절), 점은 주변시로
 * 잡히므로 11px 낱말을 읽으러 시선을 옮길 필요가 없다. */
.emulator-status {
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
  font-size: var(--text-xs);
  color: var(--ink-mist);
  white-space: nowrap;
}
.emulator-status::before {
  content: "";
  width: var(--status-dot);
  height: var(--status-dot);
  border-radius: 50%;
  flex: none;
}
.emulator-status[data-state="live"]::before {
  background: var(--signal-ready);
}
.emulator-status[data-state="working"]::before {
  box-shadow: inset 0 0 0 var(--status-dot-ring) var(--signal-wait);
}
.emulator-status[data-state="off"]::before {
  box-shadow: inset 0 0 0 var(--rule-width) var(--edge-mark);
}
.emulator-glyph {
  display: inline-flex;
  color: var(--ink-mist);
}
.emulator-keys {
  display: inline-flex;
  gap: var(--device-key-gap);
}
/* 살아 있는 Android 화면은 만질 수 있다 — 손가락 커서가 그렇게 말한다.
 * 화면은 screencap의 <img>이거나 H264 터널의 <canvas>다(1-g35). */
.emulator-frame.is-interactive,
.emulator-canvas.is-interactive {
  cursor: pointer;
  touch-action: none;
}
/* 기기 고르는 상자. 크기는 원본 실측(`w-[180px] h-7`)이고, 그 28px는 이 창의
 * 다른 셀렉트(`.skills-pick`)가 이미 쓰는 높이다 — 같은 물건은 같은 치수로
 * 선다. 배경만 다르다: 이것은 도구모음 안에 앉으므로 제 바탕을 갖지 않는다. */
.emulator-pick {
  max-width: var(--device-pick-width);
  height: var(--control-height-sm);
  font-size: var(--text-xs);
  background-color: transparent;
  color: var(--ink-chalk);
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-sm);
  padding-inline: var(--space-2);
}
/* 이름이 말하는 꼴의 베젤(resolveDeviceFrameKind) — 폰은 갸름하고 태블릿은
 * 모서리가 유하다. 화면은 베젤 안에서만 산다. */
/* 껍데기 그 자체. 배경은 앱 테마가 아니라 기기의 물성이고(`--device-shell`),
 * 위쪽 모서리의 빛 한 줄이 두께를 만든다 — 원본은 검정 한 겹이라 어두운 판
 * 위에서 기기의 윤곽이 판에 먹힌다. */
.emulator-bezel {
  max-width: 100%;
  max-height: 100%;
  padding: var(--device-bezel-pad);
  border-radius: var(--device-radius-shell);
  border: var(--rule-width) solid var(--device-shell-edge);
  background: linear-gradient(
      var(--device-shell-sheen),
      transparent var(--device-shell-sheen-depth)
    ),
    var(--device-shell);
  box-shadow: var(--device-shell-shadow);
  display: flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
}
.emulator-bezel.is-tablet {
  border-radius: var(--device-radius-shell-tablet);
  padding: var(--device-bezel-pad-tablet);
}
/* 화면. 배경이 검은 이유는 `contain`이 남기는 레터박스 자리 때문이다 —
 * 배경이 없으면 그 띠로 판 바닥이 비쳐, 기기 화면이 아니라 구멍으로 읽힌다.
 * 안쪽 실선 한 줄은 원본의 `ring-1 ring-white/10`과 같은 자리다. */
.emulator-frame,
.emulator-canvas {
  max-width: 100%;
  max-height: 100%;
  object-fit: contain;
  border-radius: var(--device-radius-screen);
  background: var(--device-screen);
  box-shadow: inset 0 0 0 var(--rule-width) var(--device-screen-edge);
}
.emulator-bezel.is-tablet .emulator-frame,
.emulator-bezel.is-tablet .emulator-canvas {
  border-radius: var(--device-radius-screen-tablet);
}
/* 기다리는 동안 화면 자리에 서는 것. `layoutEmulatorScreen`이 화면과 똑같은
 * 크기·모서리를 얹으므로 첫 그림이 앉을 때 아무것도 움직이지 않는다. */
.emulator-skeleton {
  background: var(--skeleton-fill);
  animation: usage-blank-pulse var(--skeleton-period) var(--ease-standard) infinite;
}
/* 움직임을 원치 않는 눈에는 박동만 걷는다 — 채움은 남아야 그 자리가 화면이라는
 * 말이 유지된다. */
@media (prefers-reduced-motion: reduce) {
  .emulator-skeleton {
    animation: none;
  }
}
/* 첫 그림은 켜지듯 앉는다. 스켈레톤과 형제라서 할 수 있는 일이다 — 원본은
 * 스피너와 그림이 서로 다른 return 가지라 둘 사이에 트랜지션이 설 자리가 없다. */
.emulator-frame,
.emulator-canvas {
  transition: opacity var(--motion-fast) var(--ease-enter);
}
/* 판을 든 사람이 지금 키보드를 먹는다는 것을 기기의 실루엣으로 말한다 —
 * 브라우저 기본 아웃라인은 반경 54px짜리 껍데기에 각진 사각형으로 그려진다. */
.emulator-shell:focus-visible {
  outline: none;
}
.emulator-shell:focus-visible .emulator-bezel,
.emulator-side-key:focus-visible {
  outline: none;
  box-shadow:
    var(--device-shell-shadow),
    0 0 0 var(--ring-width) color-mix(in srgb, var(--ring) 50%, transparent);
}
/* 안내 문구는 기기 위가 아니라 기기 위쪽에 쌓인다 — 정중앙 절대배치는 그림이
 * 오는 순간 화면 한복판을 가린다. */
.emulator-note {
  flex: none;
  margin-bottom: var(--space-4);
  font-size: var(--text-xs);
  color: var(--ink-mist);
  text-align: center;
}

.browser-toolbar {
  /* relative: 좁은 판에서 주소창이 이 행 기준의 오버레이로 뜬다 — 원본도
   * 툴바 행이 위치 조상이다(BrowserAddressBar.tsx:356-358). */
  position: relative;
  display: flex;
  flex: none;
  align-items: center;
  gap: var(--space-1);
  padding: var(--space-1) var(--space-2);
  border-bottom: var(--rule-width) solid var(--edge-rule);
}

.browser-btn {
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  border: 0;
  border-radius: var(--radius-sm);
  background: none;
  color: var(--ink-mist);
  cursor: pointer;
  transition:
    background 120ms ease,
    color 120ms ease;
}

.browser-btn:hover:not(:disabled) {
  background: var(--row-hover);
  color: var(--ink-chalk);
}

.browser-btn:disabled {
  opacity: 0.4;
  cursor: default;
}

.browser-btn .icon {
  width: 14px;
  height: 14px;
}

/* 도는 동안 새로고침 단추가 스피너를 입는다 — 트랙 회전은 워크트리 스피너의
 * 것을 그대로 쓴다: 이 창의 "돌고 있다" 어휘는 하나다. */
.browser-btn.is-loading .icon {
  animation: worktree-spin 700ms linear infinite;
}

/* 잡기(디자인 모드)가 무장한 동안 그 판의 단추는 켜져 있음을 반전으로 말한다 —
 * Orca가 잡기 컨트롤에 입히는 `bg-foreground text-background`와 같은 어휘를,
 * 하드코딩한 색 대신 이 창의 토큰(잉크를 바탕으로, 심연을 글자로)으로. 전환은
 * `.browser-btn`이 이미 가지고 있으니 켜짐/꺼짐이 미끄러진다. */
.browser-btn.is-armed,
.browser-btn.is-armed:hover:not(:disabled) {
  background: var(--ink-chalk);
  color: var(--surface-abyss);
}

/* 주석 수는 컨트롤 모서리의 알약 — Orca의 -top-1 -right-1 min-w-4 rounded-full
 * 뱃지를 이 창의 토큰으로. 뱃지가 곧 보내기 문이라 pointer-events를 산다. */
.browser-btn {
  position: relative;
}

/* 주석 줄 — 툴바 아래 한 줄: 몇 개 모였고, 어디로 보내며, 어떻게 비우나. */
/* 찾기 스트립은 두 판에서 같은 꼴로 선다(1-g38): 브라우저 판의 것과 프리뷰의
 * 것은 같은 손짓이므로 같은 규칙을 탄다 — 두 벌이면 두 벌이 어긋난다. */
.browser-notes,
.browser-findbar,
.doc-findbar {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: 4px var(--space-2);
  background: var(--surface-well);
  border-bottom: var(--rule-width) solid var(--edge-rule);
}
.browser-find-input,
.doc-find-input {
  flex: 1;
  min-width: 0;
  background: transparent;
  color: var(--ink-chalk);
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-sm);
  padding: 2px var(--space-2);
  font-size: var(--text-xs);
}
.browser-find-count,
.doc-find-count {
  font-size: var(--text-xs);
  color: var(--ink-mist);
  white-space: nowrap;
  min-width: 3em;
  text-align: right;
}
/* Orca의 구분 막대 — 개수·화살표·닫기를 가르는 한 줄, 스트립의 이음매와 같은 색. */
.browser-find-sep,
.doc-find-sep {
  flex: 0 0 auto;
  width: 0;
  height: 14px;
  border-left: var(--rule-width) solid var(--edge-rule);
}
.browser-find-prev,
.browser-find-next,
.browser-find-close,
.doc-find-prev,
.doc-find-next,
.doc-find-close {
  border: 0;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--ink-mist);
  font-size: var(--text-xs);
  padding: 2px 6px;
  cursor: pointer;
  transition:
    background 120ms ease,
    color 120ms ease;
}
.browser-find-prev:hover,
.browser-find-next:hover,
.browser-find-close:hover,
.doc-find-prev:hover,
.doc-find-next:hover,
.doc-find-close:hover {
  background: var(--row-hover);
  color: var(--ink-chalk);
}

/* ------------------------------------------- AI에게 남길 메모 (1-g43·1-g46)
 * 메모는 아래 어딘가의 목록이 아니라 **그 블록 옆**에 산다 — Orca의
 * MarkdownPreview 실측 그대로, 최상위 블록마다 오른쪽 여백 컬럼이 서고
 * (본문 1fr + 220~300px, 사이 32px), 카드는 제 블록의 여백에 쌓인다.
 * 좁은 판(760px 아래)에서는 여백이 블록 밑으로 눕는다. */
.mdview-body {
  /* 아래 @container의 기준 — 판의 너비가 여백의 자세를 정한다. */
  container-type: inline-size;
}

.mdview-note-block {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(220px, min(28cqw, 300px));
  column-gap: 32px;
  align-items: start;
  position: relative;
}

.mdview-note-block > :not(.mdview-note-rail) {
  grid-column: 1;
  min-width: 0;
}

.mdview-note-block.has-notes > :not(.mdview-note-rail) {
  cursor: pointer;
}

.mdview-note-rail {
  grid-area: 1 / 2;
  min-width: 0;
  position: relative;
}

/* +는 스치면 나타난다 — 본문과 여백 사이 홈에 서고(왼쪽 -26px), 여백이
 * 본문 밑으로 누운 좁은 판에서는 제 흐름의 자리로 돌아온다. */
.mdview-note-add {
  position: absolute;
  top: 2px;
  left: -26px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  padding: 0;
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-sm);
  background: var(--surface-deck);
  color: var(--ink-mist);
  cursor: pointer;
  opacity: 0;
  transition: opacity 0.1s, color 0.1s, background-color 0.1s;
}

.mdview-note-block:hover > .mdview-note-rail > .mdview-note-add,
.mdview-note-block:focus-within > .mdview-note-rail > .mdview-note-add {
  opacity: 1;
}

.mdview-note-add:hover {
  background: var(--surface-raised);
  color: var(--ink-chalk);
}

.mdview-note-add:focus-visible {
  outline: 2px solid var(--nav-plane-accent);
  outline-offset: 1px;
  opacity: 1;
}

.mdview-note-stack {
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 0;
}

.mdview-note-railseat {
  margin-top: 0;
  scroll-margin: 12px;
}

.mdview-note-railseat + .mdview-note-stack {
  margin-top: 8px;
}

.mdview-note-railseat .note-composer {
  margin: 0;
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-sm);
  padding: 8px;
  background: var(--surface-deck);
  box-shadow: 0 1px 2px color-mix(in srgb, var(--ink-chalk) 12%, transparent);
}

/* 카드 한 장(Orca DiffCommentCard 실측): 줄 이름표와 지우는 손, 긁은 글의
 * 인용(호박색 왼단), 남긴 말. 지금 가리키는 카드와 방금 불린 카드는 제
 * 옷(is-active/is-attention)을 입는다. */
.mdview-note-card {
  min-width: 0;
  padding: 12px 14px;
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-md);
  background: var(--surface-deck);
  font-size: var(--text-xs);
  scroll-margin: 12px;
  box-shadow: 0 1px 3px color-mix(in srgb, var(--ink-chalk) 4%, transparent),
    0 4px 12px color-mix(in srgb, var(--ink-chalk) 3%, transparent);
  /* 움직임은 공통 전이 목록(위 .mdview-note-card가 든 그 규칙)이 준다. */
}

.mdview-note-card:hover,
.mdview-note-card.is-active {
  border-color: color-mix(in srgb, var(--ink-chalk) 18%, transparent);
  background: color-mix(in srgb, var(--ink-chalk) 4%, var(--surface-deck));
}

.mdview-note-card.is-attention {
  animation: 0.9s ease-out mdview-note-attention;
}

/* 부른 카드의 눈길 — 링이 번졌다가 가라앉고, 몸이 살짝 물러났다 돌아온다
 * (Orca markdown-note-attention 실측). */
@keyframes mdview-note-attention {
  0% {
    box-shadow: 0 0 0 1px color-mix(in srgb, var(--nav-plane-accent) 55%, transparent),
      0 0 0 8px color-mix(in srgb, var(--nav-plane-accent) 16%, transparent);
    transform: translateX(0);
  }
  35% {
    box-shadow: 0 0 0 1px color-mix(in srgb, var(--nav-plane-accent) 45%, transparent),
      0 0 0 5px color-mix(in srgb, var(--nav-plane-accent) 12%, transparent);
    transform: translateX(-3px);
  }
  100% {
    box-shadow: 0 0 0 0 transparent, 0 0 0 0 transparent;
    transform: translateX(0);
  }
}

.mdview-note-head {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  min-width: 0;
}

.mdview-note-line {
  flex: 1;
  min-width: 0;
  color: var(--ink-chalk);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.mdview-note-quote {
  margin: 2px 0 4px;
  padding-left: 8px;
  border-left: 2px solid color-mix(in srgb, var(--annotation-highlight) 35%, transparent);
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  color: var(--ink-mist);
}

.mdview-note-body {
  margin-top: 2px;
  white-space: pre-wrap;
  word-break: break-word;
  color: var(--ink-chalk);
}

/* 수정 중엔 몸의 자리에 작곡가가 앉는다(1-g47) — 카드 안이라 제 여백만. */
.mdview-note-card .note-composer {
  margin: 4px 0 0;
}

.mdview-note-del {
  flex: none;
}

/* 좁은 판: 여백이 본문 밑으로 눕는다(Orca @container 760px 실측). */
@container (max-width: 760px) {
  .mdview-note-block {
    display: block;
  }

  .mdview-note-rail {
    margin-top: 6px;
  }

  .mdview-note-add {
    position: static;
  }

  .mdview-note-railseat,
  .mdview-note-stack {
    margin-top: 6px;
  }
}

/* 찾은 것과 지금 서 있는 것.
 *
 * `<mark>`로 감싸지 않고 Range를 등록부에 걸므로, 칠은 여기서만 일어난다 —
 * 문서의 구조는 검색 전과 한 글자도 다르지 않다. 색은 이 창이 이미 가진
 * 검색 쌍(`--markdown-search-match` / `-active`)이다: tokens.css가 그 자리에
 * "두 번째 쌍은 두 판이 노랑의 뜻을 두고 어긋나게 만드는 중복"이라고 적어 두었고,
 * 이 판도 같은 뜻으로 노랗다. 글자색은 건드리지 않는다 — 울타리 안의 코드가
 * 검색 때문에 다른 토큰처럼 보이면 안 된다(`.hit-mark`와 같은 이유). */
::highlight(mdview-search-match) {
  background-color: color-mix(in srgb, var(--markdown-search-match) 38%, transparent);
}

::highlight(mdview-search-active-match) {
  background-color: color-mix(in srgb, var(--markdown-search-match-active) 46%, transparent);
}

.browser-grabbar {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: 4px var(--space-2);
  background: var(--surface-well);
  border-bottom: var(--rule-width) solid var(--edge-rule);
  font-size: var(--text-xs);
  color: var(--ink-chalk);
}

.browser-grabbar-words {
  flex: 1;
  color: var(--ink-mist);
}

.browser-grabbar-cancel {
  border: 0;
  border-radius: var(--radius-sm);
  background: none;
  color: var(--ink-mist);
  font: inherit;
  font-size: var(--text-xs);
  padding: 2px 8px;
  cursor: pointer;
  transition:
    background 120ms ease,
    color 120ms ease;
}

.browser-grabbar-cancel:hover {
  background: var(--row-hover);
  color: var(--ink-chalk);
}

.browser-notes-count {
  flex: 1;
}

.browser-notes-send,
.browser-notes-clear {
  border: 0;
  border-radius: var(--radius-sm);
  background: none;
  color: var(--ink-mist);
  font: inherit;
  font-size: var(--text-xs);
  padding: 2px 8px;
  cursor: pointer;
  transition:
    background 120ms ease,
    color 120ms ease;
}

.browser-notes-send {
  background: var(--ink-chalk);
  color: var(--surface-abyss);
}

.browser-notes-clear:hover {
  background: var(--row-hover);
  color: var(--ink-chalk);
}

.browser-badge {
  position: absolute;
  top: -4px;
  right: -4px;
  min-width: 14px;
  height: 14px;
  padding: 0 3px;
  border-radius: 999px;
  background: var(--ink-chalk);
  color: var(--surface-abyss);
  font-size: 10px;
  line-height: 14px;
  text-align: center;
  cursor: pointer;
}

/* 주소창의 flex 자리를 쥐는 슬롯(실측 BrowserAddressBar.tsx:330-333
 * `flex min-w-11 flex-1`): 다른 컨트롤이 전부 flex:none이라 좁은 판의
 * 짜부라짐은 전부 이 자리 몫이고, 최소 44px은 접힌 뒤에도 남아 입력을
 * 다시 여는 어포던스가 된다. 입력이 오버레이로 떠도 슬롯은 이 폭을
 * 지키니 측정이 진동하지 않는다(:45-46 주석). */
.browser-address-slot {
  display: flex;
  flex: 1;
  min-width: 44px;
  align-items: center;
}

/* 220px 문턱 밑 + focus — 입력이 툴바 행 위의 오버레이로 선다(실측
 * `absolute inset-x-3 top-1/2 z-30 -translate-y-1/2` + 검정 18% 그림자
 * `0 10px 24px rgba(0,0,0,0.18)`, BrowserAddressBar.tsx:353-361 — 색은
 * 이 창의 그림자 어휘인 color-mix로). */
.browser-address.is-overlaying {
  position: absolute;
  inset-inline: var(--space-2);
  top: 50%;
  transform: translateY(-50%);
  width: auto;
  z-index: 30;
  box-shadow: var(--shadow-overlay-bar);
}

.browser-address {
  flex: 1;
  min-width: 0;
  height: 26px;
  padding: 0 var(--space-2);
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-sm);
  background: var(--surface-well);
  color: var(--ink-chalk);
  font: inherit;
  font-size: var(--text-xs);
  outline: none;
}

.browser-address::placeholder {
  color: var(--ink-mist);
}

.browser-body {
  flex: 1;
  min-height: 0;
  /* 네이티브 웹뷰가 이 위에 얹힌다. 페이지가 아직 없을 때 비쳐 보이는 바닥.
   * relative는 마크업 편집기의 자리 잡기 — 판이 눕는 동안 편집기가 이
   * 사각형을 그대로 입는다. */
  position: relative;
  background: var(--surface-deck);
}

/* ---- 스크린샷 마크업(B02 ②) — Orca MarkupOverlay의 실측 옷 ----
 * 오버레이 `absolute inset-0 z-20`, 바탕 이미지 `objectFit: fill`, 캔버스는
 * `touch-none cursor-crosshair`, 아래 가운데에 도구 막대(`rounded-md border
 * bg-card/95 px-1.5 py-1 shadow-md backdrop-blur`)와 확인 줄. */
.browser-markup-editor {
  position: absolute;
  inset: 0;
  overflow: hidden;
  z-index: 3;
}

.browser-markup-stage {
  position: absolute;
  inset: 0;
}

.browser-markup-img {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
  object-fit: fill;
  pointer-events: none;
  user-select: none;
}

.browser-markup-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  touch-action: none;
  cursor: crosshair;
}

.browser-markup-text {
  position: absolute;
  min-width: 40px;
  max-width: 70%;
  border: 0;
  outline: none;
  background: none;
  padding: 0;
  font-family:
    ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  font-weight: 600;
  line-height: 1.1;
}

.browser-markup-dock {
  position: absolute;
  inset-inline: 0;
  bottom: 12px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--space-2);
  pointer-events: none;
}

.browser-markup-bar,
.browser-markup-confirm {
  pointer-events: auto;
  display: flex;
  align-items: center;
  gap: 4px;
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius);
  background: color-mix(in srgb, var(--surface-abyss) 95%, transparent);
  padding: 4px 6px;
  box-shadow: var(--shadow-2);
  backdrop-filter: var(--glass-blur);
  -webkit-backdrop-filter: var(--glass-blur);
}

.browser-markup-tool {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border: 0;
  border-radius: var(--radius-sm);
  background: none;
  color: var(--ink-mist);
  cursor: pointer;
}

.browser-markup-tool .icon {
  width: 16px;
  height: 16px;
}

.browser-markup-tool:hover {
  background: var(--row-hover);
  color: var(--ink-chalk);
}

/* 눌린 도구는 전경을 입는다(실측 `bg-foreground/80 text-background`). */
.browser-markup-tool[aria-pressed="true"] {
  background: color-mix(in srgb, var(--ink-chalk) 80%, transparent);
  color: var(--surface-abyss);
}

.browser-markup-sep {
  flex: 0 0 auto;
  width: 0;
  height: 20px;
  margin: 0 2px;
  border-left: var(--rule-width) solid var(--edge-rule);
}

.browser-markup-dot {
  width: 16px;
  height: 16px;
  border-radius: 999px;
  border: var(--rule-width) solid var(--edge-rule);
}

.browser-markup-fontsize {
  width: auto;
  padding: 0 8px;
  gap: 4px;
  display: inline-flex;
  align-items: center;
  font-size: 11px;
  font-variant-numeric: tabular-nums;
}

.browser-markup-pop-wrap {
  position: relative;
  display: inline-flex;
}

.browser-markup-pop {
  position: absolute;
  bottom: calc(100% + 6px);
  left: 0;
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius);
  background: var(--surface-abyss);
  padding: var(--space-2);
  box-shadow: var(--shadow-2);
}

.browser-markup-swatches {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}

.browser-markup-swatch {
  width: 24px;
  height: 24px;
  border-radius: 999px;
  border: var(--rule-width) solid var(--edge-rule);
  cursor: pointer;
}

.browser-markup-swatch[aria-pressed="true"] {
  box-shadow: 0 0 0 var(--ring-width) var(--ring);
}

.browser-markup-widths,
.browser-markup-sizes {
  display: flex;
  align-items: center;
  gap: 4px;
}

.browser-markup-width,
.browser-markup-size {
  display: grid;
  place-items: center;
  flex: 1;
  min-width: 28px;
  height: 24px;
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-sm);
  background: none;
  color: var(--ink-chalk);
  font: inherit;
  font-size: 11px;
  font-variant-numeric: tabular-nums;
  cursor: pointer;
}

.browser-markup-width:hover,
.browser-markup-size:hover {
  background: var(--row-hover);
}

.browser-markup-width[aria-pressed="true"],
.browser-markup-size[aria-pressed="true"] {
  border-color: var(--ring);
  background: var(--row-hover);
}

.browser-markup-width span {
  display: block;
  border-radius: 999px;
  background: var(--ink-chalk);
}

.browser-markup-hint {
  padding: 0 4px;
  font-size: var(--text-2xs);
  color: var(--ink-mist);
}

.browser-markup-act {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  height: 28px;
  padding: 0 10px;
  border: 0;
  border-radius: var(--radius-sm);
  background: var(--surface-well);
  color: var(--ink-chalk);
  font: inherit;
  font-size: 11px;
  cursor: pointer;
}

.browser-markup-act .icon {
  width: 14px;
  height: 14px;
}

.browser-markup-act:hover {
  background: var(--row-hover);
}

.browser-markup-copy {
  background: var(--ink-chalk);
  color: var(--surface-abyss);
}

.browser-markup-copy:hover {
  background: color-mix(in srgb, var(--ink-chalk) 88%, transparent);
}

.browser-markup-copy:disabled {
  opacity: 0.6;
  cursor: default;
}

/* Caffeinate 세그먼트 (P0-17 잔여) — Orca CaffeinateStatusSegment: 모드
 * 낱말 곁의 활동 점(size-1.5 rounded-full, 활동 시 전경색·아니면 흐린
 * 회색:108-117), 팝오버의 세 줄 선택. */
.sb-awake-dot {
  flex: none;
  width: var(--dot-size);
  height: var(--dot-size);
  border-radius: 50%;

  /* Resting: the idle-shape role, the same ink an idle worktree's dot wears
   * (Orca dims its resting dot the same one step, :113-117). */
  background: var(--edge-mark);
}

/* Working: full foreground, Orca's `bg-foreground` for the active dot. */
.sb-awake-dot.is-active {
  background: var(--ink-chalk);
}

/* Orca's popover is `w-64` — 256px (CaffeinateStatusSegment.tsx:150). */
.caffeinate-pop {
  width: 256px;
}

.caffeinate-options {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
  padding: var(--space-1);
}

.caffeinate-option {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 1px;
  padding: 6px 8px;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: inherit;
  font: inherit;
  cursor: pointer;
  text-align: left;
}

.caffeinate-option:hover {
  background: var(--row-hover);
}

.caffeinate-option.is-active {
  background: var(--row-selected);
}

/* 벨이 데려온 판의 한 번 번쩍임 (P0-14) — Orca `flashFocusedPane`
 * (native-notification-delivery.ts:102). 초점 링의 제 색·제 굵기로 두
 * 번 맥동하는 900ms: 눈이 새 문맥을 잡는 한 호흡이고, 애니메이션이므로
 * hover 모션 규칙과는 다른 길이다. */
@keyframes pane-called {
  0%,
  40%,
  100% {
    box-shadow: none;
  }
  20%,
  60% {
    box-shadow: inset 0 0 0 var(--ring-width) var(--ring);
  }
}

.pane-slot.is-called {
  animation: pane-called 900ms ease-out;
}

/* 쿠키 가져오기 요약 카드 — note-pop 위에 줄 몇 개와 단추 하나. */
.cookie-import-pop {
  max-width: 340px;
  padding: var(--space-3);
}

.cookie-import-line {
  margin: 0 0 var(--space-1);
  font-weight: 600;
}

.cookie-import-quiet {
  margin: 0 0 var(--space-1);
  color: var(--ink-label);
  font-size: var(--text-xs);
}

.cookie-import-reopen {
  margin-top: var(--space-2);
}

/* ---- 토큰 사용량 화면 (P1 사용량 ⑧) ----
 *
 * 워커 페이지와 같은 판 위에 산다 — 스크롤은 뷰가, 여백은 판이 갖는다. 표는
 * 숫자가 오른쪽으로 정렬되고 탭 숫자(`tabular-nums`)라야 자릿수가 흔들리지
 * 않는다: 날짜별 행이 수십 줄 쌓이는 화면에서 그 흔들림이 가장 크게 보인다. */
.tokens-view {
  height: 100%;
  overflow-y: auto;
  padding: var(--space-4);
  background: var(--surface-deck);
  color: var(--ink-chalk);
}

.tokens-head {
  display: flex;
  align-items: baseline;
  gap: var(--space-3);
  margin-bottom: var(--space-3);
}

.tokens-name {
  font-weight: 600;
}

.tokens-note,
.tokens-quiet {
  color: var(--ink-label);
  font-size: var(--text-xs);
}

.tokens-gap {
  flex: 1;
}

/* 장부 전환 — 탭과 같은 문법: 켠 쪽이 잉크를 얻는다. */
.tokens-pick {
  display: inline-flex;
  gap: var(--space-1);
}

.tokens-provider.is-active {
  color: var(--ink-chalk);
  background: color-mix(in srgb, var(--ink-chalk) 6%, var(--surface-deck));
}

.tokens-quiet {
  margin: 0 0 var(--space-1);
}

.tokens-section {
  margin: var(--space-4) 0 var(--space-2);
  font-size: var(--text-sm);
  font-weight: 600;
  color: var(--ink-label);
}

.tokens-table {
  width: 100%;
  border-collapse: collapse;
  font-size: var(--text-xs);
}

.tokens-table th,
.tokens-table td {
  padding: 4px 8px;
  border-bottom: 1px solid var(--edge-rule);
  text-align: left;
  white-space: nowrap;
}

.tokens-table th {
  color: var(--ink-label);
  font-weight: 500;
}

.tokens-table .tokens-num {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

/* 무엇을 언제 보고 있는지 — 카드 위 한 줄. */
.tokens-status {
  margin: 0 0 var(--space-3);
  color: var(--ink-label);
  font-size: var(--text-xs);
}

/* 여덟 장이 폭에 따라 넷·둘·하나로 접힌다. 카드는 눌리지 않으므로
 * :hover도 transition도 없다. */
.tokens-cards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(168px, 1fr));
  gap: var(--space-2);
  margin-bottom: var(--space-3);
}

.tokens-card {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  padding: var(--space-2) var(--space-3);
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-md);
  background: var(--surface-raised);
}

.tokens-card-mark {
  display: inline-flex;
  color: var(--ink-glyph);
}

.tokens-card-body {
  display: grid;
  min-width: 0;
}

.tokens-card-value {
  font-size: var(--text-lg);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.tokens-card-label {
  color: var(--ink-label);
  font-size: var(--text-xs);
}

/* 일별 추이 — 눈금 하나(가장 높은 날), 판, 양 끝 날짜, 범례. */
.tokens-chart {
  margin: 0 0 var(--space-2);
}

.tokens-chart-scale {
  display: flex;
  justify-content: flex-end;
  color: var(--ink-label);
  font-size: var(--text-2xs);
  font-variant-numeric: tabular-nums;
}

.tokens-chart-plot {
  display: block;
  width: 100%;
  height: 140px;
}

.tokens-chart-seg--input {
  fill: var(--usage-input);
}

.tokens-chart-seg--output {
  fill: var(--usage-output);
}

.tokens-chart-seg--cache-read {
  fill: var(--usage-cache-read);
}

.tokens-chart-seg--cache-write {
  fill: var(--usage-cache-write);
}

/* 아무것도 쓰지 않은 날의 자국 — 없음도 그려야 없음이 보인다. */
.tokens-chart-empty {
  fill: var(--edge-rule);
}

/* 칸 전체를 덮는 판정 사각형. 1px 조각을 겨누게 하지 않는다. */
.tokens-chart-hit {
  fill: transparent;
  pointer-events: all;
}

.tokens-chart-days {
  display: flex;
  justify-content: space-between;
  color: var(--ink-label);
  font-size: var(--text-2xs);
}

.tokens-legend {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-3);
  margin: var(--space-2) 0 0;
  padding: 0;
  list-style: none;
  color: var(--ink-label);
  font-size: var(--text-xs);
}

.tokens-legend li {
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
}

.tokens-swatch {
  width: 8px;
  height: 8px;
  border-radius: var(--radius-xs);
}

.tokens-swatch--input {
  background: var(--usage-input);
}

.tokens-swatch--output {
  background: var(--usage-output);
}

.tokens-swatch--cache-read {
  background: var(--usage-cache-read);
}

.tokens-swatch--cache-write {
  background: var(--usage-cache-write);
}

/* ---- 지식 그래프 ----------------------------------------------------------
 *
 * 볼트의 `wiki/`가 그림이 되는 판. 에이전트 그래프와 나눠 쓰는 것은 캔버스의
 * 기구(미는 몸짓·바퀴·프레임·간선 페인터)이고, 여기 있는 것은 이 그림만의
 * 옷이다. 색은 한 자도 새로 만들지 않는다: 점의 물듦은 창이 이미 들고 있는
 * 그래프 레인 램프(`--git-graph-lane-*`)에서 오고, 그래서 라이트 판이 그 램프에
 * 이미 하는 뒤집기를 그대로 받는다.
 *
 * 수치도 한 자도 여기서 만들지 않는다 — 반지름·라벨·여백·배율·문턱·티어 폭은
 * 전부 `tokens.css`의 `--knowledge-*`이고, JS는 판이 지어질 때 그 값을 한 번
 * 읽는다(`knowledgeTuning`). 같은 수를 두 곳에 적으면 그중 한 곳만 고쳐지는
 * 날이 오고, 그날 그림과 시험은 서로 다른 판을 말한다. */
.knowledge-view {
  display: flex;
  flex-direction: column;
  width: 100%;
  max-width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  background: var(--surface-deck);
  color: var(--ink-chalk);
}

/* 티어 ————
 *
 * 배치를 정하는 것은 창의 폭이 아니라 **이 판의 폭**이다: 같은 창에서도 판이
 * 반으로 갈리면 인스펙터를 옆에 둘 자리가 없고, 그때 `@media`는 아직 넓다고
 * 답한다. 그래서 문턱은 `--knowledge-tier-*` 셋이고 답은 판 자신에게 붙는
 * `is-tier-*` 클래스다 — 컨테이너 쿼리로 적을 수 없는 것은 컨테이너가 제
 * 자신에게는 옷을 입히지 못하기 때문이고(재는 상자와 옷을 입는 상자가 같다),
 * 그래서 재는 일만 JS가 하고 값은 여전히 토큰 한 곳에 있다.
 *
 * wide → 인스펙터가 옆. 그 아래 셋은 아래로 쌓이고, compact부터 렌즈가
 * 팝오버로, tiny에서 범례가 「?」로 접힌다. 어느 티어에서도 목적지를
 * `display:none`으로 **지우지 않는다** — 접힌 것은 열 수 있지만 지워진 것은
 * 열 수 없다. */
.knowledge-body {
  position: relative;
  display: flex;
  flex: 1;
  min-height: 0;
  flex-direction: column;
}

.knowledge-view.is-tier-wide .knowledge-body {
  flex-direction: row;
}

.knowledge-surface {
  position: relative;
  display: flex;
  flex: 1;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
}

/* 그림과 그 위에 뜬 것들. 범례는 이 상자 **밖**, 아래에 선다 — 떠 있는 배율
 * 상자가 재는 바닥이 그림의 바닥이어야 하기 때문이다. */
.knowledge-stage {
  position: relative;
  display: flex;
  flex: 1;
  min-width: 0;
  min-height: 0;
}

.knowledge-head {
  position: relative;
  display: flex;
  flex: none;
  flex-wrap: nowrap;
  gap: var(--space-1);
  align-items: center;
  min-height: var(--workbench-head-min-height);
  padding: var(--space-3) var(--space-4);
  border-bottom: var(--rule-width) solid var(--edge-rule);
  background: var(--workbench-ambient), var(--surface-deck);
}

/* 머리의 어느 칸도 제 내용만큼 넓다고 우기지 않는다 — 우기는 칸 하나가 좁은
 * 판에서 가로 스크롤을 만들고, 가로로 스크롤하는 툴바는 툴바가 아니다. */
.knowledge-head > * {
  min-width: 0;
}

.knowledge-name {
  flex: none;
  margin-right: var(--space-2);
  white-space: nowrap;
}

.knowledge-query {
  flex: none;
  width: 100%;
  max-width: 100%;
  height: var(--control-height-sm);
  padding: var(--space-1) var(--space-2);
  appearance: none;
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-sm);
  background: var(--surface-well);
  color: var(--ink-chalk);
  font: inherit;
  transition: border-color var(--motion-fast) var(--ease-standard);
}

.knowledge-query::placeholder {
  color: var(--ink-mist);
}

.knowledge-query:focus-visible {
  outline: var(--accent-rule) solid var(--ink-chalk);
  outline-offset: var(--knowledge-focus-offset);
}

.knowledge-gap {
  flex: 1;
}

.knowledge-stat {
  flex: none;
  color: var(--ink-label);
  font-size: var(--text-xs);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

/* 같은 사실의 긴 벌과 짧은 벌. 좁은 판이 고르는 것은 어느 쪽을 **보일지**이지
 * 어느 쪽을 지울지가 아니다 — 둘 다 서 있어야 낭독기가 티어와 무관하게 같은
 * 문장을 읽는다. */
.knowledge-stat-full {
  display: none;
}

.knowledge-stat-compact {
  display: inline;
}

/* 좁은 판(compact·tiny)에서 상태 문구는 낭독기에게만 선다 — 규칙은 `.sr` 하나를
 * 함께 쓴다(시트 머리). 줄어들지 않는 이 벌 하나가 320px 잎에서 검색 칸을 0으로
 * 누르고 머리를 가로로 넘치게 했다(t-4140 회귀, 반응형 워크벤치 시험). 지우지
 * 않고 화면 밖에 두는 것은 위의 규칙 그대로 — `role="status"`는 티어와 무관하게
 * 같은 문장을 읽는다. */

/* 「보기」 메뉴(시안 이식). 렌즈·태그·시간 슬라이서·저장 시야·다시 읽기는 어느 티어에서도
 * 이 팝오버 뒤에 산다 — 머리에는 모드·검색·목차 표시·상태만 남는다. 접힌 자리는
 * 팝오버이지 쓰레기통이 아니다: 여는 단추 하나가 모든 티어에 선다. */
.knowledge-lens-toggle {
  display: inline-flex;
  flex: none;
  gap: var(--space-1);
  white-space: nowrap;
}

.knowledge-view.is-tier-compact .knowledge-lens-toggle span,
.knowledge-view.is-tier-tiny .knowledge-lens-toggle span {
  display: none;
}

.knowledge-lens-popover {
  position: absolute;
  z-index: 3;
  top: 100%;
  right: var(--space-4);
  display: none;
  flex-wrap: wrap;
  gap: var(--space-2);
  align-items: center;
  max-width: calc(100% - var(--space-4) * 2);
  min-width: 0;
  padding: var(--space-2);
  border: var(--rule-width) solid var(--edge-glint);
  border-radius: var(--radius);
  background: var(--surface-glass);
  backdrop-filter: var(--knowledge-glass-blur);
  -webkit-backdrop-filter: var(--knowledge-glass-blur);
  box-shadow: var(--shadow-soft);
}

.knowledge-view.is-tier-compact .knowledge-lens-popover,
.knowledge-view.is-tier-tiny .knowledge-lens-popover {
  left: var(--space-4);
}

.knowledge-lens-popover.is-open {
  display: flex;
}

.knowledge-view-tools {
  display: flex;
  flex: none;
  gap: var(--space-1);
  align-items: center;
}

/* 네 렌즈는 한 세그먼트 컨트롤이다. 아이콘과 짧은 낱말은 빠르게 훑는 표면이고,
 * 긴 뜻은 접근 가능한 이름에 그대로 남는다. */
.knowledge-sift {
  flex: none;
  gap: 0;
  overflow: hidden;
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-sm);
}

.knowledge-flag {
  gap: var(--space-1);
  border: 0;
  border-radius: 0;
  white-space: nowrap;
}

.knowledge-flag + .knowledge-flag {
  border-left: var(--rule-width) solid var(--edge-rule);
}

/* 「목차·일지 표시」는 머리의 제 단추다(시안) — 세그먼트의 옷을 벗고 테두리를 되찾는다. */
.knowledge-nav-toggle {
  flex: none;
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-sm);
}

.knowledge-nav-toggle.is-active {
  border-color: var(--edge-glint);
  background: var(--row-active);
  color: var(--ink-chalk);
}

.knowledge-view.is-toolbar-compact .knowledge-nav-toggle span,
.knowledge-view.is-tier-compact .knowledge-nav-toggle span,
.knowledge-view.is-tier-tiny .knowledge-nav-toggle span {
  display: none;
}

.knowledge-tags {
  position: relative;
  display: flex;
  flex: 1 1 auto;
  gap: var(--space-1);
  align-items: center;
  min-width: 0;
}

.knowledge-tags-more-toggle {
  flex: none;
}

.knowledge-tags-popover {
  position: absolute;
  z-index: 4;
  top: 100%;
  right: 0;
  display: none;
  flex-wrap: wrap;
  gap: var(--space-1);
  min-width: var(--knowledge-tags-popover-width);
  padding: var(--space-2);
  border: var(--rule-width) solid var(--edge-glint);
  border-radius: var(--radius);
  background: var(--surface-glass);
  box-shadow: var(--shadow-soft);
}

.knowledge-tags-popover.is-open {
  display: flex;
}

/* 시간 슬라이서 (Bloom 문법) — 접이식 툴바 컨트롤. 기본 「전체」, 디밍만(재배치 없음). */
.knowledge-slicer {
  position: relative;
  display: inline-flex;
  align-items: center;
  flex: none;
}

.knowledge-slicer-toggle {
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
}

.knowledge-slicer-toggle.is-active {
  color: var(--nav-plane-ring);
  background: var(--row-active);
  border-color: var(--nav-plane-ring);
}

.knowledge-slicer-popover {
  position: absolute;
  z-index: 4;
  top: 100%;
  right: 0;
  display: none;
  flex-direction: column;
  gap: var(--space-2);
  min-width: 200px;
  padding: var(--space-3);
  border: var(--rule-width) solid var(--edge-glint);
  border-radius: var(--radius);
  background: var(--surface-glass);
  backdrop-filter: var(--knowledge-glass-blur);
  -webkit-backdrop-filter: var(--knowledge-glass-blur);
  box-shadow: var(--shadow-soft);
}

.knowledge-slicer-popover.is-open {
  display: flex;
}

.knowledge-slicer-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: var(--text-xs);
  color: var(--ink-label);
}

.knowledge-slicer-slider {
  width: 100%;
  accent-color: var(--nav-plane-ring);
  cursor: pointer;
}

.knowledge-slicer-presets {
  display: flex;
  gap: var(--space-1);
  flex-wrap: wrap;
}

.knowledge-slicer-preset {
  font-size: var(--text-xs);
  padding: 2px var(--space-2);
}

.knowledge-slicer-preset.is-active {
  background: var(--row-active);
  color: var(--nav-plane-ring);
  border-color: var(--nav-plane-ring);
}

/* 저장 시야 (Bloom 문법) — 툴바 ★ 버튼 및 팝오버. */
.knowledge-scene {
  position: relative;
  display: inline-flex;
  align-items: center;
  flex: none;
}

.knowledge-scene-toggle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: var(--text-sm);
  padding: 0 var(--space-2);
}

.knowledge-scene-popover {
  position: absolute;
  z-index: 4;
  top: 100%;
  right: 0;
  display: none;
  flex-direction: column;
  gap: var(--space-2);
  min-width: 220px;
  padding: var(--space-3);
  border: var(--rule-width) solid var(--edge-glint);
  border-radius: var(--radius);
  background: var(--surface-glass);
  backdrop-filter: var(--knowledge-glass-blur);
  -webkit-backdrop-filter: var(--knowledge-glass-blur);
  box-shadow: var(--shadow-soft);
}

.knowledge-scene-popover.is-open {
  display: flex;
}

.knowledge-scene-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: var(--text-xs);
  color: var(--ink-label);
}

.knowledge-scene-create {
  display: flex;
  gap: var(--space-1);
}

.knowledge-scene-input {
  flex: 1;
  font-size: var(--text-xs);
  padding: var(--space-1) var(--space-2);
}

.knowledge-scene-save {
  font-size: var(--text-xs);
  padding: var(--space-1) var(--space-2);
}

.knowledge-scene-list {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
  max-height: 200px;
  overflow-y: auto;
}

.knowledge-scene-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-1);
}

.knowledge-scene-load {
  flex: 1;
  display: inline-flex;
  align-items: center;
  text-align: left;
  font-size: var(--text-xs);
  padding: var(--space-1) var(--space-2);
}

.knowledge-scene-delete {
  font-size: var(--text-xs);
  padding: var(--space-1) var(--space-2);
  color: var(--ink-mist);
  transition:
    background-color var(--motion-fast) var(--ease-standard),
    border-color var(--motion-fast) var(--ease-standard),
    color var(--motion-fast) var(--ease-standard);
}

.knowledge-scene-delete:hover {
  color: var(--signal-halt);
}

.knowledge-scene-empty {
  font-size: var(--text-xs);
  color: var(--ink-mist);
  padding: var(--space-2) 0;
  text-align: center;
}

/* 검색 토큰 및 저장 검색어 (Bloom 문법) */
/* 검색은 머리에서 자란다(시안): 남는 폭을 토큰의 상한까지 가진다. */
.knowledge-search {
  position: relative;
  display: inline-flex;
  flex: 1 1 auto;
  max-width: var(--knowledge-search-max-width);
  min-width: 0;
}

.knowledge-view.is-tier-middle .knowledge-search,
.knowledge-view.is-tier-compact .knowledge-search,
.knowledge-view.is-tier-tiny .knowledge-search {
  flex: 1 1 auto;
  min-width: 0;
}

.knowledge-search-suggest {
  position: absolute;
  z-index: 4;
  top: 100%;
  left: 0;
  display: none;
  flex-direction: column;
  gap: var(--space-2);
  min-width: 260px;
  padding: var(--space-2);
  border: var(--rule-width) solid var(--edge-glint);
  border-radius: var(--radius);
  background: var(--surface-glass);
  backdrop-filter: var(--knowledge-glass-blur);
  -webkit-backdrop-filter: var(--knowledge-glass-blur);
  box-shadow: var(--shadow-soft);
}

.knowledge-search.is-suggesting .knowledge-search-suggest {
  display: flex;
}

.knowledge-search-tokens {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-1);
}

/* 검색 후보(t-4140 S3): 상자 맨 위의 리스트박스. 짚은 줄은 `aria-selected`가 말하고
 * 옷은 그것을 읽는다. */
.knowledge-search-results {
  display: flex;
  flex-direction: column;
  gap: 2px;
  max-height: var(--knowledge-candidates-max-height);
  margin: 0;
  padding: 0;
  overflow: auto;
  list-style: none;
}

.knowledge-search-results[hidden],
.knowledge-candidates-empty[hidden] {
  display: none;
}

.knowledge-search-results li {
  display: flex;
  gap: var(--space-1);
  align-items: center;
  border-radius: var(--radius-sm);
  transition: background-color var(--motion-fast) var(--ease-standard);
}

.knowledge-candidate {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  gap: 1px;
  min-width: 0;
  padding: var(--space-1) var(--space-2);
  border: 0;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--ink-chalk);
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.knowledge-candidate-title {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.knowledge-candidate-note {
  overflow: hidden;
  color: var(--ink-label);
  font-size: var(--text-xs);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.knowledge-search-results li:hover,
.knowledge-search-results li[aria-selected="true"] {
  background: var(--row-active);
}

.knowledge-candidate-explore {
  flex: none;
  padding: 0 var(--space-2);
  font-size: var(--text-xs);
}

.knowledge-candidates-empty {
  margin: 0;
  padding: var(--space-1) var(--space-2);
  color: var(--ink-label);
  font-size: var(--text-xs);
}

.knowledge-token-chip {
  font-size: var(--text-xs);
  padding: 2px var(--space-2);
  border-radius: var(--radius-sm);
  background: var(--surface-well);
  color: var(--ink-chalk);
  transition:
    background-color var(--motion-fast) var(--ease-standard),
    border-color var(--motion-fast) var(--ease-standard),
    color var(--motion-fast) var(--ease-standard);
}

.knowledge-token-chip:hover {
  background: var(--row-hover);
  color: var(--nav-plane-ring);
}

.knowledge-saved-phrases {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
  border-top: var(--rule-width) solid var(--edge-glint);
  padding-top: var(--space-1);
}

.knowledge-saved-phrases-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: var(--text-xs);
  color: var(--ink-label);
}

.knowledge-save-phrase {
  font-size: var(--text-xs);
  padding: 1px var(--space-1);
  color: var(--ink-label);
}

.knowledge-saved-phrases-list {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-1);
}

.knowledge-search-phrase-chip {
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
  font-size: var(--text-xs);
  padding: 2px var(--space-2);
  border-radius: var(--radius-sm);
  background: var(--surface-well);
  color: var(--ink-chalk);
}

.knowledge-phrase-text {
  cursor: pointer;
  transition:
    background-color var(--motion-fast) var(--ease-standard),
    border-color var(--motion-fast) var(--ease-standard),
    color var(--motion-fast) var(--ease-standard);
}

.knowledge-phrase-text:hover {
  color: var(--nav-plane-ring);
}

.knowledge-delete-phrase {
  cursor: pointer;
  color: var(--ink-mist);
  padding: 0 2px;
  transition:
    background-color var(--motion-fast) var(--ease-standard),
    border-color var(--motion-fast) var(--ease-standard),
    color var(--motion-fast) var(--ease-standard);
}

.knowledge-delete-phrase:hover {
  color: var(--signal-halt);
}

/* 네 깃발과 태그 칩은 같은 문법으로 켜진다 — 이 창의 다른 토글들과 같게, 켠
 * 쪽이 잉크를 얻고 배경을 얻는다. */
.knowledge-sift,
.knowledge-chips {
  display: flex;
  flex-wrap: nowrap;
  gap: var(--space-1);
  align-items: center;
}

.knowledge-chips {
  min-width: 0;
  overflow: hidden;
}

.knowledge-flag.is-active {
  border-color: var(--edge-glint);
  background: var(--row-active);
  color: var(--ink-chalk);
}

.knowledge-chip {
  display: inline-flex;
  gap: var(--space-1);
  align-items: center;
  max-width: var(--knowledge-tag-chip-max-width);
  padding: 2px var(--space-2);
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-sm);
  background: none;
  color: var(--ink-label);
  font-size: var(--text-xs);
  cursor: pointer;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  transition:
    background-color var(--motion-fast) var(--ease-standard),
    border-color var(--motion-fast) var(--ease-standard),
    color var(--motion-fast) var(--ease-standard);
}

.knowledge-refresh,
.knowledge-export {
  flex: none;
}

.knowledge-view.is-tier-tiny .knowledge-head {
  padding: var(--space-2) var(--space-2);
  gap: var(--space-1);
}

.knowledge-view.is-tier-tiny .knowledge-scene-toggle {
  padding: 0 var(--space-1);
}

.knowledge-view.is-tier-tiny .knowledge-slicer-label {
  display: none;
}

.knowledge-view.is-tier-middle .knowledge-name,
.knowledge-view.is-tier-compact .knowledge-name,
.knowledge-view.is-tier-tiny .knowledge-name {
  display: none;
}

.knowledge-view.is-tier-middle .knowledge-query,
.knowledge-view.is-tier-compact .knowledge-query,
.knowledge-view.is-tier-tiny .knowledge-query {
  flex: 1 1 auto;
  width: auto;
  min-width: 0;
}

.knowledge-view.is-toolbar-compact .knowledge-tags-more-toggle,
.knowledge-view.is-tier-middle .knowledge-tags-more-toggle,
.knowledge-view.is-tier-compact .knowledge-tags-more-toggle,
.knowledge-view.is-tier-tiny .knowledge-tags-more-toggle {
  display: none;
}

.knowledge-view.is-toolbar-compact .knowledge-tags-popover,
.knowledge-view.is-tier-middle .knowledge-tags-popover,
.knowledge-view.is-tier-compact .knowledge-tags-popover,
.knowledge-view.is-tier-tiny .knowledge-tags-popover {
  position: static;
  display: flex;
  min-width: 0;
  padding: 0;
  border: 0;
  background: none;
  box-shadow: none;
}

.knowledge-chip::before {
  content: "";
  width: var(--knowledge-chip-dot);
  height: var(--knowledge-chip-dot);
  border-radius: 50%;
  background: var(--knowledge-tint, var(--ink-glyph));
}

.knowledge-chip:hover,
.knowledge-chip:focus-visible {
  border-color: var(--edge-glint);
  color: var(--ink-chalk);
  outline: none;
}

.knowledge-chip.is-active {
  border-color: var(--knowledge-tint, var(--edge-glint));
  background: var(--row-active);
  color: var(--ink-chalk);
}

.knowledge-canvas {
  flex: 1;
  min-width: 0;
  min-height: 0;
  background: var(--knowledge-ground);
  cursor: grab;
  touch-action: none;
  position: relative;
  overflow: hidden;
}

.knowledge-canvas:focus-visible {
  outline: var(--accent-rule) solid var(--ink-chalk);
  outline-offset: var(--knowledge-focus-offset);
}

.knowledge-canvas.is-panning {
  cursor: grabbing;
}

.knowledge-canvas.is-empty {
  background-image: none;
}

.knowledge-picture {
  display: block;
  width: 100%;
  height: 100%;
}

/* GL 페인터의 세 층 (6차 P2).
 *
 * 절의 머리(`/* ---- `)를 달지 않는 것은 이 옷들이 지식 그래프 절의 **안**이기
 * 때문이다: 소스 계약이 그 절을 머리에서 머리까지로 잘라 색과 하드코딩을 세고,
 * 새 머리는 그 자를 여기서 끊는다(실측: 색 칸 매핑 8 → 0).
 *
 * 캔버스가 맨 아래에서 성운·선·점을 지고, 그 위에 <svg>가 이름판과 관계의 낱말만
 * 들고 서고, 맨 위가 이름표 오버레이다. <svg>는 GL 판에서 점과 선을 한 개도 들지
 * 않으므로 그 층을 통과시켜야 손이 아래의 그림에 닿는다 — 포인터는 캔버스의 것이다. */
.knowledge-gl {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

.knowledge-picture.is-gl {
  position: relative;
  pointer-events: none;
}

/* 성운은 GL이 그린다 — 같은 원반을 두 손이 그리면 색이 두 번 얹힌다. 자리는
   여전히 SVG의 타원이 들고 있고(이름판이 그 수를 읽는다) 보이지만 않는다. */
.knowledge-picture.is-gl .knowledge-nebula {
  display: none;
}

/* 층은 통과시키되 **누르는 것**은 되살린다. 주제의 이름판은 그 군집을 펼치는
   컨트롤이다(5차) — 부모의 `pointer-events: none`을 물려받으면 GL 판에서만 죽은
   컨트롤이 된다(검증 09-16). */
.knowledge-picture.is-gl .knowledge-cluster-label {
  pointer-events: visiblePainted;
}

.knowledge-gl-labels {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
}

/* 이름표 한 장. 격자가 **예약한 상자의 한가운데**에 서므로 자리 옮김은
   translate(-50%, -50%)이고, 글자의 모양은 SVG의 이름표와 같은 토큰에서 온다. */
.knowledge-gl-label {
  position: absolute;
  top: 0;
  left: 0;
  white-space: nowrap;
  color: var(--ink-mist);
  font-size: calc(var(--knowledge-label-px) * 1px);
  line-height: 1;
  text-shadow:
    0 0 calc(var(--knowledge-label-outline-px) * 1px) var(--knowledge-ground),
    0 0 calc(var(--knowledge-label-outline-px) * 1px) var(--knowledge-ground);
  /* SVG에서 이름은 점의 <g> 안에 있어 이름을 누르면 그 점이 골라진다. 오버레이의
     이름도 같은 손이다 — 제 점의 열쇠를 들고(`data-graph-key`) 포인터를 받는다. */
  cursor: pointer;
  pointer-events: auto;
}

/* 색을 묻는 견본. 그려지지는 않지만 계산은 된다 — `display: none`이면 브라우저가
   값을 풀어 주지 않는 판이 있어 크기를 0으로 두고 숨긴다. */
.knowledge-gl-swatch {
  position: absolute;
  width: 0;
  height: 0;
  overflow: hidden;
  opacity: 0;
  pointer-events: none;
}

/* 색은 군집에서(3차), 그리고 **한 규칙에서**.
 *
 * 여덟 칸의 색은 토큰이 들고(라이트 판의 뒤집기도 토큰이 한다), 이 매핑이 사는
 * 자리는 여기 한 곳뿐이다 — 점과 칩과 성운과 목록의 줄이 저마다 제 매핑을 들고
 * 있으면 아홉째 색이 생기는 날 다섯 곳 중 넷만 고쳐진다. 물드는 쪽은
 * `--knowledge-tint`와 세 채움만 읽는다. 군집이 없는 점은 물들지 않는다 — 색은
 * 구분이지 장식이 아니다. */
.knowledge-view [data-hue="0"] { --knowledge-tint: var(--knowledge-hue-0); --knowledge-node-fill: url(#knowledge-node-gradient-0); --knowledge-halo-fill: url(#knowledge-halo-gradient-0); --knowledge-nebula-fill: url(#knowledge-nebula-gradient-0); }
.knowledge-view [data-hue="1"] { --knowledge-tint: var(--knowledge-hue-1); --knowledge-node-fill: url(#knowledge-node-gradient-1); --knowledge-halo-fill: url(#knowledge-halo-gradient-1); --knowledge-nebula-fill: url(#knowledge-nebula-gradient-1); }
.knowledge-view [data-hue="2"] { --knowledge-tint: var(--knowledge-hue-2); --knowledge-node-fill: url(#knowledge-node-gradient-2); --knowledge-halo-fill: url(#knowledge-halo-gradient-2); --knowledge-nebula-fill: url(#knowledge-nebula-gradient-2); }
.knowledge-view [data-hue="3"] { --knowledge-tint: var(--knowledge-hue-3); --knowledge-node-fill: url(#knowledge-node-gradient-3); --knowledge-halo-fill: url(#knowledge-halo-gradient-3); --knowledge-nebula-fill: url(#knowledge-nebula-gradient-3); }
.knowledge-view [data-hue="4"] { --knowledge-tint: var(--knowledge-hue-4); --knowledge-node-fill: url(#knowledge-node-gradient-4); --knowledge-halo-fill: url(#knowledge-halo-gradient-4); --knowledge-nebula-fill: url(#knowledge-nebula-gradient-4); }
.knowledge-view [data-hue="5"] { --knowledge-tint: var(--knowledge-hue-5); --knowledge-node-fill: url(#knowledge-node-gradient-5); --knowledge-halo-fill: url(#knowledge-halo-gradient-5); --knowledge-nebula-fill: url(#knowledge-nebula-gradient-5); }
.knowledge-view [data-hue="6"] { --knowledge-tint: var(--knowledge-hue-6); --knowledge-node-fill: url(#knowledge-node-gradient-6); --knowledge-halo-fill: url(#knowledge-halo-gradient-6); --knowledge-nebula-fill: url(#knowledge-nebula-gradient-6); }
.knowledge-view [data-hue="7"] { --knowledge-tint: var(--knowledge-hue-7); --knowledge-node-fill: url(#knowledge-node-gradient-7); --knowledge-halo-fill: url(#knowledge-halo-gradient-7); --knowledge-nebula-fill: url(#knowledge-nebula-gradient-7); }

/* 그라데이션의 불투명도. 수는 토큰의 것이고 `<stop>`은 클래스로 그것을 읽는다. */
.knowledge-stop-halo-core { stop-opacity: var(--knowledge-halo-core); }
.knowledge-stop-nebula-core { stop-opacity: var(--knowledge-nebula-core); }
.knowledge-stop-fade { stop-opacity: 0; }

/* 주제의 원반과 그 이름 (성좌 배치, 09-16).
 *
 * 전체 지도의 첫 물음은 「어떤 주제들이 있는가」이므로, 그 답인 군집의 이름이
 * 그림 위에 선다 — 예전에는 `display: none`이라 범례에만 있었고, 범례는 점을
 * 보면서 읽을 수 없는 자리다. 원반은 평평한 색 한 겹과 테두리 한 올이다:
 * 빛 번짐은 글자와 선의 경계를 먹는다(사용자 조건).
 *
 * 주변 탐색(`is-local`)에서는 서지 않는다 — 그 화면의 주제는 중심 하나다. */
.knowledge-nebula {
  display: none;
  fill: var(--knowledge-nebula-fill, none);
  stroke: color-mix(in srgb, var(--knowledge-tint, var(--ink-mist)) var(--knowledge-nebula-edge-weight), transparent);
  stroke-width: var(--knowledge-nebula-edge-width);
  pointer-events: none;
  vector-effect: non-scaling-stroke;
  transition: opacity var(--motion-fast) var(--ease-standard);
}

.knowledge-picture:not(.is-local) .knowledge-nebula,
.knowledge-picture:not(.is-local) .knowledge-cluster-label {
  display: block;
}

.knowledge-cluster-label {
  display: none;
  cursor: pointer;
  transition: opacity var(--motion-fast) var(--ease-standard);
}

.knowledge-cluster-name {
  fill: var(--knowledge-tint, var(--ink-label));
  font-size: calc(var(--knowledge-cluster-label-px) * 1px);
  font-weight: 650;
  letter-spacing: var(--knowledge-cluster-label-tracking);
  dominant-baseline: middle;
  opacity: var(--knowledge-cluster-label-opacity);
  paint-order: stroke;
  stroke: var(--knowledge-ground);
  stroke-width: calc(var(--knowledge-label-outline-px) * 3px);
  stroke-linejoin: round;
}

/* 주제의 대표 지식 — 그 군집에서 연결이 가장 많은 쪽의 제목. 이름표 경쟁에
 * 맡기지 않고 주제의 이름 바로 아래 붙인다: 전체 지도의 약속이 「주제와 대표
 * 지식」이므로 그 둘은 함께 서야 한다. */
.knowledge-cluster-lead {
  fill: var(--ink-chalk);
  font-size: calc(var(--knowledge-cluster-count-px) * 1px);
  dominant-baseline: middle;
  paint-order: stroke;
  stroke: var(--knowledge-ground);
  stroke-width: calc(var(--knowledge-label-outline-px) * 3px);
  stroke-linejoin: round;
}

/* 좁은 판에서 이름판은 주제의 이름 한 줄이다 — 대표 지식과 쪽 수는 인스펙터와
 * 군집 범례가 계속 말한다(`placeKnowledgeLabels`가 같은 답으로 자리를 잡는다). */
.knowledge-picture.is-short-plate .knowledge-cluster-lead,
.knowledge-picture.is-short-plate .knowledge-cluster-count {
  display: none;
}

/* 「쪽 n · 이름 +m」 — 이 주제에 몇 쪽이 있고 그중 몇 개의 이름을 접었는가.
 * 접었다는 사실을 그림이 스스로 말한다(사용자 조건). */
.knowledge-cluster-count {
  fill: var(--ink-label);
  font-size: calc(var(--knowledge-cluster-count-px) * 1px);
  dominant-baseline: middle;
  paint-order: stroke;
  stroke: var(--knowledge-ground);
  stroke-width: calc(var(--knowledge-label-outline-px) * 2px);
  stroke-linejoin: round;
}

.knowledge-cluster-label:focus-visible {
  outline: var(--accent-rule) solid var(--ink-chalk);
  outline-offset: var(--knowledge-focus-offset);
}

.knowledge-picture.is-zoomed-in .knowledge-cluster-label {
  opacity: 0;
  pointer-events: none;
}

/* 좁은 판에서 자리를 못 얻은 이름판은 **지운다** — 투명한 글자도 페인트 목록에
 * 남고([[svg-inactive-halo-paint-cost]]), 무엇보다 읽히지 않는 글자가 자리를
 * 차지한 화면은 「표시량을 줄였다」고 말할 수 없다. */
.knowledge-picture .knowledge-cluster-label.is-folded {
  display: none;
}

/* 들어간 배율에서는 성운을 그리지 않는다 — 성운의 값은 넓이이고, 확대된 성운은
 * 화면 전체를 덮는 그라데이션이다(실측: 그런 성운 열아홉이 프레임을 265ms로).
 * `opacity: 0`이 아니라 `display: none`인 것은 [[svg-inactive-halo-paint-cost]]의
 * 같은 이유다: 투명한 원도 페인트 목록에 남는다. */
.knowledge-picture.is-zoomed-in .knowledge-nebula {
  display: none;
}

/* 점은 쥘 수 있다(3차). 쥐는 동안 판 전체가 그 손을 말한다. */
.knowledge-node {
  cursor: grab;
  transition: opacity var(--motion-fast) var(--ease-standard);
}

.knowledge-canvas.is-dragging,
.knowledge-canvas.is-dragging .knowledge-node {
  cursor: grabbing;
}

/* 도착(3차)은 CSS가 아니라 Web Animations다(`arriveKnowledgeLayers`): 클래스를 뗐다
 * 붙이는 재시작이 강제 레이아웃 읽기 하나를 요구했고, 그 읽기가 천 페이지에서
 * 점 페인트를 여섯 배로 만들었다. 시간은 여전히 `--knowledge-arrive`의 것이다. */

/* 모서리가 있는 모양(`KNOWLEDGE_SHAPES`)의 테두리는 둥글게 잇는다 — GL 손은 모양의 참
 * 거리로 테두리를 긋고, 그 바깥 모서리는 둥근 이음과 같은 곡선이다. 기본값(miter)이면
 * 삼각형의 꼭짓점에서 두 손의 테두리가 선 굵기만큼 갈린다. */
.knowledge-dot {
  fill: color-mix(in srgb, var(--ink-mist) var(--knowledge-node-muted-weight), var(--knowledge-tint, var(--ink-mist)));
  stroke: var(--knowledge-ground);
  stroke-width: var(--knowledge-node-stroke);
  stroke-linejoin: round;
  transition: fill var(--motion-fast) var(--ease-standard),
              stroke var(--motion-fast) var(--ease-standard);
}

.knowledge-halo {
  display: none;
  pointer-events: none;
}

/* 주제의 대표 페이지는 제 원반의 한가운데에 크게 앉고 고리 하나를 두른다 —
 * PNP 15쪽의 「큰 중심」이 우리 데이터에서 뜻하는 것은 「이 주제에서 가장 많이
 * 이어진 쪽」이다. 고리는 색이 아니라 모양이므로 색을 못 보는 눈에도 남는다. */
.knowledge-node[data-tier="core"] .knowledge-dot {
  fill: color-mix(in srgb, var(--knowledge-tint, var(--ink-mist)) 78%, var(--knowledge-ground));
  stroke: var(--knowledge-tint, var(--ink-mist));
  stroke-width: var(--knowledge-node-selected-stroke);
}

.knowledge-node[data-tier="major"] .knowledge-dot {
  fill: color-mix(in srgb, var(--knowledge-tint, var(--ink-mist)) 62%, var(--knowledge-ground));
}

/* 아직 쓰지 않은 페이지: 채우지 않은 점선 테두리. 형태로도 구분되므로 색을
 * 못 보는 눈에도 「없는 페이지」가 보인다(§8). */
.knowledge-node.is-ghost .knowledge-dot {
  fill: none;
  stroke: var(--signal-wait);
  stroke-dasharray: var(--knowledge-node-ghost-dash);
  stroke-width: var(--knowledge-node-ghost-stroke);
}

/* 활동 고리(t-2931): 창 안에서 회상된 점은 halo를 고리로 두른다 — 채움 없이
 * 선만이라 허브의 halo 원반과 겹쳐도 둘 다 읽힌다. 창의 길이는 백엔드의 표
 * (`live.limits`)가 정하고 여기는 옷뿐이다. 굵기는 화면 픽셀로 고정된다. */
.knowledge-node.is-recalled .knowledge-halo {
  display: block;
  fill: none;
  stroke: var(--knowledge-activity-ring);
  stroke-width: var(--knowledge-activity-ring-width);
  stroke-dasharray: var(--knowledge-activity-ring-dash);
  vector-effect: non-scaling-stroke;
}

/* 원본은 옅게, 그리고 마름모로(`KNOWLEDGE_NODE_SHAPES`). 지식이 아니라 지식이 나온 자리다. */
.knowledge-node.is-source .knowledge-dot {
  fill: color-mix(in srgb, var(--ink-mist) var(--knowledge-muted-ink-weight), transparent);
  stroke: color-mix(in srgb, var(--ink-mist) var(--knowledge-source-stroke-weight), transparent);
  stroke-width: 1;
  filter: none;
}

/* 공급망의 점(P4) — 구성요소 ■는 생태계의 잉크, 취약점 ▲는 심각도의 잉크.
 *
 * 잉크는 점의 묶음이 든 낱말(`data-ecosystem`·`data-severity`, `knowledgeSupplyDress`)이 변수로
 * 고르고, 점의 몸은 그 변수를 읽는 한 규칙이다 — 범례의 표본(`knowledge-legend-node`)도 같은 낱말을
 * 들어 같은 변수를 받는다. 멤버와 정보성 권고는 속이 옅고 테두리가 그 잉크다: 색이 아니라 모양의
 * 차이다. 규칙이 (0,3,0)이라 뒤의 상태 규칙(밝힘·고름·검색·경로)이 테두리를 순서대로 덮고, GL 손은
 * 같은 옷을 입힌 견본에서 이 값을 읽는다(`knowledgeGlPalette`). */
.knowledge-view [data-ecosystem="cargo"] { --knowledge-supply-ink: var(--knowledge-ecosystem-cargo); }
.knowledge-view [data-ecosystem="npm"] { --knowledge-supply-ink: var(--knowledge-ecosystem-npm); }
.knowledge-view [data-severity="critical"] { --knowledge-supply-ink: var(--knowledge-severity-critical); }
.knowledge-view [data-severity="high"] { --knowledge-supply-ink: var(--knowledge-severity-high); }
.knowledge-view [data-severity="medium"] { --knowledge-supply-ink: var(--knowledge-severity-medium); }
.knowledge-view [data-severity="low"] { --knowledge-supply-ink: var(--knowledge-severity-low); }
.knowledge-view [data-severity="none"] { --knowledge-supply-ink: var(--knowledge-severity-none); }
.knowledge-view [data-severity="unknown"] { --knowledge-supply-ink: var(--knowledge-severity-unknown); }

.knowledge-view [data-member="true"] {
  --knowledge-supply-fill-weight: var(--knowledge-member-fill-weight);
  --knowledge-supply-stroke: var(--knowledge-supply-ink);
  --knowledge-supply-stroke-width: var(--knowledge-member-stroke);
}

.knowledge-view [data-informational] {
  --knowledge-supply-fill-weight: var(--knowledge-informational-fill-weight);
  --knowledge-supply-stroke: var(--knowledge-supply-ink);
  --knowledge-supply-stroke-width: var(--knowledge-informational-stroke);
}

/* 코드 층의 점(t-5970) — 파일 ⬢과 정의 ✚는 제 잉크의 몸과 바탕의 테두리(구성요소의 점과 같은 옷).
 * 주변 탐색의 군집 색 규칙보다 한 단 무거운 짝으로 제 잉크를 지키는 것도 공급망의 점과 같다. GL
 * 손은 같은 옷을 입힌 견본에서 이 값을 읽고, 테두리 굵기는 같은 토큰이다(`knowledgeRestingNodeInk`). */
.knowledge-view .is-code_file { --knowledge-code-ink: var(--knowledge-code-file-ink); }
.knowledge-view .is-code_symbol { --knowledge-code-ink: var(--knowledge-code-symbol-ink); }
.knowledge-node.is-code_file .knowledge-dot,
.knowledge-node.is-code_symbol .knowledge-dot,
.knowledge-picture.is-local .knowledge-node.is-code_file:not(.is-ghost):not(.is-source) .knowledge-dot,
.knowledge-picture.is-local .knowledge-node.is-code_symbol:not(.is-ghost):not(.is-source) .knowledge-dot {
  fill: var(--knowledge-code-ink);
  stroke: var(--knowledge-ground);
  stroke-width: var(--knowledge-node-stroke);
  filter: none;
}

.knowledge-legend-node.is-code_file .knowledge-legend-ink,
.knowledge-legend-node.is-code_symbol .knowledge-legend-ink {
  fill: var(--knowledge-code-ink);
}

/* 주변 탐색의 점 규칙(`.is-local … :not(.is-ghost):not(.is-source)`, (0,6,0))은 페이지의 군집 색을
 * 입히는 규칙이라, 공급망의 점은 한 단 더 무거운 짝으로 제 잉크를 지킨다. */
.knowledge-node.is-component .knowledge-dot,
.knowledge-node.is-vulnerability .knowledge-dot,
.knowledge-picture.is-local .knowledge-node.is-component:not(.is-ghost):not(.is-source) .knowledge-dot,
.knowledge-picture.is-local .knowledge-node.is-vulnerability:not(.is-ghost):not(.is-source) .knowledge-dot {
  fill: color-mix(in srgb, var(--knowledge-supply-ink, var(--ink-mist)) var(--knowledge-supply-fill-weight, 100%), var(--knowledge-ground));
  stroke: var(--knowledge-supply-stroke, var(--knowledge-ground));
  stroke-width: var(--knowledge-supply-stroke-width, var(--knowledge-node-stroke));
}

.knowledge-label {
  fill: var(--ink-mist);
  font-size: calc(var(--knowledge-label-px) * 1px);
  paint-order: stroke;
  stroke: var(--knowledge-ground);
  stroke-width: calc(var(--knowledge-label-outline-px) * 1px);
  stroke-linejoin: round;
  pointer-events: none;
  transition: opacity var(--motion-fast) var(--ease-standard);
}

/* 라벨의 세 단(§3).
 *
 * 천 개의 제목을 한 화면에 겹쳐 쓰는 것은 하나도 읽히지 않게 하는 일이므로,
 * 배율이 낮을 때 서는 것은 허브뿐이고, 중간 문턱에서 연결이 둘 이상인 점이,
 * 높은 문턱에서 전부가 선다. 문턱 셋은 `--knowledge-lod-*`이고 어느 단인지는
 * 점이 제 `data-label-tier`로 들고 있다 — CSS가 차수를 셀 수는 없다. */
.knowledge-label {
  display: none;
}

/* 이름표가 서는 자리는 격자가 정한다(09-16, `placeKnowledgeLabels`).
 *
 * 3차의 차수 문턱 셋(`--knowledge-lod-*`)은 「몇 개가 서는가」만 정하고 「겹치는가」는
 * 묻지 않았다 — 실측(실제 볼트 412쪽, 1600×1000): 선 이름표 21개에 겹친 쌍 27,
 * 900×760에서는 118. 이제 이름은 화면 격자에 자리를 예약하고, 자리를 못 얻은
 * 이름은 접힌다. CSS는 그 답(`is-named`)을 입기만 한다. 접힌 허브의 「+N」은
 * 여전히 배율과 무관하게 선다 — 읽혀야 펼칠 수 있으므로. */
.knowledge-node.is-named .knowledge-label,
.knowledge-node[data-label-tier="hub"] .knowledge-label {
  display: block;
}

/* 위계는 글자에도 있다: 주제의 대표 페이지가 가장 또렷하고, 대표 지식이 그 다음,
 * 잎은 물러선다. 크기를 줄이는 대신 잉크를 옮긴다 — 작은 글자는 안 읽힌다. */
.knowledge-node[data-tier="core"] .knowledge-label {
  fill: var(--ink-chalk);
  font-weight: 600;
}

/* 아래가 막힌 이름표는 점 위에 선다(`placeKnowledgeLabels`). 자리는 격자가
 * 정하고 CSS는 그 답을 입는다 — 높이는 이름표의 글자 크기와 점의 반지름에서
 * 나오므로 어느 배율에서도 점에 붙어 있다. */
/* 이름표의 네 자리(아래·위·오른쪽·왼쪽)는 격자가 고르고, 그 자리는 x·y와
 * text-anchor로 쓰인다(`placeKnowledgeLabels`) — 점마다 반지름이 다르므로 옆자리의
 * 거리는 CSS가 알 수 없는 수다. 여기 남는 것은 그 자리가 정해지기 전의 기본값뿐. */


.knowledge-node[data-tier="major"] .knowledge-label {
  fill: var(--ink-chalk);
}

/* 짚은 것·고른 것·검색이 맞춘 것의 이름은 배율과 무관하게 선다 — 사람이 지금
 * 묻고 있는 바로 그 점의 이름이 배율 때문에 숨는 것은 답이 아니다. */
.knowledge-node.is-lit .knowledge-label,
.knowledge-node.is-selected .knowledge-label,
.knowledge-node.is-search-match .knowledge-label {
  display: block;
}

/* 본문 링크의 두 세기(09-16). 군집 안의 실은 제 주제의 색을 옅게 띠어 그 덩어리의
 * 모양을 그리고, 주제를 건너는 실은 더 옅은 중립색이다 — 주제 **사이**에서 읽혀야
 * 하는 것은 프론트매터가 이름을 준 관계이지 스쳐 지나간 대괄호가 아니다. 이름 있는
 * 관계(`is-typed`)는 아래에서 제 색과 굵기를 그대로 가져간다.
 *
 * 세기를 `opacity`가 아니라 **잉크**로 말하는 것이 요점이다: 불투명도는 상태의
 * 것이다(검색·슬라이서·경로가 물러선 선을 그것으로 말한다). 여기서 opacity를 쓰면
 * 밝힌 선도 흐린 선도 이 규칙에 묻힌다. */
.knowledge-picture:not(.is-local) .knowledge-edge.is-intra:not(.is-typed):not(.is-ghost):not(.is-merge) {
  --knowledge-edge-ink: color-mix(in srgb, var(--knowledge-tint, var(--ink-mist)) var(--knowledge-edge-intra-weight), transparent);
}

.knowledge-picture:not(.is-local) .knowledge-edge.is-inter:not(.is-typed):not(.is-ghost):not(.is-merge) {
  --knowledge-edge-ink: color-mix(in srgb, var(--ink-mist) var(--knowledge-edge-inter-weight), transparent);
}

.knowledge-edge {
  fill: none;
  stroke: var(--knowledge-edge-ink, var(--knowledge-edge-mentions-ink));
  stroke-width: var(--knowledge-edge-mentions-width);
  stroke-linecap: round;
  transition: stroke var(--motion-fast) var(--ease-standard),
              opacity var(--motion-fast) var(--ease-standard);
}

/* 프론트매터가 이름을 준 관계(`related`·`implements`·`depends_on`·
 * `supersedes`·`contradicts`)는 본문의 `[[위키링크]]`보다 무겁게 선다.
 * 방향이 있는 넷은 화살촉을 달고(`marker-end`, JS가 배선한다), `related`는
 * 무방향이라 달지 않는다 — 없는 방향을 그리는 화살표는 거짓말이다. */
.knowledge-edge.is-typed {
  stroke: var(--edge-mark);
  stroke-width: var(--knowledge-edge-typed-width);
  stroke-linecap: round;
}

.knowledge-edge.is-typed.kind-related {
  stroke: var(--knowledge-typed-related);
  /* 방향이 없는 가장 약한 타입 관계이고 가장 흔하다 — 온 잉크로는 그림 전체가
   * 이 선이었다(실제 볼트: 173 중 57). 밝은 동안(호버·포커스)만 온 잉크. */
  opacity: var(--knowledge-edge-related-opacity);
}

.knowledge-edge.is-lit.kind-related,
.knowledge-picture.is-focused .knowledge-edge.is-focus-lit.kind-related {
  opacity: 1;
}

.knowledge-edge.is-typed.kind-implements {
  stroke: var(--knowledge-typed-implements);
}

.knowledge-edge.is-typed.kind-depends_on {
  stroke: var(--knowledge-typed-depends-on);
  stroke-dasharray: var(--knowledge-edge-depends-dash);
}

.knowledge-edge.is-typed.kind-supersedes {
  stroke: var(--knowledge-typed-supersedes);
  stroke-dasharray: var(--knowledge-edge-supersedes-dash);
}

.knowledge-edge.is-typed.kind-contradicts {
  stroke: var(--knowledge-typed-contradicts);
  stroke-dasharray: var(--knowledge-edge-contradicts-dash);
}

/* 공급망의 `affects`(P4): 취약점 → 구성요소. 볼트가 선언한 관계가 아니라 SCA의 발견이지만 방향이
 * 있는 이름 있는 선이라 타입 관계의 문법(굵기·화살촉)을 그대로 입고, 잉크만 경보의 것이다. */
.knowledge-edge.is-typed.kind-affects {
  stroke: var(--knowledge-typed-affects);
}

/* merge 후보(t-2931): 볼트가 선언한 관계가 아니라 백엔드가 센 물음이라 타입
 * 관계의 잉크를 빌리지 않고, 점선으로 「이 둘이 하나인가」를 묻는다. */
.knowledge-edge.kind-merge {
  stroke: var(--knowledge-merge-ink);
  stroke-width: var(--knowledge-edge-merge-width);
  stroke-dasharray: var(--knowledge-edge-merge-dash);
}

/* 관계의 낱말은 밝은 선에만. JS가 그 층에 서는 <text>의 수를 이웃의 수로
 * 묶어 두므로, 여기서 하는 일은 읽히게 두는 것뿐이다. */
.knowledge-edge-label {
  fill: var(--ink-mist);
  font-size: calc(var(--knowledge-label-edge-px) * 1px);
  text-anchor: middle;
  paint-order: stroke;
  stroke: var(--knowledge-ground);
  stroke-width: var(--knowledge-edge-label-halo);
  stroke-linejoin: round;
  pointer-events: none;
}

/* 유령이 뒤에 서는 것은 순서가 뜻이기 때문이다: 「가리키는 페이지가 없다」는
 * 그 선이 무슨 관계인가보다 급한 사실이고, 타입 관계도 없는 페이지를 가리킬 수
 * 있다. 굵기는 위에서 얻은 것을 그대로 쓴다. */
.knowledge-edge.is-ghost {
  stroke: color-mix(in srgb, var(--signal-wait) var(--knowledge-muted-ink-weight), transparent);
  stroke-dasharray: var(--knowledge-edge-ghost-dash);
}

/* 한 점을 짚으면 그 이웃만 밝고 나머지는 물러선다. 흐리는 일은 판 하나에 붙은
 * 클래스가 하고, 밝히는 일만 이웃 수만큼의 쓰기다 — 천 개의 점에 클래스를
 * 쓰고 지우는 표면은 호버 하나에 프레임을 떨어뜨린다. */
.knowledge-picture.is-tracing .knowledge-node:not(.is-lit) {
  opacity: var(--knowledge-far-node-opacity);
}

.knowledge-picture.is-tracing .knowledge-edge:not(.is-lit) {
  stroke: color-mix(in srgb, var(--ink-mist) var(--knowledge-far-edge-ink-weight), transparent);
  opacity: var(--knowledge-far-edge-opacity);
}

/* 포커스와 검색은 **불투명도만** 물린다 — 잉크는 그대로 둔다.
 *
 * 호버의 흐림이 잉크를 바꾸는 것은 그것이 한 점을 짚는 짧은 몸짓이기 때문이고,
 * 포커스와 검색은 사람이 그 상태로 그림을 **읽는** 동안 켜져 있다. 그동안 점의
 * 색은 여전히 그 태그의 색이어야 한다: 색이 군집을 말하는 판에서 흐림이 색을
 * 갈아 치우면, 흐린 채로 읽는 사람은 군집을 하나도 읽지 못한다. 두 테마에서
 * 3:1을 재는 하네스도 이 잉크를 읽는다. */
.knowledge-picture.is-focused .knowledge-node:not(.is-focus-lit),
.knowledge-picture.is-searching .knowledge-node.is-search-dim,
.knowledge-picture.is-sliced .knowledge-node.is-slice-dim {
  opacity: var(--knowledge-dim-opacity);
}

.knowledge-picture.is-focused .knowledge-edge:not(.is-focus-lit),
.knowledge-picture.is-searching .knowledge-edge.is-search-dim,
.knowledge-picture.is-sliced .knowledge-edge.is-slice-dim {
  opacity: var(--knowledge-dim-edge-opacity);
}

.knowledge-node.is-search-match .knowledge-dot {
  stroke: var(--knowledge-highlight);
  stroke-width: var(--knowledge-node-match-stroke);
}

/* 밝힌 군집(3차)은 검색과 같은 손이다 — 불투명도만, 잉크는 그대로. 다른 군집의
 * 성운과 이름표도 물러선다. */
.knowledge-picture.is-spotlight .knowledge-node:not(.is-spotlit),
.knowledge-picture.is-spotlight .knowledge-nebula:not(.is-spotlit),
.knowledge-picture.is-spotlight .knowledge-cluster-label:not(.is-spotlit) {
  opacity: var(--knowledge-dim-opacity);
}

.knowledge-picture.is-spotlight .knowledge-edge:not(.is-spotlit) {
  opacity: var(--knowledge-dim-edge-opacity);
}

.knowledge-edge.is-lit,
.knowledge-picture.is-focused .knowledge-edge.is-focus-lit {
  stroke: var(--ink-mist);
  stroke-width: var(--knowledge-edge-lit-width);
}

/* 경로 — 경로의 점과 선만 밝고 나머지는 물러선다. 물러서는 옷은 판(`is-path`)의 규칙이고
 * 점·선마다 클래스를 쓰지 않는다(t-5966): 천 쪽에서 점 1,020개와 선 1,734개에 「흐림」을
 * 쓰고 지우는 것이 경로 하나에 프레임을 백 밀리초로 만들었다(실측 102 ms → 아래 규칙으로
 * 경로의 몫만 남긴다). 포커스·검색의 흐림과 같은 손이다. */
.knowledge-picture.is-path .knowledge-node:not(.is-path-lit) {
  opacity: var(--knowledge-dim-opacity);
}

.knowledge-picture.is-path .knowledge-edge:not(.is-path-lit) {
  opacity: var(--knowledge-dim-edge-opacity);
}

.knowledge-node.is-path-lit .knowledge-dot {
  stroke: var(--knowledge-highlight);
  stroke-width: var(--knowledge-node-selected-stroke);
}

.knowledge-node.is-path-lit .knowledge-label {
  display: block;
}

/* `.knowledge-edge`는 선의 <path> 자신이다 — 그 안의 `path`를 고르는 선택자는 아무것도
 * 고르지 못했다(K22). 판의 `is-path`를 함께 걸어 타입 관계의 잉크(0,3,0)와 포커스·
 * 검색의 옷보다 뒤에서 이긴다. */
.knowledge-picture.is-path .knowledge-edge.is-path-lit {
  stroke: var(--knowledge-highlight);
  stroke-width: var(--knowledge-edge-lit-width);
  opacity: 1;
}

.knowledge-inspector-chain {
  margin-top: var(--space-2);
  padding: var(--space-2);
  background: var(--surface-well);
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-sm);
  font-size: var(--text-xs);
}

.knowledge-chain-body {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-1);
  margin-top: var(--space-1);
  font-family: var(--font-mono);
}

.knowledge-chain-node {
  font-weight: 600;
  color: var(--ink-chalk);
}

.knowledge-chain-arrow {
  color: var(--ink-mist);
}

.knowledge-chain-rel {
  color: var(--nav-plane-ring);
  font-weight: 500;
}

/* 사슬의 홉마다 근거(t-5966 G3) — 관계 낱말 뒤의 작은 꼬리. */
.knowledge-chain-road {
  color: var(--ink-label);
  font-weight: 400;
}

/* 경로 묻기와 경로 목록(t-5966 G3). 입력은 설정의 옷, 단추는 렌즈 플래그의 옷을 입는다. */
.knowledge-path-ask {
  display: flex;
  gap: var(--space-1);
  margin-top: var(--space-2);
}

.knowledge-path-ask .knowledge-path-to {
  flex: 1 1 auto;
  min-width: 0;
}

.knowledge-path-note {
  margin: var(--space-1) 0 0;
  color: var(--ink-label);
}

.knowledge-path-list {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-1);
  margin-top: var(--space-1);
}

.knowledge-path-pick {
  font-family: var(--font-mono);
  font-size: var(--text-xs);
}

.knowledge-path-pick.is-active {
  color: var(--ink-chalk);
  border-color: var(--nav-plane-ring);
}

.knowledge-node.is-lit .knowledge-dot,
.knowledge-node.is-selected .knowledge-dot {
  stroke: var(--ink-chalk);
  stroke-width: var(--knowledge-node-selected-stroke);
}

.knowledge-zoom {
  position: absolute;
  bottom: var(--space-3);
  right: var(--space-3);
  display: flex;
  gap: var(--space-1);
  align-items: center;
  padding: var(--space-1);
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-sm);
  background: var(--knowledge-ground);
  z-index: 2;
}

.knowledge-zoom-label {
  min-width: var(--knowledge-zoom-label-min-width);
  color: var(--ink-label);
  font-size: var(--text-xs);
  font-variant-numeric: tabular-nums;
  text-align: center;
}

/* 범례 ————
 *
 * 캔버스 아래 한 줄. 자리도 문법도 에이전트 그래프의 띠와 같게 하는 것은 두
 * 그림이 한 창의 두 지도이기 때문이다 — 한쪽에서 배운 읽는 법이 다른 쪽에서도
 * 맞아야 한다. 태그의 다섯 색은 여기 다시 적지 않는다: 툴바의 태그 칩이 이미
 * 그 범례이고, 같은 것을 두 곳에 적으면 한 곳이 늦는다. */
/* 점의 모양과 선의 종류를 푸는 범례는 배율 상자의 「?」 뒤에 접혀 있다(시안 이식) — 모든
 * 티어에서. 그림 아래 늘 서 있던 띠는 첫 화면의 잡음이었고, 뜻은 열면 그대로다. 왼쪽
 * 아래에 늘 서는 것은 군집의 점 범례(`.knowledge-cluster-legend`)다. */
.knowledge-legend {
  position: absolute;
  right: var(--space-3);
  bottom: calc(var(--space-3) * 2 + var(--control-height, 28px));
  z-index: 2;
  display: none;
  flex: none;
  flex-direction: column;
  gap: var(--space-2);
  align-items: flex-start;
  max-width: min(var(--knowledge-legend-max-width), calc(100% - var(--space-3) * 2));
  padding: var(--space-2) var(--space-3);
  border: var(--rule-width) solid var(--edge-glint);
  border-radius: var(--radius);
  background: var(--surface-glass);
  backdrop-filter: var(--knowledge-glass-blur);
  -webkit-backdrop-filter: var(--knowledge-glass-blur);
  box-shadow: var(--shadow-soft);
}

.knowledge-legend.is-open {
  display: flex;
}

.knowledge-legend-toggle {
  display: inline-flex;
  position: static;
}

/* 범례의 모양 표본은 그림과 같은 기하를 같은 문(`knowledgeShapeInk`)으로 그린 작은
 * SVG다(`knowledgeLegendShape`) — 모양은 표가 정하고, 여기는 잉크만 입힌다. 선의 굵기와
 * 점선의 자는 표본 상자의 단위가 아니라 화면 픽셀이다(`vector-effect`). */
.knowledge-legend-node {
  flex: none;
  width: var(--knowledge-legend-node-px);
  height: var(--knowledge-legend-node-px);
  overflow: visible;
}

.knowledge-legend-ink {
  fill: var(--ink-mist);
  stroke: var(--ink-mist);
  stroke-width: var(--rule-width);
  stroke-linejoin: round;
  vector-effect: non-scaling-stroke;
}

.knowledge-legend-node.is-ghost .knowledge-legend-ink {
  fill: none;
  stroke: var(--signal-wait);
  stroke-dasharray: var(--knowledge-node-ghost-dash);
}

.knowledge-legend-node.is-source .knowledge-legend-ink {
  fill: color-mix(in srgb, var(--ink-mist) var(--knowledge-muted-ink-weight), transparent);
}

/* 회상된 점의 범례: 고리 — 캔버스의 halo 고리와 같은 잉크. */
.knowledge-legend-node.is-recalled .knowledge-legend-ink {
  fill: none;
  stroke: var(--knowledge-activity-ring);
  stroke-dasharray: var(--knowledge-activity-ring-dash);
}

.knowledge-legend-edge {
  width: var(--knowledge-legend-edge-px);
  height: 0;
  border-top: var(--knowledge-legend-edge-height) solid color-mix(in srgb, var(--ink-mist) var(--knowledge-legend-edge-weight), transparent);
}

.knowledge-legend-edge.kind-related { border-top-color: var(--knowledge-typed-related); }
.knowledge-legend-edge.kind-implements { border-top-color: var(--knowledge-typed-implements); }
.knowledge-legend-edge.kind-depends_on {
  border-top-color: var(--knowledge-typed-depends-on);
  border-top-style: dashed;
}
.knowledge-legend-edge.kind-supersedes {
  border-top-color: var(--knowledge-typed-supersedes);
  border-top-style: dashed;
}
.knowledge-legend-edge.kind-contradicts {
  border-top-color: var(--knowledge-typed-contradicts);
  border-top-style: dotted;
}
.knowledge-legend-edge.kind-merge {
  border-top-color: var(--knowledge-merge-ink);
  border-top-style: dashed;
}
.knowledge-legend-edge.kind-affects { border-top-color: var(--knowledge-typed-affects); }

/* 근거의 표본(t-5966): 새 잉크 없이 있는 표의 것으로 — 기계가 잰 선은 dedupe 물음의 점선,
 * 키가 선언한 선은 타입 관계의 잉크, 본문이 추론한 선은 본문 링크의 옅은 잉크. */
.knowledge-legend-edge.is-measured {
  border-top-color: var(--knowledge-merge-ink);
  border-top-style: dashed;
}
.knowledge-legend-edge.is-declared { border-top-color: var(--edge-mark); }
.knowledge-legend-edge.is-inferred { border-top-color: var(--knowledge-edge-mentions-ink); }

/* 근거 렌즈의 세 토글 — 다른 렌즈와 같은 세그먼트 컨트롤의 옷. */
.knowledge-provenance {
  display: flex;
  flex: none;
  gap: 0;
  overflow: hidden;
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-sm);
}

.knowledge-provenance-flag .knowledge-legend-edge {
  flex: none;
}

/* 공급망의 범례 표본(P4): 그림의 점과 같은 낱말(`data-ecosystem`·`data-member`·`data-severity`)을 들어
 * 같은 변수를 받는다 — 몸의 식은 캔버스의 점과 같고, 테두리만 표본의 자(화면 픽셀)다. */
.knowledge-legend-node.is-component .knowledge-legend-ink,
.knowledge-legend-node.is-vulnerability .knowledge-legend-ink {
  fill: color-mix(in srgb, var(--knowledge-supply-ink, var(--ink-mist)) var(--knowledge-supply-fill-weight, 100%), var(--knowledge-ground));
  stroke: var(--knowledge-supply-stroke, var(--knowledge-supply-ink, var(--ink-mist)));
}

.knowledge-legend-node[data-member="true"] .knowledge-legend-ink {
  stroke-width: calc(var(--knowledge-member-stroke) * 1px);
}

/* 인스펙터 ————
 *
 * 두 상태가 **함께** 서 있고 보이는 쪽만 바뀐다(`hidden`). 지웠다 다시 짓는
 * 갱신을 하지 않는 이유는 실측된 것이다 — 3a32c83c. */
.knowledge-inspector {
  display: flex;
  flex: none;
  flex-direction: column;
  gap: var(--space-4);
  padding: var(--knowledge-inspector-padding);
  overflow-y: auto;
  background: color-mix(in srgb, var(--surface-deck) var(--knowledge-inspector-veil-weight), transparent);
  backdrop-filter: var(--knowledge-inspector-blur);
  -webkit-backdrop-filter: var(--knowledge-inspector-blur);
  width: auto;
  max-height: var(--knowledge-inspector-max-height);
  min-height: var(--knowledge-inspector-stack-min-height);
  border-top: var(--rule-width) solid var(--edge-rule);
}

.knowledge-view.is-tier-wide .knowledge-inspector {
  width: var(--knowledge-inspector-width);
  max-height: none;
  min-height: 0;
  border-top: 0;
  border-left: var(--rule-width) solid var(--edge-rule);
}

.knowledge-inspector-title {
  margin: 0;
  font-family: var(--font-display);
  font-size: var(--text-lg);
  font-weight: var(--workbench-title-weight);
  letter-spacing: var(--workbench-title-tracking);
  line-height: var(--leading-body);
}

.knowledge-inspector-head {
  margin: 0;
  color: var(--ink-label);
  font-size: var(--text-xs);
  font-weight: 600;
}

/* A list's heading carries the rule that opens its chapter (t-3818) — the
 * overview is seven lists deep, and without it the lists run together. The
 * cluster line's inline head is a span and keeps its place in the row. */
h4.knowledge-inspector-head {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  margin-top: var(--space-2);
}

h4.knowledge-inspector-head::after {
  flex: 1;
  border-top: var(--rule-width) solid var(--edge-rule);
  content: "";
}

.knowledge-inspector-path,
.knowledge-inspector-folder,
.knowledge-inspector-tags,
.knowledge-inspector-excerpt,
.knowledge-backlinks,
.knowledge-modified {
  margin: 0;
  color: var(--ink-label);
  font-size: var(--text-xs);
  overflow-wrap: anywhere;
}

.knowledge-inspector-excerpt {
  color: var(--ink-chalk);
  line-height: var(--knowledge-prose-line-height);
}

.knowledge-inspector-path {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.knowledge-card > .knowledge-inspector-excerpt {
  margin-block: var(--space-2);
}

.knowledge-card > .knowledge-inspector-acts {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  margin-bottom: var(--space-3);
}

.knowledge-card > .knowledge-inspector-acts .btn {
  min-width: 0;
  height: auto;
  min-height: var(--control-height-sm);
  padding: var(--space-2);
  white-space: normal;
}

.knowledge-card > .knowledge-inspector-acts .knowledge-inspector-open {
  background: var(--workbench-tint);
  border-color: var(--edge-glint);
  color: var(--ink-chalk);
  transition:
    background-color var(--motion-fast) var(--ease-standard),
    border-color var(--motion-fast) var(--ease-standard),
    color var(--motion-fast) var(--ease-standard);
}

.knowledge-card > .knowledge-inspector-acts .knowledge-inspector-open:hover:not(:disabled) {
  background: var(--row-hover);
}

.knowledge-card > .knowledge-inspector-acts .knowledge-inspector-request {
  border-radius: var(--radius-sm);
}

.knowledge-overview-counts {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--space-1);
  margin: 0;
  font-size: var(--text-xs);
}

.knowledge-stat-tile {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
  padding: var(--space-2) var(--space-3);
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-md);
  background: linear-gradient(160deg, var(--workbench-tint), transparent 64%), var(--knowledge-stat-tile-bg);
}

.knowledge-stat-tile dt {
  color: var(--ink-label);
}

.knowledge-stat-tile dd {
  margin: 0;
  color: var(--ink-chalk);
  font-family: var(--font-display);
  font-size: var(--text-xl);
  font-weight: var(--workbench-title-weight);
  font-variant-numeric: tabular-nums;
  letter-spacing: var(--workbench-title-tracking);
  line-height: 1;
}

.knowledge-overview,
.knowledge-card {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  min-width: 0;
}

.knowledge-overview[hidden],
.knowledge-card[hidden] {
  display: none;
}

.knowledge-inspector-list {
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.knowledge-inspector-list li {
  display: flex;
  gap: var(--space-2);
  align-items: baseline;
  justify-content: space-between;
  font-size: var(--text-xs);
}

/* 관계 줄의 표식(t-4140 S4): 범례의 선 그대로, 이름 앞에. 화살표와 낱말은 글로 따로 선다. */
.knowledge-relation-mark {
  flex: none;
  align-self: center;
}

.knowledge-relation-dir {
  flex: none;
  color: var(--ink-label);
}

/* A long page title and a relation describe different things. Give each its
 * own line, so folded-hub metadata cannot push the page name off the card. */
.knowledge-inspector-list .knowledge-relation-row {
  display: grid;
  grid-template-columns: auto auto minmax(0, 1fr) auto;
  column-gap: var(--space-2);
  row-gap: var(--space-1);
  padding-block: var(--space-2);
  border-bottom: var(--rule-width) solid var(--edge-rule);
}

.knowledge-relation-row .knowledge-inspector-row {
  grid-column: 3 / -1;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  white-space: normal;
  overflow-wrap: anywhere;
  line-height: var(--leading-body);
}

.knowledge-relation-row .knowledge-inspector-note {
  grid-column: 3;
  min-width: 0;
  overflow-wrap: anywhere;
}

.knowledge-relation-row .knowledge-unfold {
  grid-column: 4;
  align-self: start;
}

/* 관계 키 뒤의 한 마디 — 그 키가 무엇을 뜻하는가(09-16). 키와 같은 줄에 흐르다가
 * 판이 좁아지면 아래로 내려간다: 「쉬운 말」이 먼저 잘리는 화면은 답이 아니다. */
/* 뜻을 단 관계 줄은 한 줄을 통째로 쓴다 — 일곱 개가 한 줄에 흐르면 어느 뜻이
 * 어느 키의 것인지 다시 알 수 없다. 점의 모양 넷은 짧으니 그대로 흐른다. */
.knowledge-legend-list li[data-edge-kind] {
  flex: 1 0 100%;
}

.knowledge-relation-why,
.knowledge-legend-why {
  color: var(--ink-label);
  overflow-wrap: anywhere;
}

.knowledge-relation-why::before,
.knowledge-legend-why::before {
  content: " · ";
}

/* 관계 줄의 근거 칩(t-5966) — 뜻 한 줄 뒤에 누가 썼는가. */
.knowledge-relation-provenance {
  color: var(--ink-label);
}

.knowledge-relation-provenance::before {
  content: " · ";
}

/* 인스펙터의 두 탭(S4). 옷은 에이전트 인스펙터의 것이고 여기는 자리뿐이다. */
.knowledge-inspector-tabs {
  margin: calc(-1 * var(--knowledge-inspector-padding)) calc(-1 * var(--knowledge-inspector-padding)) 0;
}

.knowledge-inspector-page,
.knowledge-inspector-activity {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  min-width: 0;
}

.knowledge-inspector-page[hidden],
.knowledge-inspector-activity[hidden],
.knowledge-activity-quiet[hidden] {
  display: none;
}

.knowledge-activity-quiet {
  margin: 0;
  color: var(--ink-label);
  font-size: var(--text-xs);
}

.knowledge-meter {
  position: relative;
  min-height: var(--knowledge-meter-row-height);
  padding-inline: var(--space-1);
  overflow: hidden;
  border-radius: var(--radius-xs);
}

.knowledge-meter::before {
  position: absolute;
  z-index: 0;
  top: 0;
  bottom: 0;
  left: 0;
  width: calc(var(--meter-fill) * 100%);
  border-radius: inherit;
  background: var(--knowledge-meter-ink);
  content: "";
  pointer-events: none;
}

.knowledge-meter > * {
  position: relative;
  z-index: 1;
}

.knowledge-inspector-row {
  flex: 1;
  min-width: 0;
  padding: 0;
  border: 0;
  background: none;
  color: var(--ink-chalk);
  font-size: var(--text-xs);
  text-align: left;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  cursor: pointer;
  transition:
    color var(--motion-fast) var(--ease-standard),
    text-decoration-color var(--motion-fast) var(--ease-standard);
}

.knowledge-inspector-row:hover,
.knowledge-inspector-row:focus-visible {
  color: var(--accent-ink, var(--ink-chalk));
  text-decoration: underline;
  outline: none;
}

/* 문이 없는 줄(건강 카드의 raw 항목): 수는 서되 손은 없다. */
.knowledge-inspector-row:disabled,
.knowledge-inspector-row:disabled:hover {
  color: var(--ink-chalk);
  text-decoration: none;
  cursor: default;
}

/* 켜진 줄(밝힌 군집·켜진 렌즈): 이 창의 다른 토글과 같은 옷. */
.knowledge-inspector-row.is-active {
  color: var(--ink-chalk);
  font-weight: 600;
}

/* 군집의 줄과 칩과 카드의 군집 단추는 제 색 점을 앞세운다(3차). 점 하나가 범례다 —
 * 캔버스의 성운과 같은 매핑에서 같은 색을 읽는다. */
.knowledge-cluster-row .knowledge-inspector-row::before,
.knowledge-cluster-press::before {
  display: inline-block;
  width: var(--knowledge-chip-dot);
  height: var(--knowledge-chip-dot);
  margin-right: var(--space-1);
  border-radius: 50%;
  background: var(--knowledge-tint, var(--ink-glyph));
  vertical-align: middle;
  content: "";
}

/* 색이 있는 줄의 막대는 그 색으로 — 군집의 줄, 그리고 군집의 색을 얻은 태그의 줄.
 * 막대의 길이는 답의 몫(`--meter-fill`) 그대로이고, 물드는 것은 군집의 색이다
 * (t-3818): 목록의 줄과 캔버스의 성운이 같은 매핑에서 같은 색을 읽는다. */
.knowledge-meter[data-hue]::before {
  background: color-mix(in srgb, var(--knowledge-tint, var(--ink-mist)) var(--knowledge-meter-tint-weight), transparent);
}

/* 볼트 건강(3차): 0인 줄은 조용하다 — 깨끗한 볼트는 네 줄이 모두 조용한 볼트다. */
.knowledge-health-row.is-clean .knowledge-inspector-row,
.knowledge-health-row.is-clean .knowledge-inspector-note {
  color: var(--ink-mist);
}

/* BUS LOG(t-2931): 줄마다 종류의 색 점 하나가 앞선다 — 군집 줄의 점과 같은
 * 문법이고, 종류의 잉크는 토큰 다섯이 든다. 페이지가 서 있지 않은 줄은 누를 수
 * 없어 낱말만 남는다. */
.knowledge-bus-row {
  --knowledge-bus-ink: var(--ink-mist);
}

/* 좌석 문 — 회상 줄과 「이 페이지를 본 작업」의 판 이름. 닫힌 판은 꺼진 채 이름만. */
.knowledge-seat {
  flex: none;
  max-width: 40%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.knowledge-seat:disabled {
  cursor: default;
  opacity: 0.6;
}

.knowledge-bus-row[data-bus-kind="created"] { --knowledge-bus-ink: var(--knowledge-bus-created); }
.knowledge-bus-row[data-bus-kind="updated"] { --knowledge-bus-ink: var(--knowledge-bus-updated); }
.knowledge-bus-row[data-bus-kind="linked"] { --knowledge-bus-ink: var(--knowledge-bus-linked); }
.knowledge-bus-row[data-bus-kind="recalled"] { --knowledge-bus-ink: var(--knowledge-bus-recalled); }
.knowledge-bus-row[data-bus-kind="ingested"] { --knowledge-bus-ink: var(--knowledge-bus-ingested); }

.knowledge-bus-row .knowledge-inspector-row::before {
  display: inline-block;
  width: var(--knowledge-chip-dot);
  height: var(--knowledge-chip-dot);
  margin-right: var(--space-1);
  border-radius: 50%;
  background: var(--knowledge-bus-ink);
  vertical-align: middle;
  content: "";
}

.knowledge-bus-row .knowledge-inspector-row:disabled {
  color: var(--ink-label);
  cursor: default;
  text-decoration: none;
}

.knowledge-health-row:not(.is-clean) .knowledge-inspector-note {
  color: var(--ink-chalk);
  font-weight: 600;
}

.knowledge-inspector-cluster {
  display: flex;
  gap: var(--space-2);
  align-items: baseline;
  margin: 0;
  font-size: var(--text-xs);
}

.knowledge-inspector-cluster[hidden] {
  display: none;
}

.knowledge-cluster-press {
  flex: none;
  color: var(--ink-chalk);
}

.knowledge-inspector-note,
.knowledge-relation-word {
  flex: none;
  color: var(--ink-label);
  font-size: var(--text-xs);
  font-variant-numeric: tabular-nums;
}

/* 포커스 깊이. 셋 중 하나라는 것이 이 위젯의 뜻이므로 라디오 그룹이고,
 * 켠 칸은 이 창의 다른 세그먼트와 같은 옷을 입는다. */
/* 연결 깊이의 줄(시안): 빵부스러기 아래 — 낱말, 세 단, 페이지 수. */
.knowledge-depth {
  position: absolute;
  top: calc(var(--space-3) + var(--control-height-sm) + var(--space-2));
  left: var(--space-4);
  z-index: 2;
  display: flex;
  gap: var(--space-1);
  align-items: center;
  max-width: calc(100% - var(--space-4) * 2);
  color: var(--ink-label);
  font-size: var(--text-xs);
}

.knowledge-depth[hidden] {
  display: none;
}

.knowledge-depth-word {
  margin-right: var(--space-1);
  white-space: nowrap;
}

.knowledge-depth-step {
  padding: 0 var(--space-2);
  font-size: var(--text-xs);
}

.knowledge-crumb-count {
  margin-left: var(--space-1);
}

/* 군집 범례(시안): 왼쪽 아래의 점과 이름. 점의 색은 군집의 색 규칙 하나에서 온다(`data-hue`). */
.knowledge-cluster-legend {
  position: absolute;
  left: var(--space-4);
  bottom: var(--space-3);
  z-index: 2;
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-1) var(--space-3);
  max-width: var(--knowledge-cluster-legend-max);
  color: var(--ink-label);
  font-size: var(--text-2xs);
}

.knowledge-cluster-legend[hidden] {
  display: none;
}

.knowledge-cluster-key {
  display: inline-flex;
  gap: var(--space-1);
  align-items: center;
  height: auto;
  padding: 0;
  border: 0;
  background: transparent;
  color: inherit;
  font-size: inherit;
  transition: color var(--motion-fast) var(--ease-standard);
}

.knowledge-cluster-key:hover,
.knowledge-cluster-key.is-active {
  color: var(--ink-chalk);
}

.knowledge-cluster-key:focus-visible {
  outline: var(--accent-rule) solid var(--ink-chalk);
  outline-offset: var(--knowledge-focus-offset);
}

.knowledge-cluster-dot {
  flex: none;
  width: var(--knowledge-chip-dot);
  height: var(--knowledge-chip-dot);
  border-radius: 50%;
  background: var(--knowledge-tint, var(--ink-mist));
}

.knowledge-depth-step.is-active,
.knowledge-mode-step.is-active {
  border-color: var(--edge-glint);
  background: var(--row-active);
  color: var(--ink-chalk);
}

/* ---- 「전체 지도 | 주변 탐색」 (t-4140) ----
 *
 * 토글은 머리의 세그먼트이고 눌린 쪽이 지금의 모드다(`aria-pressed`). 좁은 판은
 * 낱말을 접고 그림만 남긴다 — 이름은 `aria-label`이 든다. */
.knowledge-mode {
  display: flex;
  flex: none;
  gap: var(--space-1);
  align-items: center;
  padding: var(--knowledge-segment-pad);
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius);
  background: var(--surface-well);
}

.knowledge-mode-step {
  border-color: transparent;
  background: transparent;
}

.knowledge-view.is-toolbar-compact .knowledge-mode-step span,
.knowledge-view.is-tier-compact .knowledge-mode-step span,
.knowledge-view.is-tier-tiny .knowledge-mode-step span {
  display: none;
}

/* 가장 좁은 판(이름도 접히는 폭)에서는 토글이 서지 않는다 — 실측: 단추 하나(26px)가
 * 280px의 머리를 넘쳤다. 주변 탐색은 검색 후보의 「주변 탐색으로」·워크벤치의
 * 「연결 보기」·Esc로 여전히 닿고, 빵부스러기의 「전체 지도」가 돌아오는 문이다. */
.knowledge-view.is-tier-tiny .knowledge-mode {
  display: none;
}

/* 빵부스러기는 캔버스 위에 뜬다 — 배율 상자와 같은 자리, 반대쪽 모서리. */
/* 시안의 빵부스러기는 상자가 아니라 낱말이다: 「← 전체 지도 › 여기」가 그림 위에 그냥 선다. */
.knowledge-crumb {
  position: absolute;
  top: var(--space-3);
  left: var(--space-4);
  z-index: 2;
  display: flex;
  gap: var(--space-2);
  align-items: center;
  max-width: calc(100% - var(--space-4) * 2);
  color: var(--ink-label);
  font-size: var(--text-xs);
}

.knowledge-crumb-back,
.knowledge-crumb-root {
  padding: 0 var(--space-1);
  border-color: transparent;
  background: transparent;
  color: var(--ink-label);
  font-size: var(--text-xs);
  transition: color var(--motion-fast) var(--ease-standard);
}

.knowledge-crumb-back:hover,
.knowledge-crumb-root:hover {
  color: var(--ink-chalk);
}

.knowledge-crumb[hidden] {
  display: none;
}

.knowledge-crumb-here {
  overflow: hidden;
  color: var(--ink-chalk);
  font-weight: 600;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.knowledge-crumb-count {
  white-space: nowrap;
}

/* ---- 주변 탐색의 옷 (시안 이식) ----
 *
 * 승인된 시안의 차분함: 선은 가늘고 옅으며 중심의 바퀴살만 또렷하고, 점은 군집의 색으로
 * 평평하며, 중심은 크고 후광을 두르고, 이름표는 전부 선다. 전체 지도의 옷은 그대로다 —
 * 판의 `is-local`이 이 절을 켠다. 수는 전부 토큰(`--knowledge-centre-*`·`--knowledge-edge-local-*`). */
.knowledge-picture.is-local .knowledge-edge,
.knowledge-picture.is-local.is-focused .knowledge-edge.is-focus-lit {
  stroke-width: var(--knowledge-edge-local-width);
}

.knowledge-picture.is-local .knowledge-edge:not(.is-typed):not(.is-ghost):not(.kind-merge),
.knowledge-picture.is-local.is-focused .knowledge-edge.is-focus-lit:not(.is-typed):not(.is-ghost):not(.kind-merge) {
  stroke: var(--knowledge-edge-local-ink);
}

.knowledge-picture.is-local .knowledge-edge:not(.is-spoke),
.knowledge-picture.is-local.is-focused .knowledge-edge.is-focus-lit:not(.is-spoke) {
  opacity: var(--knowledge-edge-context-opacity);
}

.knowledge-picture.is-local .knowledge-edge.is-spoke,
.knowledge-picture.is-local.is-focused .knowledge-edge.is-focus-lit.is-spoke {
  opacity: var(--knowledge-edge-spoke-opacity);
}

.knowledge-picture.is-local.is-tracing .knowledge-edge.is-lit,
.knowledge-picture.is-local.is-path .knowledge-edge.is-path-lit {
  opacity: 1;
}

.knowledge-picture.is-local .knowledge-edge.is-spoke:not(.is-typed):not(.is-ghost):not(.kind-merge) {
  stroke: var(--knowledge-edge-spoke-ink);
}

.knowledge-picture.is-local .knowledge-edge.is-lit {
  stroke: var(--ink-mist);
  stroke-width: var(--knowledge-edge-lit-width);
}

.knowledge-picture.is-local .knowledge-node:not(.is-ghost):not(.is-source) .knowledge-dot {
  fill: var(--knowledge-tint, var(--ink-mist));
  stroke: var(--knowledge-ground);
  stroke-width: var(--knowledge-node-selected-stroke);
}

/* 중심: 큰 점과 후광. 원은 제 자리(0,0)에 앉아 있어 배율이 그대로 중심을 지킨다;
 * 선 굵기는 배율로 나눠 화면 픽셀을 지킨다. */
.knowledge-picture.is-local .knowledge-node.is-selected .knowledge-dot {
  transform: scale(var(--knowledge-centre-scale));
  fill: color-mix(in srgb, var(--knowledge-tint, var(--ink-mist)) var(--knowledge-centre-fill-weight), var(--knowledge-ground));
  stroke: var(--knowledge-tint, var(--ink-chalk));
  stroke-width: calc(var(--knowledge-node-selected-stroke) / var(--knowledge-centre-scale));
}

.knowledge-picture.is-local .knowledge-node.is-selected .knowledge-halo {
  display: block;
  transform: scale(var(--knowledge-centre-scale));
  fill: none;
  stroke: var(--knowledge-tint, var(--ink-mist));
  stroke-width: calc(var(--knowledge-node-stroke) / var(--knowledge-centre-scale));
  stroke-dasharray: none;
  opacity: var(--knowledge-centre-halo-opacity);
}

/* 주변 탐색도 격자의 답을 입는다(09-16). 고리가 이름표의 **자리**를 고르고
 * 격자가 **설지 말지**를 고른다 — 이웃 서른의 제목이 서로를 덮는 화면보다,
 * 스물다섯이 읽히는 화면이 낫다. 고른 점과 그 이웃은 언제나 선다(격자의 첫 줄). */
.knowledge-picture.is-local .knowledge-node.is-named .knowledge-label {
  display: block;
}

.knowledge-picture.is-local .knowledge-node.is-selected .knowledge-label {
  transform: translateY(var(--knowledge-centre-label-shift));
  fill: var(--ink-chalk);
  font-size: calc(var(--knowledge-label-px) * var(--knowledge-centre-label-scale) * 1px);
  font-weight: 500;
}

/* 둘째 고리는 물러서되 읽힌다 — 전체 지도의 흐림보다 옅게. */
.knowledge-picture.is-local.is-focused .knowledge-node:not(.is-focus-lit) {
  opacity: var(--knowledge-local-far-opacity);
}

.knowledge-picture.is-local.is-focused .knowledge-edge:not(.is-focus-lit):not(.is-lit):not(.is-path-lit) {
  opacity: var(--knowledge-edge-context-opacity);
}

/* 접힌 허브는 모양으로 말한다: 점선 고리와 이름표 뒤의 「+N」. 색은 여전히 군집의
 * 것이라 접힘을 색으로 읽을 필요가 없다. */
.knowledge-node.is-folded .knowledge-halo {
  display: block;
  fill: none;
  stroke: var(--ink-label);
  stroke-width: var(--knowledge-node-ghost-stroke);
  stroke-dasharray: var(--knowledge-node-ghost-dash);
  vector-effect: non-scaling-stroke;
}

.knowledge-fold {
  fill: var(--ink-label);
  font-weight: 600;
}

.knowledge-unfold {
  flex: none;
  padding: 0 var(--space-2);
  font-size: var(--text-xs);
}

/* 연결 만들기의 서식(t-4140 S5) — 카드 안의 정돈된 서브 카드. */
.knowledge-link-form {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  padding: var(--space-3);
  margin-top: var(--space-2);
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-sm);
  background: color-mix(in srgb, var(--surface-well) 70%, var(--surface-deck));
}

.knowledge-link-form[hidden],
.knowledge-inspector-link[hidden],
.knowledge-link-candidates[hidden] {
  display: none;
}

.knowledge-link-form h4.knowledge-inspector-head {
  margin: 0;
  color: var(--ink-chalk);
  font-size: var(--text-xs);
  font-weight: 600;
  letter-spacing: 0.01em;
}

.knowledge-link-form h4.knowledge-inspector-head::after {
  display: none;
}

.knowledge-link-target {
  width: 100%;
  min-width: 0;
  height: 28px;
  padding: 0 var(--space-2);
  appearance: none;
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-sm);
  background: var(--surface-well);
  color: var(--ink-chalk);
  font-family: inherit;
  font-size: var(--text-xs);
  box-sizing: border-box;
  transition: border-color var(--motion-fast) var(--ease-standard),
              background-color var(--motion-fast) var(--ease-standard);
}

.knowledge-link-target::placeholder {
  color: var(--ink-mist);
}

.knowledge-link-target:focus {
  border-color: var(--edge-glint);
  background: var(--surface-deck);
  outline: none;
}

.knowledge-link-candidates {
  max-height: 140px;
  overflow-y: auto;
  margin: 0;
  padding: 2px;
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-sm);
  background: var(--surface-deck);
  list-style: none;
}

.knowledge-link-kind {
  width: 100%;
  min-width: 0;
  height: 28px;
  padding: 0 calc(var(--space-2) + 16px) 0 var(--space-2);
  appearance: none;
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-sm);
  background-color: var(--surface-well);
  color: var(--ink-chalk);
  font-family: inherit;
  font-size: var(--text-xs);
  cursor: pointer;
  box-sizing: border-box;
  transition: border-color var(--motion-fast) var(--ease-standard);
}

.knowledge-link-kind:focus {
  border-color: var(--edge-glint);
  outline: none;
}

.knowledge-link-kind option {
  background: var(--surface-deck);
  color: var(--ink-chalk);
}

.knowledge-link-directions {
  display: flex;
  gap: 2px;
  padding: 2px;
  border: var(--rule-width) solid var(--edge-rule);
  border-radius: var(--radius-sm);
  background: var(--surface-well);
  box-sizing: border-box;
}

.knowledge-link-direction {
  flex: 1 1 0;
  min-width: 0;
  height: 24px;
  padding: 0 var(--space-1);
  border: 0;
  border-radius: var(--radius-xs);
  background: transparent;
  color: var(--ink-mist);
  font-family: inherit;
  font-size: var(--text-2xs);
  font-weight: 500;
  text-align: center;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  white-space: nowrap;
  transition: background-color var(--motion-fast) var(--ease-standard),
              color var(--motion-fast) var(--ease-standard);
}

.knowledge-link-direction:hover:not(.is-active) {
  color: var(--ink-chalk);
  background: color-mix(in srgb, var(--surface-deck) 60%, transparent);
}

.knowledge-link-direction.is-active,
.knowledge-link-direction[aria-checked="true"] {
  background: var(--surface-deck);
  color: var(--ink-chalk);
  font-weight: 600;
  box-shadow: var(--shadow-1);
}

.knowledge-link-preview {
  margin: 0;
  padding: var(--space-2);
  border-radius: var(--radius-sm);
  background: var(--surface-deck);
  border: var(--rule-width) solid color-mix(in srgb, var(--edge-rule) 60%, transparent);
  color: var(--ink-label);
  font-size: var(--text-2xs);
  line-height: var(--knowledge-prose-line-height);
  overflow-wrap: anywhere;
}

.knowledge-link-form .knowledge-inspector-acts {
  display: flex;
  justify-content: flex-end;
  gap: var(--space-2);
  margin-top: 2px;
}

.knowledge-link-form .knowledge-link-save,
.knowledge-link-form .knowledge-link-cancel {
  height: 26px;
  padding: 0 var(--space-3);
  font-size: var(--text-xs);
  border-radius: var(--radius-sm);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition:
    background-color var(--motion-fast) var(--ease-standard),
    border-color var(--motion-fast) var(--ease-standard),
    color var(--motion-fast) var(--ease-standard),
    opacity var(--motion-fast) var(--ease-standard);
}

.knowledge-link-form .knowledge-link-cancel {
  background: transparent;
  border: var(--rule-width) solid var(--edge-rule);
  color: var(--ink-label);
}

.knowledge-link-form .knowledge-link-cancel:hover {
  background: var(--row-hover);
  color: var(--ink-chalk);
}

.knowledge-link-form .knowledge-link-save:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.knowledge-inspector-link.is-active {
  border-color: var(--edge-glint);
  background: var(--row-active);
  color: var(--ink-chalk);
}

/* 잇는 손(Alt+드래그) 아래의 판. */
.knowledge-canvas.is-linking,
.knowledge-canvas.is-linking .knowledge-node {
  cursor: crosshair;
}

/* 새 손잡이의 포커스 링(t-4140 S7) — 캔버스·검색 상자·목록 줄과 같은 링. 색만이
 * 포커스를 말하지 않는다: 바깥선 하나가 어느 판에서도 선다. */
.knowledge-mode-step:focus-visible,
.knowledge-crumb-back:focus-visible,
.knowledge-crumb-root:focus-visible,
.knowledge-candidate:focus-visible,
.knowledge-candidate-explore:focus-visible,
.knowledge-unfold:focus-visible,
.knowledge-link-direction:focus-visible,
.knowledge-link-target:focus-visible,
.knowledge-link-kind:focus-visible,
.knowledge-link-save:focus-visible,
.knowledge-link-cancel:focus-visible,
.knowledge-inspector-link:focus-visible {
  outline: var(--accent-rule) solid var(--ink-chalk);
  outline-offset: var(--knowledge-focus-offset);
}

.knowledge-inspector-acts {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
}

.knowledge-inspector-open[hidden],
.knowledge-overview-clusters[hidden],
.knowledge-inspector-folder[hidden],
.knowledge-inspector-tags[hidden],
.knowledge-inspector-excerpt[hidden],
.knowledge-modified[hidden],
.knowledge-relations-outgoing[hidden],
.knowledge-relations-incoming[hidden] {
  display: none;
}

/* 빈 볼트의 한 문장과 한 단추. 판 가운데에 서는 것은 이것이 고장이 아니라
 * 시작이라는 말이기 때문이다 — 「아직 아무것도 없다」와 「무언가 깨졌다」를
 * 같은 화면으로 말하지 않는다. */
.knowledge-empty {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  place-content: center;
  align-items: center;
  padding: var(--space-5);
  text-align: center;
  pointer-events: none;
}

.knowledge-empty-word {
  max-width: var(--knowledge-empty-measure);
  margin: 0;
  color: var(--ink-label);
  font-size: var(--text-sm);
  line-height: var(--knowledge-prose-line-height);
}

.knowledge-empty-act {
  pointer-events: auto;
}

.knowledge-error {
  position: absolute;
  top: var(--space-3);
  left: 50%;
  max-width: var(--knowledge-error-measure);
  margin: 0;
  padding: var(--space-2) var(--space-3);
  transform: translateX(-50%);
  border: var(--rule-width) solid color-mix(in srgb, var(--signal-halt) var(--knowledge-error-edge-weight), transparent);
  border-radius: var(--radius);
  background: var(--surface-glass);
  color: var(--signal-halt);
  font-size: var(--text-xs);
}

/* 배치와 카메라의 움직임뿐 아니라 상태 전이도 줄인다. */
@media (prefers-reduced-motion: reduce) {
  .knowledge-query,
  .knowledge-node,
  .knowledge-dot,
  .knowledge-label,
  .knowledge-edge,
  .knowledge-chip,
  .knowledge-mode-step,
  .knowledge-candidate,
  .knowledge-search-results li,
  .knowledge-crumb,
  .knowledge-crumb-back,
  .knowledge-crumb-root,
  .knowledge-cluster-key,
  .knowledge-nebula,
  .knowledge-cluster-label {
    transition: none;
  }
}

/* On-demand integration facts share the inspector's available width. */
.zo-integration { min-width: 0; max-width: 100%; color: var(--ink-mist); }
.zo-integration summary { cursor: pointer; overflow-wrap: anywhere; }
.zo-integration-body { min-width: 0; overflow-wrap: anywhere; }
.zo-integration-body p { white-space: pre-wrap; }
.zo-integration-body input { display: block; width: 100%; min-width: 0; box-sizing: border-box; }
.zo-integration-body button { max-width: 100%; white-space: normal; }
/* Skills document: one keyed list;
  narrow panes stack the same detail node. */
/* ---- Jev dashboard (t-5807) — the seats' numbers, decisions and trend.
   Geometry from tokens.css (--jev-*); colours from the semantic palette. */
.jev-view {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
  min-width: 0;
  height: 100%;
  padding: var(--space-5);
  overflow: auto;
  color: var(--ink-chalk);
  background: var(--surface-deck);
  font-size: var(--jev-body-size);
}

.jev-view[hidden], .jev-view [hidden] {
  display: none !important;
}

.jev-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: var(--space-3);
  flex-wrap: wrap;
}

.jev-title {
  font-size: var(--jev-title-size);
  margin: var(--space-1) 0;
}

.jev-eyebrow, .jev-about, .jev-freshness, .jev-bound,
.jev-decision-when, .jev-decision-marks, .jev-recent-empty {
  color: var(--ink-mist);
  font-size: var(--jev-meta-size);
  margin: 0;
}

.jev-actions {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  flex-wrap: wrap;
}

.jev-status, .jev-error {
  margin: 0;
}

/* A feature's row opens its drawer (t-6277 D6): the name is the button, and
   the whole row answers a pointer. */
.jev-table tbody tr[data-jev-dash-row] {
  cursor: pointer;
}

.jev-table tbody tr[data-jev-dash-row] td {
  transition: background-color var(--motion-fast) var(--ease-standard);
}

.jev-table tbody tr[data-jev-dash-row]:hover td {
  background: var(--row-hover);
}

.jev-table tbody tr.is-open td {
  background: color-mix(in srgb, var(--jev-progress-ink) var(--jev-tint-open), transparent);
}

.jev-row-open {
  display: block;
  padding: 0;
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}

/* The feature's id under its name, small (t-6277 D7): the word its settings
   key and its ledger rows are found by. */
.jev-row-id {
  display: block;
  color: var(--ink-mist);
  font-family: var(--font-mono);
  font-size: var(--jev-meta-size);
  font-weight: var(--jev-weight-plain);
}

/* The drawer rides a dock pinned to the top of the page's window, so it
   stays where the eye is while the table scrolls under it; the dock takes
   no room of its own. A sticky inset is read inside the page's padding, so
   the dock sticks where it starts, and the drawer reaches back over the
   padding to the page's own edges. */
.jev-drawer-dock {
  position: sticky;
  top: 0;
  z-index: 4;
  height: 0;
  margin-block-end: calc(-1 * var(--space-4));
}

.jev-drawer {
  position: absolute;
  top: calc(-1 * var(--space-5));
  right: calc(-1 * var(--space-5));
  width: min(var(--jev-drawer-width), calc(100% + var(--space-5)));
  height: var(--jev-drawer-height, 70vh);
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  padding: var(--space-4);
  overflow: auto;
  border-left: var(--jev-line) solid var(--edge-rule);
  background: var(--surface-deck);
  box-shadow: var(--shadow-2);
}

.jev-drawer-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: var(--space-3);
}

.jev-drawer-title {
  margin: 0;
  font-size: var(--jev-drawer-title-size);
}

.jev-drawer-id {
  margin: var(--space-1) 0 0;
  color: var(--ink-mist);
  font-family: var(--font-mono);
  font-size: var(--jev-meta-size);
}

.jev-drawer-summary, .jev-drawer-written, .jev-drawer-text {
  margin: 0;
  line-height: var(--leading-body);
}

.jev-drawer-written {
  color: var(--jev-tone-under);
  font-size: var(--jev-meta-size);
}

.jev-drawer-part {
  display: grid;
  gap: var(--space-2);
}

.jev-drawer-heading {
  margin: 0;
  color: var(--ink-mist);
  font-size: var(--jev-meta-size);
  font-weight: var(--jev-weight-strong);
}

.jev-drawer-facts {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: var(--space-1) var(--space-3);
  margin: 0;
}

.jev-drawer-facts dt {
  color: var(--ink-mist);
}

.jev-drawer-facts dd {
  margin: 0;
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.jev-drawer-text {
  color: var(--ink-mist);
  font-size: var(--jev-meta-size);
}

/* The settings card's switch, worn over the table (§6.1): the same framed
   row and the same line under it, standing at the page's edges as the strip
   and the table do. The row's frame is the one frame — a panel around it
   would be a box around a box (t-6277 D10). */
.jev-switch {
  display: grid;
  gap: var(--space-2);
}

.jev-switch .settings-jev-switch,
.jev-switch .settings-notice {
  margin: 0;
}

.jev-error {
  color: var(--signal-halt);
}

/* The strip over the table (t-6243 D1): the week's sums, how many features
   stand where, and the day's requests against the limit. */
.jev-summary {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  margin: 0;
}

.jev-stat {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
  min-width: var(--jev-stat-min);
  padding: var(--space-2) var(--space-3);
  border: var(--jev-line) solid var(--edge-rule);
  border-radius: var(--radius-md);
  background: var(--surface-well);
}

/* The figure is what the strip is read for: large; its label small and quiet
   above it (t-6277 D10). */
.jev-stat dt {
  display: flex;
  align-items: center;
  gap: var(--space-1);
  color: var(--ink-mist);
  font-size: var(--jev-stat-label-size);
}

.jev-stat dd {
  margin: 0;
  font-size: var(--jev-stat-size);
  font-weight: var(--jev-weight-strong);
  line-height: var(--leading-tight);
  font-variant-numeric: tabular-nums;
}

/* The states start a group of their own after the sums. */
.jev-stat[data-group="states"] {
  background: var(--surface-deck);
}

.jev-stat.jev-stat--lead {
  margin-inline-start: var(--space-3);
}

/* A state's count wears the state's tone — the tone its rows wear. */
.jev-stat[data-status] dt::before {
  content: "";
  flex: none;
  width: var(--jev-tone-dot);
  height: var(--jev-tone-dot);
  border-radius: 50%;
  background: var(--jev-tone);
}

.jev-view [data-status="applying"] { --jev-tone: var(--jev-tone-applying); }
.jev-view [data-status="recording"] { --jev-tone: var(--jev-tone-recording); }
.jev-view [data-status="under"] { --jev-tone: var(--jev-tone-under); }
.jev-view [data-status="blocked"] { --jev-tone: var(--jev-tone-blocked); }
.jev-view [data-status="dormant"] { --jev-tone: var(--jev-tone-dormant); }

/* What the table says when no feature was asked all week (t-6277 D10):
   whether Jev is off, or on and quiet. */
.jev-empty-row td {
  padding: var(--space-4) var(--jev-cell-pad);
  color: var(--ink-mist);
  text-align: center;
}

/* The row the unused features fold into: one line, one press. */
.jev-fold-row td {
  padding: 0;
}

.jev-fold {
  width: 100%;
  padding: var(--space-2);
  border: 0;
  background: none;
  color: var(--ink-mist);
  font: inherit;
  font-size: var(--jev-meta-size);
  text-align: left;
  cursor: pointer;
  transition:
    background-color var(--motion-fast) var(--ease-standard),
    color var(--motion-fast) var(--ease-standard);
}

.jev-fold:hover {
  color: var(--ink-chalk);
  background: var(--row-hover);
}

/* The table takes its own height and the view scrolls as one page; a table
   scrolling inside a page that also scrolls is two scrollbars for one list. */
.jev-table-wrap {
  flex: none;
  /* Clipped, not scrolled: a wrap that scrolls sideways is a scroll
     container, and the head could then stick only inside it — which never
     scrolls down. The table fits a 1080p stage (t-6243 D1), so nothing is
     lost to the clip, and the head sticks to the page (t-6277 D10). */
  overflow-x: clip;
  border: var(--jev-line) solid var(--edge-rule);
  border-radius: var(--radius-md);
}

.jev-table {
  border-collapse: collapse;
  width: 100%;
  font-variant-numeric: tabular-nums;
}

.jev-table th, .jev-table td {
  padding: var(--jev-cell-pad);
  line-height: var(--jev-cell-leading);
  text-align: left;
  vertical-align: top;
  border-bottom: var(--jev-line) solid var(--edge-rule);
}

/* The counted cells stay on one line; the words wrap — a feature's name and
   the response time's slow figure among them, which take a second line
   rather than push the table past a 1080p stage (t-6243 D1/D2). */
.jev-table [data-jev-cell="rows"], .jev-table [data-jev-cell="answered"],
.jev-table [data-jev-cell="acted"], .jev-table [data-jev-cell="cost"] {
  white-space: nowrap;
  min-width: var(--jev-cell-min);
}

.jev-table [data-jev-cell="seat"] {
  min-width: var(--jev-name-min);
}

/* The rate's lower bound sits under the rate, small. */
.jev-table .jev-bound {
  display: block;
}

.jev-fact-strong {
  font-weight: var(--jev-weight-strong);
}

.jev-fact-mist {
  color: var(--ink-mist);
  font-size: var(--jev-meta-size);
}

/* The head stays at the page's top edge while the rows scroll under it: a
   sticky inset is read inside the page's padding, so it reaches back over
   it (t-6277 D10). */
.jev-table th {
  color: var(--ink-mist);
  font-weight: var(--jev-weight-medium);
  font-size: var(--jev-meta-size);
  background: var(--surface-well);
  position: sticky;
  top: calc(-1 * var(--space-5));
  z-index: 2;
}

.jev-table tbody tr:last-child td {
  border-bottom: 0;
}

.jev-table tr.is-quiet td {
  color: var(--ink-mist);
}

.jev-table tr.is-applying [data-jev-cell="seat"] {
  font-weight: var(--jev-weight-strong);
}

.jev-share {
  font-weight: var(--jev-weight-strong);
}

/* The week as one picture of two lines, each line's latest value under it,
   marked the way its line is drawn (t-6243 D4). */
.jev-trends {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  color: var(--ink-mist);
  font-size: var(--jev-meta-size);
}

/* Beside the picture, one line per line of it — the row keeps its height. */
.jev-trend-legend {
  display: grid;
}

.jev-trend-last {
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
  white-space: nowrap;
}

.jev-trend-last::before {
  content: "";
  width: var(--space-3);
  border-top: var(--jev-trend-stroke) solid var(--jev-trend);
}

.jev-trend-agreement::before {
  border-top-style: dashed;
  border-top-color: var(--jev-trend-accuracy);
}

.jev-table [data-jev-cell="status"] {
  min-width: var(--jev-status-width);
  font-size: var(--jev-meta-size);
}

/* The model the table's judgments come from, named once over it. */
.jev-caption {
  caption-side: top;
  padding: var(--space-2);
  text-align: left;
  color: var(--ink-mist);
  font-size: var(--jev-meta-size);
}

/* A feature's state (t-6243 D2): the chip in its state's tone, one sentence
   of why, the samples still owed, and any fact beside them. */
.jev-status {
  display: grid;
  justify-items: start;
  gap: var(--space-1);
}

/* The chip, the samples still owed and the sentence start on one line; the
   sentence takes the width left beside them and wraps inside it. */
.jev-status-lead {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-1) var(--space-2);
}

.jev-status-lead .jev-status-reason {
  flex: 1 1 var(--jev-reason-min);
  min-width: 0;
}

.jev-chip {
  display: inline-flex;
  align-items: center;
  padding: var(--jev-chip-pad-block) var(--space-2);
  border-radius: var(--radius-pill);
  background: color-mix(in srgb, var(--jev-tone) var(--jev-tint), transparent);
  color: var(--jev-tone);
  font-weight: var(--jev-weight-strong);
  white-space: nowrap;
}

/* A light tint keeps the chip's ink at AA on the light panel, as the
   settings card's state pill does. */
:root[data-theme="light"] .jev-chip {
  background: color-mix(in srgb, var(--jev-tone) var(--jev-tint-quiet), transparent);
}

/* A feature that asks nothing says so in words alone. */
.jev-chip[data-status="dormant"] {
  padding-inline: 0;
  background: none;
  font-weight: var(--jev-weight-medium);
}

.jev-status-reason, .jev-status-fact {
  margin: 0;
}

/* A recording feature measured under its bar says why in the tone of a miss
   (t-6277 D8): the chip stays one of four, the sentence carries the rest. */
.jev-status-reason.is-under {
  color: var(--jev-tone-under);
}

.jev-status-fact {
  color: var(--ink-mist);
}

.jev-owed {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  color: var(--ink-mist);
}

.jev-progress {
  position: relative;
  flex: none;
  width: var(--jev-progress-width);
  height: var(--jev-progress-height);
  border-radius: var(--radius-pill);
  background: color-mix(in srgb, var(--ink-mist) var(--jev-tint-track), transparent);
  overflow: hidden;
}

.jev-progress-fill {
  position: absolute;
  inset: 0 auto 0 0;
  width: calc(var(--jev-filled, 0) * 100%);
  background: var(--jev-progress-ink);
}

/* A lower bound under the line for acting by itself wears the tone of a
   feature under its bar. */
.jev-bound.is-under {
  color: var(--jev-tone-under);
}

/* A sample too small for a share says its size quietly; a feature the door
   refused throughout says so in the tone of one waiting on a person
   (t-6243 D3). */
.jev-sample {
  color: var(--ink-mist);
}

.jev-refused {
  color: var(--jev-tone-blocked);
  font-weight: var(--jev-weight-strong);
}

/* What did not come back, by token (t-6243 D5): a quiet word for the wire's
   misses, and a button in the tone of a feature waiting on a person for the
   ones a person clears. */
.jev-tokens {
  display: flex;
  flex-wrap: wrap;
  gap: 0 var(--space-1);
  white-space: normal;
}

/* One text line tall, so a row of them costs a line and not a box. A word
   starts where the count above it starts; a button's tint is what lines up,
   so its words sit inside it (t-6277 D10). */
.jev-token {
  display: inline-flex;
  align-items: center;
  padding: 0;
  border: 0;
  border-radius: var(--radius-sm);
  background: none;
  color: var(--ink-mist);
  font: inherit;
  font-size: var(--jev-meta-size);
  line-height: var(--jev-token-line);
  white-space: nowrap;
}

button.jev-token {
  padding-inline: var(--space-1);
  background: color-mix(in srgb, var(--jev-tone-blocked) var(--jev-tint), transparent);
  color: var(--jev-tone-blocked);
  cursor: pointer;
  transition:
    background-color var(--motion-fast) var(--ease-standard),
    color var(--motion-fast) var(--ease-standard);
}

button.jev-token:hover {
  background: color-mix(in srgb, var(--jev-tone-blocked) var(--jev-tint-hover), transparent);
}

.jev-spark {
  width: var(--jev-spark-width);
  height: var(--jev-spark-height);
  overflow: visible;
}

.jev-spark-line {
  fill: none;
  stroke: var(--jev-trend);
  stroke-width: var(--jev-trend-stroke);
  stroke-linejoin: round;
  stroke-linecap: round;
}

.jev-spark-dot {
  fill: var(--jev-trend);
}

.jev-spark-agreement .jev-spark-line {
  stroke: var(--jev-trend-accuracy);
  stroke-dasharray: var(--jev-trend-dash);
}

.jev-spark-agreement .jev-spark-dot {
  fill: var(--jev-trend-accuracy);
}

.jev-recent-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
}

/* One judgment in the drawer's width: when, what became of it and its
   marks on the first line; what it was asked, then what it answered, under
   them. */
.jev-decision {
  display: grid;
  grid-template-columns: auto auto minmax(0, 1fr);
  grid-template-areas:
    "when outcome marks"
    "asked asked asked"
    "answer answer answer";
  gap: var(--space-1) var(--space-2);
  align-items: baseline;
  padding: var(--space-2) var(--space-3);
  border: var(--jev-line) solid var(--edge-rule);
  border-radius: var(--radius-sm);
}

.jev-decision-when { grid-area: when; }
.jev-decision-outcome { grid-area: outcome; }
.jev-decision-marks { grid-area: marks; text-align: right; }
.jev-decision-asked { grid-area: asked; }
.jev-decision-answer { grid-area: answer; }

.jev-decision-outcome {
  font-weight: var(--jev-weight-strong);
}

.jev-decision[data-outcome]:not([data-outcome="answered"]) .jev-decision-outcome {
  color: var(--signal-halt);
}

/* The facts wrap rather than cut: a line a person cannot finish reading is
   a line that says less than the row does. */
.jev-decision-asked, .jev-decision-answer {
  min-width: 0;
  overflow-wrap: anywhere;
}

.skills-view {
